LABELS = (
    "row sums",
    "first elements",
    "row maxima",
    "positive rows",
    "even values",
    "first row abs",
    "row has zero",
    "row lengths",
)


def validate_grid(grid):
    """Raise an informative error unless *grid* is a rectangle-free grid of ints."""
    if not isinstance(grid, list):
        raise TypeError("grid must be a list of lists")
    non_lists = [index for index, row in enumerate(grid) if not isinstance(row, list)]
    if non_lists:
        raise TypeError(f"rows at {non_lists} are not lists")
    empty = [index for index, row in enumerate(grid) if not row]
    if empty:
        raise ValueError(f"rows at {empty} are empty")
    bad_cells = [
        (r, c)
        for r, row in enumerate(grid)
        for c, value in enumerate(row)
        if not isinstance(value, int) or isinstance(value, bool)
    ]
    if bad_cells:
        raise TypeError(f"non-integer cells at {bad_cells}")


def analyze(grid):
    """Extract eight derived lists from a grid of integers."""
    validate_grid(grid)
    row_sums = [sum(row) for row in grid]
    first_elements = [row[0] for row in grid]
    row_maxima = [max(row) for row in grid]
    positive_rows = [row for row in grid if all(value > 0 for value in row)]
    even_values = [value for row in grid for value in row if value % 2 == 0]
    first_row_abs = [abs(value) for value in (grid[0] if grid else [])]
    row_has_zero = [0 in row for row in grid]
    row_lengths = [len(row) for row in grid]
    return (
        row_sums,
        first_elements,
        row_maxima,
        positive_rows,
        even_values,
        first_row_abs,
        row_has_zero,
        row_lengths,
    )


def format_report(grid):
    """Render the eight extracted lists of *grid* as aligned text lines."""
    results = analyze(grid)
    lines = [f"  {label:<14}: {values}" for label, values in zip(LABELS, results)]
    return "\n".join(lines)


def summarize(grids):
    """Render one summary line per grid with its overall total and even count."""
    reports = [analyze(grid) for grid in grids]
    totals = [sum(report[0]) for report in reports]
    even_counts = [len(report[4]) for report in reports]
    lines = [
        f"grid {number}: total={total}, evens={evens}"
        for number, (total, evens) in enumerate(zip(totals, even_counts), 1)
    ]
    return "\n".join(lines)


def main():
    grids = [
        [[1, 0], [4, 5]],
        [[3, -2, 4], [7, 8, 9], [0, 0, 1]],
    ]
    for number, grid in enumerate(grids, 1):
        print(f"grid {number} = {grid}")
        print(format_report(grid))
    print(summarize(grids))


if __name__ == "__main__":
    main()

