"""Log parsing helpers: split raw log lines into eight derived views."""


def _validate(logs):
    if not isinstance(logs, list):
        raise TypeError("logs must be a list of strings")
    offenders = [index for index, entry in enumerate(logs) if not isinstance(entry, str)]
    if offenders:
        raise TypeError("non-string log entries at positions %r" % offenders)
    return [line.strip() for line in logs]


def first_words(lines):
    return [line.split()[0] for line in lines if line.split()]


def error_lines(lines):
    return [line for line in lines if "error" in line.split()]


def timeout_ips(lines):
    candidates = [line.split() for line in lines if "timeout" in line.split()]
    return [words[1] for words in candidates if len(words) > 1]


def long_message_lengths(lines, limit=50):
    return [len(line) for line in lines if len(line) > limit]


def last_words(lines):
    return [line.split()[-1] for line in lines if line.split()]


def upper_lines(lines):
    return [line.upper() for line in lines]


def digit_starts(lines):
    return [bool(line) and line[0].isdigit() for line in lines]


def success_third_words(lines):
    candidates = [line.split() for line in lines if "success" in line.split()]
    return [words[2] for words in candidates if len(words) > 2]


def parse(logs):
    lines = _validate(logs)
    return (
        first_words(lines),
        error_lines(lines),
        timeout_ips(lines),
        long_message_lengths(lines),
        last_words(lines),
        upper_lines(lines),
        digit_starts(lines),
        success_third_words(lines),
    )


LABELS = (
    "first_words",
    "error_lines",
    "timeout_ips",
    "long_lengths",
    "last_words",
    "upper_lines",
    "digit_starts",
    "success_third_words",
)


def format_report(result):
    sizes = [len(values) for values in result]
    rows = ["%-20s (%d) %r" % (label, len(values), values)
            for label, values in zip(LABELS, result)]
    header = "%d log views, %d extracted items" % (len(result), sum(sizes))
    return "\n".join([header] + rows)


def main():
    logs = [
        "12:00 192.0.0.1 error failed",
        "12:01 10.0.0.7 timeout while waiting for the upstream database connection",
        "12:02 10.0.0.8 success deployment finished",
        "restarting worker pool",
    ]
    print(format_report(parse(logs)))


if __name__ == "__main__":
    main()

