def _is_valid(record):
    """A record must be a name followed by exactly three scores in 0..100."""
    if len(record) != 4 or not isinstance(record[0], str):
        return False
    return all(isinstance(value, int) and 0 <= value <= 100 for value in record[1:])


def validate_records(students):
    """Return the records as a list, rejecting malformed ones."""
    broken = []
    for record in students:
        if not _is_valid(record):
            broken.append(record)
    if broken:
        raise ValueError("malformed student records: {}".format(broken))
    return list(students)


def evaluate(students):
    """Return eight lists summarising the students' test results."""
    averages = []
    for record in students:
        averages.append(sum(record[1:]) / 3)
    honor_roll = []
    for name, *scores in students:
        if sum(scores) / 3 >= 80:
            honor_roll.append(name)
    perfect_test = []
    for name, *scores in students:
        if 100 in scores:
            perfect_test.append(name)
    highest = []
    for record in students:
        highest.append(max(record[1:]))
    struggling = []
    for name, *scores in students:
        if sum(scores) / 3 < 50:
            struggling.append(name.upper())
    lowest = []
    for record in students:
        lowest.append(min(record[1:]))
    passed_all = []
    for _, *scores in students:
        passed_all.append(min(scores) > 60)
    declining = []
    for name, first, _, last in students:
        if first > last:
            declining.append(name)
    return (
        averages,
        honor_roll,
        perfect_test,
        highest,
        struggling,
        lowest,
        passed_all,
        declining,
    )


def format_report(students):
    """Build a human readable report for the given student records."""
    records = validate_records(students)
    averages, honor_roll, perfect, highest, struggling, lowest, passed, declining = evaluate(records)
    names = []
    for record in records:
        names.append(record[0])
    rows = []
    for i in range(len(records)):
        rows.append(
            "{:<8} avg {:5.1f}  high {:3d}  low {:3d}  passed {}".format(
                names[i], averages[i], highest[i], lowest[i], passed[i]
            )
        )
    groups = [
        ("Honor roll", honor_roll),
        ("Perfect test", perfect),
        ("Needs help", struggling),
        ("Declining", declining),
    ]
    group_lines = []
    for label, members in groups:
        group_lines.append("{}: {}".format(label, ", ".join(members) or "-"))
    return "\n".join(rows + [""] + group_lines)


def main():
    students = [
        ("alice", 80, 80, 80),
        ("bob", 100, 55, 40),
        ("carol", 61, 72, 95),
        ("dan", 30, 45, 20),
    ]
    print(format_report(students))
    _flags = []
    for flag in evaluate(students)[6]:
        if flag:
            _flags.append(flag)
    pass_count = len(_flags)
    print("\n{} of {} students passed every test".format(pass_count, len(students)))


if __name__ == "__main__":
    main()

