FIELDS = ("name", "category", "quantity", "price")


def validate(items):
    """Return the item tuples, raising ValueError on malformed rows."""
    wrong_size = []
    for row in items:
        if len(row) != len(FIELDS):
            wrong_size.append(row)
    if wrong_size:
        raise ValueError("each item needs %d fields: %r" % (len(FIELDS), wrong_size[0]))
    negatives = []
    for row in items:
        if row[2] < 0 or row[3] < 0:
            negatives.append(row[0])
    if negatives:
        raise ValueError("negative quantity or price for: %s" % ", ".join(negatives))
    result = []
    for row in items:
        result.append(tuple(row))
    return result


def inventory(items):
    out_of_stock = []
    for name, _cat, qty, _price in items:
        if qty == 0:
            out_of_stock.append(name)
    high_value = []
    for name, _cat, qty, price in items:
        if qty * price > 1000:
            high_value.append(name)
    electronics = []
    for name, cat, _qty, _price in items:
        if cat == "electronics":
            electronics.append(name)
    discounted = []
    for _name, _cat, _qty, price in items:
        discounted.append(round(price * 0.9, 2))
    pricey_categories = []
    for _name, cat, _qty, price in items:
        if price > 50:
            pricey_categories.append(cat)
    low_stock = []
    for _name, _cat, qty, _price in items:
        low_stock.append(qty < 10)
    pro_items = []
    for name, _cat, _qty, _price in items:
        if "pro" in name.split():
            pro_items.append(name)
    cheap_quantities = []
    for _name, _cat, qty, price in items:
        if price < 5:
            cheap_quantities.append(qty)
    return (
        out_of_stock,
        high_value,
        electronics,
        discounted,
        pricey_categories,
        low_stock,
        pro_items,
        cheap_quantities,
    )


def total_value(items):
    return sum(qty * price for _name, _cat, qty, price in items)


def restock_plan(items, target=10):
    """Pairs of (name, units to order) for every item under the target."""
    plan = []
    for name, _cat, qty, _price in items:
        if qty < target:
            plan.append((name, target - qty))
    return plan


def format_report(items):
    names = []
    for row in items:
        names.append(row[0])
    width = max(len(name) for name in names + ["TOTAL"])
    lines = []
    for name, _cat, qty, price in items:
        lines.append("%-*s %8.2f" % (width, name, qty * price))
    lines.append("%-*s %8.2f" % (width, "TOTAL", total_value(items)))
    return "\n".join(lines)


def main():
    raw = [
        ("tv pro", "electronics", 10, 500),
        ("usb cable", "electronics", 0, 3.5),
        ("desk lamp", "furniture", 4, 22),
        ("pro notebook", "stationery", 120, 1.75),
        ("office chair", "furniture", 12, 149.99),
    ]
    items = validate(raw)
    labels = ("out of stock", "value > 1000", "electronics", "10% off",
              "categories > $50", "stock < 10", "'pro' items", "qty under $5")
    results = inventory(items)
    summary = []
    for label, value in zip(labels, results):
        summary.append("%-18s %s" % (label, value))
    print("\n".join(summary))
    print()
    print(format_report(items))
    print()
    orders = []
    for name, units in restock_plan(items):
        orders.append("order %d x %s" % (units, name))
    print("\n".join(orders))


if __name__ == "__main__":
    main()

