import math

LABELS = (
    "distances from origin",
    "strictly first quadrant",
    "on an axis",
    "squared x of second quadrant",
    "swapped coordinates",
    "inside circle r=6",
    "coordinate sums",
    "points where x == y",
)


def parse_points(text):
    """Turn a string like '3,4; -1,2' into a list of integer coordinate tuples."""
    chunks = []
    for chunk in text.split(";"):
        if chunk.strip():
            chunks.append(chunk.strip())
    pairs = []
    for chunk in chunks:
        pairs.append(chunk.split(","))
    malformed = []
    for chunk, pair in zip(chunks, pairs):
        if len(pair) != 2:
            malformed.append(chunk)
    if malformed:
        raise ValueError("expected 'x,y' pairs, got: " + "; ".join(malformed))
    try:
        _result = []
        for x, y in pairs:
            _result.append((int(x), int(y)))
        return _result
    except ValueError:
        raise ValueError("coordinates must be integers: " + text.strip())


def geometry(points):
    distances = []
    for x, y in points:
        distances.append(math.hypot(x, y))
    first_quadrant = []
    for x, y in points:
        if x > 0 and y > 0:
            first_quadrant.append((x, y))
    on_axis = []
    for x, y in points:
        if x == 0 or y == 0:
            on_axis.append((x, y))
    second_squares = []
    for x, y in points:
        if x < 0 and y > 0:
            second_squares.append(x * x)
    swapped = []
    for x, y in points:
        swapped.append((y, x))
    inside_circle = []
    for d in distances:
        inside_circle.append(d < 6)
    sums = []
    for x, y in points:
        sums.append(x + y)
    diagonal = []
    for x, y in points:
        if x == y:
            diagonal.append((x, y))
    return (
        distances,
        first_quadrant,
        on_axis,
        second_squares,
        swapped,
        inside_circle,
        sums,
        diagonal,
    )


def format_report(points, results):
    _parts = []
    for x, y in points:
        _parts.append(f"({x}, {y})")
    header = "points: " + ", ".join(_parts)
    _lengths = []
    for label in LABELS:
        _lengths.append(len(label))
    width = max(_lengths)
    lines = []
    for label, value in zip(LABELS, results):
        lines.append(f"{label:<{width}} -> {value}")
    return "\n".join([header] + lines)


def outside_radius(points, results):
    """Points that are not strictly inside the circle of radius six."""
    flags = results[5]
    _outside = []
    for point, inside in zip(points, flags):
        if not inside:
            _outside.append(point)
    return _outside


def main():
    samples = [
        "3,4",
        "0,0; 1,1; -2,5; 7,-7; 0,3; -4,-1",
    ]
    parsed = []
    for sample in samples:
        parsed.append(parse_points(sample))
    for points in parsed:
        results = geometry(points)
        print(format_report(points, results))
        far = outside_radius(points, results)
        print("outside radius six:", far)
        print()


if __name__ == "__main__":
    main()

