LABELS = [
    "3+ bedrooms",
    "2-bathroom prices",
    "under 500k",
    "price per bedroom",
    "million-dollar (capitalized)",
    "baths > beds",
    "total rooms",
    "exactly 1 bedroom",
]


def validate(listings):
    malformed = []
    for index, row in enumerate(listings):
        if len(row) != 4:
            malformed.append(index)
    if malformed:
        raise ValueError("rows with wrong length at positions: %s" % malformed)
    bad_prices = []
    for row in listings:
        if not isinstance(row[3], int):
            bad_prices.append(row[0])
    if bad_prices:
        raise TypeError("prices must be integers for: %s" % bad_prices)
    bad_rooms = []
    for row in listings:
        if row[1] < 0 or row[2] < 0:
            bad_rooms.append(row[0])
    if bad_rooms:
        raise ValueError("room counts must not be negative for: %s" % bad_rooms)


def properties(listings):
    big = []
    for address, beds, _, _ in listings:
        if beds >= 3:
            big.append(address)
    two_bath_prices = []
    for _, _, baths, price in listings:
        if baths == 2:
            two_bath_prices.append(price)
    affordable = []
    for address, _, _, price in listings:
        if price < 500000:
            affordable.append(address)
    per_bedroom = []
    for _, beds, _, price in listings:
        if beds >= 1:
            per_bedroom.append(price / beds)
    luxury = []
    for address, _, _, price in listings:
        if price >= 1000000:
            luxury.append(address.capitalize())
    bath_heavy = []
    for _, beds, baths, _ in listings:
        bath_heavy.append(baths > beds)
    total_rooms = []
    for _, beds, baths, _ in listings:
        total_rooms.append(beds + baths)
    studios = []
    for address, beds, _, _ in listings:
        if beds == 1:
            studios.append(address)
    return (big, two_bath_prices, affordable, per_bedroom, luxury, bath_heavy,
            total_rooms, studios)


def price_stats(listings):
    prices = []
    for *_, price in listings:
        prices.append(price)
    if not prices:
        return None
    return min(prices), max(prices), sum(prices) / len(prices)


def cheapest(listings, count):
    ordered = sorted(listings, key=lambda row: row[3])
    result = []
    for address, _, _, price in ordered[:count]:
        result.append(f"{address.title()} - ${price:,}")
    return result


def report(listings):
    validate(listings)
    results = properties(listings)
    lines = []
    for label, values in zip(LABELS, results):
        lines.append(f"{label}: {values}")
    stats = price_stats(listings)
    if stats is not None:
        lines.append("prices: min ${:,} / max ${:,} / mean ${:,.0f}".format(*stats))
    lines.extend(cheapest(listings, 3))
    return "\n".join(lines)


