from collections import Counter

LABELS = (
    "routes from central station",
    "destinations under 30 minutes",
    "airport durations in hours",
    "circular route numbers",
    "origins over 60 minutes",
    "even route number flags",
    "travel times in seconds",
    "destination name lengths",
)


def check_routes(routes):
    """Raise ValueError if any record is not a 4-field route tuple."""
    wrong_size = []
    for index, record in enumerate(routes):
        if len(record) != 4:
            wrong_size.append(index)
    if wrong_size:
        raise ValueError(f"records with wrong number of fields: {wrong_size}")
    wrong_types = []
    for index, (number, origin, destination, minutes) in enumerate(routes):
        if (
            not isinstance(number, int)
            or not isinstance(origin, str)
            or not isinstance(destination, str)
            or not isinstance(minutes, int)
        ):
            wrong_types.append(index)
    if wrong_types:
        raise ValueError(f"records with wrong field types: {wrong_types}")


def normalize(routes):
    """Trim and lowercase the station names so comparisons are reliable."""
    check_routes(routes)
    result = []
    for n, o, d, t in routes:
        result.append((n, o.strip().lower(), d.strip().lower(), t))
    return result


def transit(routes):
    records = normalize(routes)
    from_central = []
    for n, o, _d, _t in records:
        if o == "central station":
            from_central.append(n)
    short_trips = []
    for _n, _o, d, t in records:
        if t < 30:
            short_trips.append(d)
    airport_hours = []
    for _n, _o, d, t in records:
        if d == "airport":
            airport_hours.append(t / 60)
    circular = []
    for n, o, d, _t in records:
        if o == d:
            circular.append(n)
    long_origins = []
    for _n, o, _d, t in records:
        if t > 60:
            long_origins.append(o)
    even_numbers = []
    for n, _o, _d, _t in records:
        even_numbers.append(n % 2 == 0)
    seconds = []
    for _n, _o, _d, t in records:
        seconds.append(t * 60)
    name_lengths = []
    for _n, _o, d, _t in records:
        name_lengths.append(len(d))
    return (
        from_central,
        short_trips,
        airport_hours,
        circular,
        long_origins,
        even_numbers,
        seconds,
        name_lengths,
    )


def format_report(routes):
    """Return one printable line per list produced by transit()."""
    lines = []
    for label, values in zip(LABELS, transit(routes)):
        lines.append(f"{label}: {values}")
    return lines


def busiest_origins(routes, limit=3):
    counts = Counter(o for _n, o, _d, _t in normalize(routes))
    result = []
    for origin, total in counts.most_common(limit):
        result.append(f"{origin} ({total})")
    return result


def main():
    routes = [
        (10, "Central Station", "Airport", 45),
        (11, "central station", "Harbour", 25),
        (12, "Airport", "Airport", 15),
        (13, "Harbour", "Airport", 75),
        (14, "Central Station", "Old Town", 62),
    ]
    for line in format_report(routes):
        print(line)
    print("busiest origins: " + ", ".join(busiest_origins(routes)))
    print(transit([(10, "central station", "airport", 45)]))


