def normalize(bookings):
    """Lowercase guest names and room types so comparisons are reliable."""
    _result = []
    for n, r, k, c in bookings:
        _result.append((str(n).strip().lower(), str(r).strip().lower(), int(k), float(c)))
    return _result


def validate(bookings):
    """Return a list of complaints about bookings that make no sense."""
    problems = []
    for name, _, nights, _ in bookings:
        if nights <= 0:
            problems.append(f"{name}: nights must be positive, got {nights}")
    _extra = []
    for name, _, _, cost in bookings:
        if cost < 0:
            _extra.append(f"{name}: cost must not be negative, got {cost}")
    problems += _extra
    return problems


def hotel(bookings):
    suite_guests = []
    for name, room, _, _ in bookings:
        if room == "suite":
            suite_guests.append(name)
    nightly_rates = []
    for _, _, nights, cost in bookings:
        nightly_rates.append(round(cost / nights, 2))
    long_stay_rooms = []
    for _, room, nights, _ in bookings:
        if nights > 7:
            long_stay_rooms.append(room)
    big_spenders = []
    for name, _, _, cost in bookings:
        if cost > 1000:
            big_spenders.append(name)
    one_night_name_lengths = []
    for name, _, nights, _ in bookings:
        if nights == 1:
            one_night_name_lengths.append(len(name))
    is_standard = []
    for _, room, _, _ in bookings:
        is_standard.append(room == "standard")
    discounted = []
    for _, _, _, cost in bookings:
        discounted.append(round(cost * 0.9, 2))
    nights_squared = []
    for _, _, nights, _ in bookings:
        nights_squared.append(nights ** 2)
    return (suite_guests, nightly_rates, long_stay_rooms, big_spenders,
            one_night_name_lengths, is_standard, discounted, nights_squared)


def occupancy_by_type(bookings):
    """Pair each room type with the total number of nights booked for it."""
    _rooms = []
    for _, room, _, _ in bookings:
        _rooms.append(room)
    types = sorted(dict.fromkeys(_rooms))
    _result = []
    for room in types:
        _nights = []
        for _, r, nights, _ in bookings:
            if r == room:
                _nights.append(nights)
        _result.append((room, sum(_nights)))
    return _result


def format_report(bookings):
    suites, rates, long_rooms, rich, _, standard, discounted, squared = hotel(bookings)
    lines = ["Guest      Room      Nights  Rate    Discounted"]
    rows = []
    for (name, room, nights, _), rate, price in zip(bookings, rates, discounted):
        rows.append((name, room, nights, rate, price))
    _row_lines = []
    for name, room, nights, rate, price in rows:
        _row_lines.append(f"{name:<10} {room:<9} {nights:>6}  {rate:>6.2f}  {price:>10.2f}")
    lines += _row_lines
    lines.append(f"Suite guests: {', '.join(suites) or 'none'}")
    lines.append(f"Over 1000: {', '.join(rich) or 'none'}")
    lines.append(f"Long-stay room types: {', '.join(long_rooms) or 'none'}")
    lines.append(f"Standard flags: {standard}")
    lines.append(f"Nights squared total: {sum(squared)}")
    _occ_lines = []
    for room, total in occupancy_by_type(bookings):
        _occ_lines.append(f"  {room}: {total} night(s)")
    lines += _occ_lines
    return "\n".join(lines)


def main():
    raw = [
        ("Smith", "Suite", 3, 900.0),
        ("Jones", "standard", 1, 120.0),
        ("Okafor", "suite", 10, 3200.0),
        ("Lim", "double", 5, 640.0),
        ("Novak", "standard", 0, 0.0),
    ]
    bookings = normalize(raw)
    complaints = validate(bookings)
    if complaints:
        for message in complaints:
            print("warning:", message)
        _filtered = []
        for b in bookings:
            if b[2] > 0 and b[3] >= 0:
                _filtered.append(b)
        bookings = _filtered
    print(format_report(bookings))


