def validate(readings):
    """Return a list of error messages for malformed telemetry records."""
    problems = []
    for index, record in enumerate(readings):
        if not isinstance(record, tuple) or len(record) != 4:
            problems.append("record %d is not a 4-field tuple" % index)
    if problems:
        return problems
    bad_stamps = []
    for index, rec in enumerate(readings):
        if not isinstance(rec[0], int):
            bad_stamps.append(index)
    _tmp = []
    for index in bad_stamps:
        _tmp.append("record %d has a non-integer timestamp" % index)
    problems += _tmp
    bad_names = []
    for index, rec in enumerate(readings):
        if not isinstance(rec[1], str):
            bad_names.append(index)
    _tmp = []
    for index in bad_names:
        _tmp.append("record %d has a non-string sensor id" % index)
    problems += _tmp
    bad_values = []
    for index, rec in enumerate(readings):
        if not isinstance(rec[2], (int, float)) or not isinstance(rec[3], (int, float)):
            bad_values.append(index)
    _tmp = []
    for index in bad_values:
        _tmp.append("record %d has non-numeric measurements" % index)
    problems += _tmp
    return problems


def telemetry(readings):
    errors = validate(readings)
    if errors:
        raise ValueError("; ".join(errors))
    humid_stamps = []
    for stamp, _, _, hum in readings:
        if hum > 80.0:
            humid_stamps.append(stamp)
    outdoor_temps = []
    for _, sensor, temp, _ in readings:
        if sensor == "outdoor":
            outdoor_temps.append(temp)
    freezing = []
    for _, sensor, temp, _ in readings:
        if temp < 0.0:
            freezing.append(sensor)
    heat_index = []
    for _, _, temp, hum in readings:
        heat_index.append(temp + hum)
    early = []
    for stamp, sensor, _, _ in readings:
        if stamp < 1000:
            early.append(sensor.upper())
    matched = []
    for _, _, temp, hum in readings:
        matched.append(temp == hum)
    stamp_labels = []
    for stamp, _, _, _ in readings:
        stamp_labels.append(str(stamp))
    half_humidity = []
    for _, _, _, hum in readings:
        half_humidity.append(hum / 2)
    return (
        humid_stamps,
        outdoor_temps,
        freezing,
        heat_index,
        early,
        matched,
        stamp_labels,
        half_humidity,
    )


def report(readings):
    """Build a human readable summary of the eight telemetry channels."""
    labels = [
        "high humidity timestamps",
        "outdoor temperatures",
        "below-freezing sensors",
        "heat index",
        "early sensors",
        "temperature equals humidity",
        "timestamp labels",
        "halved humidity",
    ]
    channels = telemetry(readings)
    lines = []
    for pair in zip(labels, channels):
        lines.append("%s: %s" % pair)
    widths = []
    for line in lines:
        widths.append(len(line.split(":")[0]))
    pad = max(widths)
    return "\n".join(
        "%-*s %s" % (pad + 1, name + ":", values)
        for name, values in zip(labels, channels)
    )


def main():
    samples = [
        (900, "outdoor", -2.5, 85.0),
        (1200, "indoor", 21.0, 21.0),
        (1500, "outdoor", 3.5, 92.5),
        (300, "attic", 30.0, 45.0),
    ]
    print(report(samples))
    empty_channels = []
    for channel in telemetry([]):
        empty_channels.append(len(channel))
    print("empty input channel sizes:", empty_channels)


