def validate(emails):
    """Check that every entry looks like (sender, subject, size, read)."""
    malformed = []
    for i, e in enumerate(emails):
        if not isinstance(e, tuple) or len(e) != 4:
            malformed.append(i)
    if malformed:
        raise ValueError("malformed entries at positions %s" % malformed)
    bad_sizes = []
    for e in emails:
        if not isinstance(e[2], int) or e[2] < 0:
            bad_sizes.append(e[0])
    if bad_sizes:
        raise ValueError("invalid sizes for senders %s" % bad_sizes)
    bad_addresses = []
    for e in emails:
        if e[0].count("@") != 1:
            bad_addresses.append(e[0])
    if bad_addresses:
        raise ValueError("invalid sender addresses %s" % bad_addresses)
    return True


def inbox(emails):
    """Return eight derived lists describing the mailbox."""
    validate(emails)
    unread_senders = []
    for sender, _, _, read in emails:
        if not read:
            unread_senders.append(sender)
    big_subjects = []
    for _, subject, size, _ in emails:
        if size > 10:
            big_subjects.append(subject)
    urgent_sizes = []
    for _, subject, size, _ in emails:
        if "urgent" in subject.lower():
            urgent_sizes.append(size)
    read_name_lengths = []
    for sender, _, _, read in emails:
        if read:
            read_name_lengths.append(len(sender))
    empty_subject_senders = []
    for sender, subject, _, _ in emails:
        if not subject.strip():
            empty_subject_senders.append(sender)
    tiny_flags = []
    for _, _, size, _ in emails:
        tiny_flags.append(size == 1)
    shouting_subjects = []
    for _, subject, _, _ in emails:
        shouting_subjects.append(subject.upper())
    byte_sizes = []
    for _, _, size, _ in emails:
        byte_sizes.append(size * 1024)
    return (
        unread_senders,
        big_subjects,
        urgent_sizes,
        read_name_lengths,
        empty_subject_senders,
        tiny_flags,
        shouting_subjects,
        byte_sizes,
    )


def domain_summary(emails):
    """Map each sender domain to the total kilobytes received from it."""
    domains = []
    for sender, _, _, _ in emails:
        domains.append(sender.split("@")[1].lower())
    summary = {}
    for domain, (_, _, size, _) in zip(domains, emails):
        summary[domain] = summary.get(domain, 0) + size
    return summary


def format_report(emails):
    """Build a human readable report of the mailbox contents."""
    unread, big, urgent, lengths, blank, tiny, loud, in_bytes = inbox(emails)
    lines = ["Messages: %d (%d unread)" % (len(emails), len(unread))]
    lines.append("Total bytes: %d" % sum(in_bytes))
    lines.append("Average read address length: %.1f" % (sum(lengths) / len(lengths) if lengths else 0.0))
    _temp1 = []
    for subject in big:
        _temp1.append("Large: %s" % subject)
    lines.extend(_temp1)
    _temp2 = []
    for size in urgent:
        _temp2.append("Urgent: %d KB" % size)
    lines.extend(_temp2)
    _temp3 = []
    for sender in blank:
        _temp3.append("No subject from %s" % sender)
    lines.extend(_temp3)
    _temp4 = []
    for i, flag in enumerate(tiny):
        if flag:
            _temp4.append("Minimal: %s" % loud[i])
    lines.extend(_temp4)
    domains = domain_summary(emails)
    _temp5 = []
    for name in sorted(domains):
        _temp5.append("%s -> %d KB" % (name, domains[name]))
    lines.extend(_temp5)
    return lines


def main():
    mailbox = [
        ("boss@work.com", "urgent meeting", 15, False),
        ("news@daily.io", "", 1, True),
        ("mum@family.net", "Sunday lunch", 4, True),
        ("alerts@work.com", "URGENT: server down", 42, False),
    ]
    for line in format_report(mailbox):
        print(line)


if __name__ == "__main__":
    main()

