def validate(commits):
    """Return the commits whose shape matches (hash, author, files, lines)."""
    if not isinstance(commits, list):
        raise TypeError("commits must be a list of tuples")
    bad = []
    for index, item in enumerate(commits):
        if len(item) != 4:
            bad.append(index)
    if bad:
        raise ValueError("malformed commit tuples at positions %s" % bad)
    numeric = []
    for item in commits:
        numeric.append((item[2], item[3]))
    if any(files < 0 or lines < 0 for files, lines in numeric):
        raise ValueError("files changed and lines added must be non-negative")
    return commits


def repository(commits):
    """Split commit records into eight parallel or filtered projections."""
    validate(commits)
    admin_hashes = []
    for h, author, files, lines in commits:
        if author == "admin":
            admin_hashes.append(h)
    single_file_authors = []
    for h, author, files, lines in commits:
        if files == 1:
            single_file_authors.append(author)
    big_commit_lines = []
    for h, author, files, lines in commits:
        if files > 10:
            big_commit_lines.append(lines)
    zero_addition = []
    for h, author, files, lines in commits:
        if lines == 0:
            zero_addition.append(h)
    hash_lengths = []
    for h, author, files, lines in commits:
        hash_lengths.append(len(h))
    over_hundred = []
    for h, author, files, lines in commits:
        over_hundred.append(lines > 100)
    lowered_authors = []
    for h, author, files, lines in commits:
        lowered_authors.append(author.lower())
    doubled_files = []
    for h, author, files, lines in commits:
        doubled_files.append(files * 2)
    return (
        admin_hashes,
        single_file_authors,
        big_commit_lines,
        zero_addition,
        hash_lengths,
        over_hundred,
        lowered_authors,
        doubled_files,
    )


def summarize(commits):
    """Build a per-author summary of commit count and total lines added."""
    names = sorted(set(repository(commits)[6]))
    summary = []
    for name in names:
        lines = []
        for item in commits:
            if item[1].lower() == name:
                lines.append(item[3])
        summary.append((name, len(lines), sum(lines)))
    return summary


def format_report(commits):
    """Render the projections and the author summary as printable lines."""
    labels = (
        "admin hashes",
        "single-file authors",
        "lines added over ten files",
        "zero-addition hashes",
        "hash lengths",
        "over one hundred lines",
        "lowercase authors",
        "doubled files changed",
    )
    projections = repository(commits)
    rows = []
    for label, values in zip(labels, projections):
        rows.append("%-26s %s" % (label, values))
    author_rows = []
    for triple in summarize(commits):
        author_rows.append("%-26s %d commits, %d lines" % triple)
    return rows + author_rows


def main():
    commits = [
        ("a1b2", "admin", 1, 50),
        ("c3d4", "Dana", 12, 430),
        ("e5f6", "dana", 3, 0),
        ("0789", "Admin", 11, 101),
    ]
    for line in format_report(commits):
        print(line)


if __name__ == "__main__":
    main()

