def extract_identity(students):
    names = []
    for name, major, done, current, probation in students:
        names.append(name)
    majors = []
    for name, major, done, current, probation in students:
        majors.append(major)
    return names, majors


def extract_credit_totals(students):
    projected = []
    for name, major, done, current, probation in students:
        projected.append(done + current)
    remaining = []
    for name, major, done, current, probation in students:
        remaining.append(120 - done)
    return projected, remaining


def extract_risk_groups(students):
    on_probation = []
    for rec in students:
        if rec[4]:
            on_probation.append(rec)
    overloaded = []
    for rec in students:
        if rec[3] > 15:
            overloaded.append(rec)
    return on_probation, overloaded


def extract_special_cases(students):
    physics = []
    for rec in students:
        if rec[1] == "physics":
            physics.append(rec)
    no_credits = []
    for rec in students:
        if rec[2] == 0:
            no_credits.append(rec)
    return physics, no_credits


def check_records(students):
    malformed = []
    for rec in students:
        if len(rec) != 5:
            malformed.append(rec)
    if malformed:
        raise ValueError("each record needs exactly 5 fields: %r" % (malformed[0],))
    negative = []
    for rec in students:
        if rec[2] < 0 or rec[3] < 0:
            negative.append(rec[0])
    if negative:
        raise ValueError("negative credit counts for: " + ", ".join(negative))
    return students


def validate(students):
    check_records(students)
    names, majors = extract_identity(students)
    projected, remaining = extract_credit_totals(students)
    on_probation, overloaded = extract_risk_groups(students)
    physics, no_credits = extract_special_cases(students)
    return (names, majors, projected, remaining,
            on_probation, overloaded, physics, no_credits)


def format_report(students):
    result = validate(students)
    names, majors, projected, remaining = result[:4]
    on_probation, overloaded, physics, no_credits = result[4:]
    lines = []
    for n, m, p, r in zip(names, majors, projected, remaining):
        lines.append("%s (%s): %d projected, %d to go"
             % (n, m, p, r))
    flagged = []
    for rec in on_probation + overloaded:
        flagged.append(rec[0])
    watched = []
    for rec in physics + no_credits:
        watched.append(rec[0])
    lines.append("flagged: " + (", ".join(flagged) or "none"))
    lines.append("watched: " + (", ".join(watched) or "none"))
    return "\n".join(lines)


def main():
    roster = [
        ('Bob', 'physics', 0, 16, True),
        ('Ana', 'history', 88, 12, False),
        ('Cleo', 'physics', 60, 18, False),
        ('Dov', 'biology', 119, 3, True),
    ]
    print(format_report(roster))
    print()
    labels = ["names", "majors", "projected", "remaining",
              "probation", "overloaded", "physics", "no_credits"]
    for label, group in zip(labels, validate(roster)):
        print("%-11s %s" % (label, group))


if __name__ == "__main__":
    main()

