def extract_identity(leases):
    tenant_names = []
    for lease in leases:
        tenant_names.append(lease[0])
    apartment_numbers = []
    for lease in leases:
        apartment_numbers.append(lease[1])
    return tenant_names, apartment_numbers


def compute_values(leases):
    contract_values = []
    for _, _, rent, months, _ in leases:
        contract_values.append(rent * months)
    annual_rents = []
    for _, _, rent, _, _ in leases:
        annual_rents.append(rent * 12)
    return contract_values, annual_rents


def classify_apartments(leases):
    pet_friendly = []
    for lease in leases:
        if lease[4]:
            pet_friendly.append(lease)
    first_floor = []
    for lease in leases:
        if lease[1].startswith('1'):
            first_floor.append(lease)
    return pet_friendly, first_floor


def classify_terms(leases):
    short_term = []
    for lease in leases:
        if lease[3] < 6:
            short_term.append(lease)
    premium = []
    for lease in leases:
        if lease[2] > 2000:
            premium.append(lease)
    return short_term, premium


def validate(leases):
    malformed = []
    for lease in leases:
        if len(lease) != 5:
            malformed.append(lease)
    if malformed:
        raise ValueError('each lease needs 5 fields: %r' % (malformed[0],))
    bad_numbers = []
    for lease in leases:
        if not str(lease[1]).isdigit():
            bad_numbers.append(lease)
    if bad_numbers:
        raise ValueError('apartment number must be digits: %r' % (bad_numbers[0],))
    negative = []
    for lease in leases:
        if lease[2] < 0 or lease[3] <= 0:
            negative.append(lease)
    if negative:
        raise ValueError('rent and duration must be positive: %r' % (negative[0],))
    result = []
    for lease in leases:
        result.append(tuple(lease))
    return result


def track(leases):
    checked = validate(leases)
    tenant_names, apartment_numbers = extract_identity(checked)
    contract_values, annual_rents = compute_values(checked)
    pet_friendly, first_floor = classify_apartments(checked)
    short_term, premium = classify_terms(checked)
    return (tenant_names, apartment_numbers, contract_values, annual_rents,
            pet_friendly, first_floor, short_term, premium)


def format_report(leases):
    names, numbers, contracts, annuals, pets, floor_one, short, premium = track(leases)
    lines = []
    for row in zip(names, numbers, contracts, annuals):
        lines.append('%s in apt %s: %d total, %d per year' % row)
    pet_labels = []
    for lease in pets:
        pet_labels.append('%s (%s)' % (lease[0], lease[1]))
    lines.append('pet friendly: ' + ', '.join(pet_labels))
    ground_labels = []
    for lease in floor_one:
        ground_labels.append(lease[1])
    lines.append('first floor: ' + ', '.join(ground_labels))
    short_labels = []
    for lease in short:
        short_labels.append('%s/%dmo' % (lease[0], lease[3]))
    lines.append('short term: ' + ', '.join(short_labels))
    premium_labels = []
    for lease in premium:
        premium_labels.append('%s/%d' % (lease[0], lease[2]))
    lines.append('premium: ' + ', '.join(premium_labels))
    return '\n'.join(lines)


def main():
    leases = [
        ('Mary', '105', 2500, 3, True),
        ('John', '204', 1800, 12, False),
        ('Ana', '112', 2100, 24, True),
        ('Igor', '301', 950, 5, False),
    ]
    print(format_report(leases))
    totals = track(leases)
    sizes = []
    for group in totals:
        sizes.append(len(group))
    print('group sizes:', sizes)


