def extract_identity(applications):
    names = []
    for app in applications:
        names.append(app[0])
    universities = []
    for app in applications:
        universities.append(app[1])
    return names, universities


def extract_scores(applications):
    experience_multipliers = []
    for app in applications:
        experience_multipliers.append(app[2] * 1.5)
    relocation_flags = []
    for app in applications:
        relocation_flags.append(app[4])
    return experience_multipliers, relocation_flags


def filter_by_profile(applications):
    relocators = []
    for app in applications:
        if app[4]:
            relocators.append(app)
    state_university = []
    for app in applications:
        if app[1] == 'state':
            state_university.append(app)
    return relocators, state_university


def filter_by_skill(applications):
    seniors = []
    for app in applications:
        if app[2] > 10:
            seniors.append(app)
    polyglots = []
    for app in applications:
        if app[3] > 3:
            polyglots.append(app)
    return seniors, polyglots


def validate(applications):
    malformed = []
    for app in applications:
        if len(app) != 5:
            malformed.append(app)
    if malformed:
        raise ValueError("each application needs 5 fields: %r" % (malformed,))
    bad_numbers = []
    for app in applications:
        if not isinstance(app[2], int) or not isinstance(app[3], int):
            bad_numbers.append(app[0])
    if bad_numbers:
        raise ValueError("experience and language counts must be integers: %s"
                         % ", ".join(bad_numbers))


def screen(applications):
    validate(applications)
    names, universities = extract_identity(applications)
    multipliers, relocation_flags = extract_scores(applications)
    relocators, state_university = filter_by_profile(applications)
    seniors, polyglots = filter_by_skill(applications)
    return (names, universities, multipliers, relocation_flags,
            relocators, state_university, seniors, polyglots)


def format_report(applications):
    result = screen(applications)
    names, universities, multipliers, relocation_flags = result[:4]
    relocators, state_university, seniors, polyglots = result[4:]
    rows = []
    for name, university, multiplier, flag \
            in zip(names, universities, multipliers, relocation_flags):
        rows.append("%-8s %-10s score=%5.1f relocate=%s"
                    % (name, university, multiplier, flag))
    shortlist = []
    for app in seniors:
        if app in polyglots:
            shortlist.append(app[0])
    summary = [
        "relocators: %d" % len(relocators),
        "state university: %d" % len(state_university),
        "seniors: %d" % len(seniors),
        "polyglots: %d" % len(polyglots),
        "shortlist: %s" % (", ".join(shortlist) or "none"),
    ]
    return "\n".join(rows + summary)


