"""Manufacturing quality-control analysis helpers."""


def validate(batches):
    """Return the batches after rejecting structurally invalid records."""
    malformed = []
    for b in batches:
        if len(b) != 5:
            malformed.append(b)
    if malformed:
        raise ValueError("malformed batch records: %r" % (malformed,))
    nonpositive = []
    for b in batches:
        if b[2] <= 0:
            nonpositive.append(b[0])
    if nonpositive:
        raise ValueError("batches with no items: %s" % ", ".join(nonpositive))
    overcounted = []
    for b in batches:
        if b[3] > b[2]:
            overcounted.append(b[0])
    if overcounted:
        raise ValueError("more defects than items: %s" % ", ".join(overcounted))
    return batches


def identify(batches):
    """Split the records into their batch codes and machine operators."""
    codes = []
    for batch in batches:
        codes.append(batch[0])
    operators = []
    for batch in batches:
        operators.append(batch[1])
    return codes, operators


def measure(batches):
    """Compute good item counts and defect rates for every batch."""
    good_counts = []
    for batch in batches:
        good_counts.append(batch[2] - batch[3])
    defect_rates = []
    for batch in batches:
        defect_rates.append(batch[3] / batch[2])
    return good_counts, defect_rates


def select(batches):
    """Select the batches that passed inspection and those run by smith."""
    passed = []
    for batch in batches:
        if batch[4]:
            passed.append(batch)
    smith_batches = []
    for batch in batches:
        if batch[1] == 'smith':
            smith_batches.append(batch)
    return passed, smith_batches


def classify(batches):
    """Isolate the large batches and the defect-free batches."""
    large = []
    for batch in batches:
        if batch[2] > 10000:
            large.append(batch)
    perfect = []
    for batch in batches:
        if batch[3] == 0:
            perfect.append(batch)
    return large, perfect


def inspect(batches):
    codes, operators = identify(batches)
    good_counts, defect_rates = measure(batches)
    passed, smith_batches = select(batches)
    large, perfect = classify(batches)
    return (codes, operators, good_counts, defect_rates,
            passed, smith_batches, large, perfect)


def report(batches):
    """Build a human-readable summary of the inspection results."""
    codes, operators, good_counts, defect_rates, passed, smith, large, perfect = inspect(batches)
    lines = []
    for code, operator, good, rate in zip(codes, operators, good_counts, defect_rates):
        lines.append("%s (%s): %d good, %.2f%% defective"
             % (code, operator, good, rate * 100))
    temp_passed = []
    for b in passed:
        temp_passed.append(b[0])
    lines.append("passed inspection: %s" % ", ".join(temp_passed))
    temp_smith = []
    for b in smith:
        temp_smith.append(b[0])
    lines.append("operated by smith: %s" % ", ".join(temp_smith))
    temp_large = []
    for b in large:
        temp_large.append(b[0])
    lines.append("large batches: %s" % ", ".join(temp_large))
    temp_perfect = []
    for b in perfect:
        temp_perfect.append(b[0])
    lines.append("defect free: %s" % ", ".join(temp_perfect))
    return "\n".join(lines)


def main():
    batches = [
        ('B1', 'smith', 15000, 0, True),
        ('B2', 'jones', 8000, 160, True),
        ('B3', 'smith', 12500, 375, False),
        ('B4', 'patel', 4200, 0, True),
    ]
    validate(batches)
    print(report(batches))


