import random

STATUS_CODES = [200, 200, 301, 404, 500]
MESSAGES = ["OK", "MOVED", "NOT FOUND", "ERROR"]


def parse_addresses(logs):
    return [line.split()[0] for line in logs if line.strip()]


def keep_dotted_quads(addresses):
    return [address for address in addresses if address.count(".") == 3]


def split_blocks(addresses):
    return [address.split(".") for address in addresses]


def is_numeric_quad(blocks):
    return all([block.isdigit() for block in blocks])


def block_ints(blocks):
    return [int(block) for block in blocks]


def to_integers(quads):
    numeric = [quad for quad in quads if is_numeric_quad(quad)]
    return [block_ints(quad) for quad in numeric]


def keep_local(quads):
    return [quad for quad in quads if quad[0] == 10]


def dash_format(quad):
    return "-".join([str(block) for block in quad])


def audit(logs):
    addresses = parse_addresses(logs)
    dotted = keep_dotted_quads(addresses)
    quads = split_blocks(dotted)
    numeric = to_integers(quads)
    local = keep_local(numeric)
    return [dash_format(quad) for quad in local]


def fake_line(index):
    first = 10 if index % 3 else random.choice([172, 192])
    blocks = [random.randint(0, 255) for _ in range(4)]
    blocks[0] = first
    address = ".".join([str(block) for block in blocks])
    if index % 5 == 4:
        address = address.rsplit(".", 1)[0]
    return "%s %d %s" % (address, random.choice(STATUS_CODES), random.choice(MESSAGES))


def main():
    random.seed(7)
    logs = [fake_line(index) for index in range(12)]
    for line in logs:
        print("log:", line)
    local_addresses = audit(logs)
    report = ["local #%d -> %s" % (rank, address)
              for rank, address in enumerate(local_addresses, start=1)]
    for entry in report:
        print(entry)
    print("total local hosts:", len(local_addresses))


if __name__ == "__main__":
    main()

