from collections import Counter


def header_lines(document):
    """Return the stripped lines of the document that start with a hash."""
    stripped = [line.strip() for line in document]
    return [line for line in stripped if line.startswith("#")]


def depth_levels(headers):
    """Count the leading hash characters of every header line."""
    return [len(header) - len(header.lstrip("#")) for header in headers]


def header_titles(headers):
    """Drop the hashes and the surrounding whitespace of every header line."""
    return [header.lstrip("#").strip() for header in headers]


def slugify(title):
    """Turn a title into a lowercase, hyphen separated url slug."""
    flattened = [char if char.isalnum() else "-" for char in title.lower()]
    words = [word for word in "".join(flattened).split("-") if word]
    return "-".join(words)


def title_slugs(titles):
    return [slugify(title) for title in titles]


def collect_entries(document):
    """Build (level, title, slug) triples for the usable headers."""
    headers = header_lines(document)
    levels = depth_levels(headers)
    titles = header_titles(headers)
    slugs = title_slugs(titles)
    triples = list(zip(levels, titles, slugs))
    return [triple for triple in triples if len(triple[1]) >= 3]


def format_entry(level, title, slug):
    indent = "  " * (level - 1)
    return "{}{}. {} -> #{}".format(indent, level, title, slug)


def outline(document):
    """Generate the table of contents lines for a document."""
    return [format_entry(*entry) for entry in collect_entries(document)]


def depth_summary(entries):
    """Report how many titles were kept at each depth level."""
    counts = Counter(level for level, _, _ in entries)
    return ["level {}: {} title(s)".format(level, counts[level])
            for level in sorted(counts)]


def main():
    document = [
        "# User Guide",
        "Some introductory prose that is not a header.",
        "## Introduction ",
        "### Why?",
        "## Installing the Tool",
        "#### Windows & macOS",
        "Plain text again.",
        "## FAQ",
    ]
    for line in outline(document):
        print(line)
    print()
    for line in depth_summary(collect_entries(document)):
        print(line)


if __name__ == "__main__":
    main()

