VOWELS = "aeiou"
PUNCTUATION = ".,;:!?\"'()-—"


def tokenize(line):
    """Split a line of verse into bare, lower-case words."""
    stripped = [word.strip(PUNCTUATION).lower() for word in line.split()]
    return [word for word in stripped if word]


def extract_vowels(word):
    """All vowel characters of a word, used as a syllable estimate."""
    return [char for char in word if char in VOWELS]


def syllable_counts(words):
    """Estimated syllable count for each word of a line."""
    return [len(extract_vowels(word)) for word in words]


def valid_lines(poem):
    """Tokenized lines that carry at least four words."""
    lines = [tokenize(line) for line in poem]
    return [words for words in lines if len(words) >= 4]


def pentameter_lines(poem):
    """Lines whose total vowel count is exactly ten."""
    counts = [sum(syllable_counts(words)) for words in valid_lines(poem)]
    return [words for words, total in zip(valid_lines(poem), counts) if total == 10]


def rhyme_scheme(pairs):
    """Label each line A, B, C... according to the ending of its last word."""
    endings = [word[-2:] for word, _ in pairs]
    labels = {}
    for ending in endings:
        if ending not in labels:
            labels[ending] = chr(ord("A") + len(labels))
    return [labels[ending] for ending in endings]


def meter(poem):
    """Pair the last word of every valid line with that line's word count."""
    lines = valid_lines(poem)
    last_words = [words[-1] for words in lines]
    return [(word, len(words)) for word, words in zip(last_words, lines)]


def format_report(poem):
    pairs = meter(poem)
    scheme = rhyme_scheme(pairs)
    rows = [
        "{} | {:<10} words={} rhyme={}".format(index, word, length, label)
        for index, ((word, length), label) in enumerate(zip(pairs, scheme), 1)
    ]
    pentameters = [" ".join(words) for words in pentameter_lines(poem)]
    rows.append("pentameters: {}".format(len(pentameters)))
    rows.extend(pentameters)
    return "\n".join(rows)


def main():
    poem = [
        "A quick brown fox",
        "Shall I compare thee to a summer's day?",
        "Too short",
        "Thou art more lovely and more temperate today",
        "Rough winds do shake the darling buds of May",
    ]
    print(format_report(poem))
    print(meter(poem))


if __name__ == "__main__":
    main()

