def validate(pixels):
    """Check that the image is a non-empty rectangular grid of ints, at least 3x3."""
    if not pixels:
        raise ValueError("image is empty")
    widths = [len(row) for row in pixels]
    if len(set(widths)) != 1:
        raise ValueError("image rows have differing lengths")
    if len(pixels) < 3 or widths[0] < 3:
        raise ValueError("image must be at least three by three")
    non_ints = [value for row in pixels for value in row if not isinstance(value, int)]
    if non_ints:
        raise ValueError("pixel values must be integers: %r" % (non_ints,))


def window_positions(pixels):
    """Top-left corners of every three by three window inside the image."""
    height, width = len(pixels), len(pixels[0])
    return [(r, c) for r in range(height - 2) for c in range(width - 2)]


def _window(pixels, row, col):
    return [line[col:col + 3] for line in pixels[row:row + 3]]


def subgrids(pixels, positions):
    """All three by three subgrids of the image, in row-major order."""
    return [_window(pixels, r, c) for r, c in positions]


def _grid_total(grid):
    return sum([sum(line) for line in grid])


def blur_sums(grids):
    """Sum of the nine values of each subgrid."""
    return [_grid_total(grid) for grid in grids]


def averages(sums):
    """Average pixel value of each subgrid."""
    return [total / 9 for total in sums]


def bright_values(values, threshold=128):
    """The blurred values that count as bright spots."""
    return [value for value in values if value > threshold]


def bright_coordinates(positions, values, threshold=128):
    """Coordinates of the window centres whose blurred value is bright."""
    bright = [pos for pos, value in zip(positions, values) if value > threshold]
    return [(r + 1, c + 1) for r, c in bright]


def convolve(pixels):
    validate(pixels)
    positions = window_positions(pixels)
    grids = subgrids(pixels, positions)
    blurred = averages(blur_sums(grids))
    return blurred, bright_coordinates(positions, blurred)


def _format_row(row):
    return " ".join(["%6.1f" % value for value in row])


def format_report(flat, coords, width):
    rows = [flat[i:i + width] for i in range(0, len(flat), width)]
    lines = [_format_row(row) for row in rows]
    coord_lines = ["bright spot at row %d, col %d" % (r, c) for r, c in coords]
    return "\n".join(lines + coord_lines)


def main():
    image = [
        [9, 9, 9, 9, 9],
        [9, 200, 210, 220, 9],
        [9, 205, 255, 215, 9],
        [9, 195, 190, 185, 9],
        [9, 9, 9, 9, 9],
    ]
    flat, coords = convolve(image)
    print(format_report(flat, coords, len(image[0]) - 2))
    print("bright count:", len(bright_values(flat)))


if __name__ == "__main__":
    main()

