        widths.append(len(row))
    if len(set(widths)) != 1:
        raise ValueError("image rows have differing lengths")
    if len(pixels) < 3 or widths[0] < 3:
        raise ValueError("image must be at least three by three")
    non_ints = []
    for row in pixels:
        for value in row:
            if not isinstance(value, int):
                non_ints.append(value)
    if non_ints:
        raise ValueError("pixel values must be integers: %r" % (non_ints,))


def window_positions(pixels):
    """Top-left corners of every three by three window inside the image."""
    height, width = len(pixels), len(pixels[0])
    result = []
    for r in range(height - 2):
        for c in range(width - 2):
            result.append((r, c))
    return result


def _window(pixels, row, col):
    result = []
    for line in pixels[row:row + 3]:
        result.append(line[col:col + 3])
    return result


def subgrids(pixels, positions):
    """All three by three subgrids of the image, in row-major order."""
    result = []
    for r, c in positions:
        result.append(_window(pixels, r, c))
    return result


def _grid_total(grid):
    result = []
    for line in grid:
        result.append(sum(line))
    return sum(result)


def blur_sums(grids):
    """Sum of the nine values of each subgrid."""
    result = []
    for grid in grids:
        result.append(_grid_total(grid))
    return result


def averages(sums):
    """Average pixel value of each subgrid."""
    result = []
    for total in sums:
        result.append(total / 9)
    return result


def bright_values(values, threshold=128):
    """The blurred values that count as bright spots."""
    result = []
    for value in values:
        if value > threshold:
            result.append(value)
    return result


def bright_coordinates(positions, values, threshold=128):
    """Coordinates of the window centres whose blurred value is bright."""
    bright = []
    for pos, value in zip(positions, values):
        if value > threshold:
            bright.append(pos)
    result = []
    for r, c in bright:
        result.append((r + 1, c + 1))
    return result


def convolve(pixels):
    validate(pixels)
    positions = window_positions(pixels)
    grids = subgrids(pixels, positions)
    blurred = averages(blur_sums(grids))
    return blurred, bright_coordinates(positions, blurred)


def _format_row(row):
    result = []
    for value in row:
        result.append("%6.1f" % value)
    return " ".join(result)


def format_report(flat, coords, width):
    rows = []
    for i in range(0, len(flat), width):
        rows.append(flat[i:i + width])
    lines = []
    for row in rows:
        lines.append(_format_row(row))
    coord_lines = []
    for r, c in coords:
        coord_lines.append("bright spot at row %d, col %d" % (r, c))
    return "\n".join(lines + coord_lines)


