def parse_row(line):
    result = []
    for token in line.replace(",", " ").split():
        result.append(int(token))
    return result


def parse_grid(text):
    lines = []
    for line in text.splitlines():
        if line.strip():
            lines.append(line)
    result = []
    for line in lines:
        result.append(parse_row(line))
    return result


def column_at(rows, index):
    result = []
    for row in rows:
        if index < len(row):
            result.append(row[index])
    return result


def duplicates_in(cells):
    filled = []
    for cell in cells:
        if cell != 0:
            filled.append(cell)
    values = []
    for value in set(filled):
        if filled.count(value) > 1:
            values.append(value)
    return sorted(values)


def format_cells(cells):
    parts = []
    for cell in cells:
        parts.append("." if cell == 0 else str(cell))
    return " ".join(parts)


def validate(grid):
    rows = []
    for row in grid:
        rows.append(list(row))
    widths = []
    for row in rows:
        widths.append(len(row))
    width = max(widths) if widths else 0
    columns = []
    for index in range(width):
        columns.append(column_at(rows, index))
    zeros = []
    for row in rows:
        for cell in row:
            if cell == 0:
                zeros.append(cell)
    duplicate_rows = []
    for row in rows:
        if duplicates_in(row):
            duplicate_rows.append(row)
    duplicate_columns = []
    for column in columns:
        if duplicates_in(column):
            duplicate_columns.append(column)
    empty_coords = []
    for r, row in enumerate(rows):
        for c, cell in enumerate(row):
            if cell == 0:
                empty_coords.append((r, c))
    columns_filled = []
    for column in columns:
        columns_filled.append(all(cell != 0 for cell in column))
    rectangular = len(set(widths)) <= 1
    return {
        "height": len(rows),
        "width": width,
        "rectangular": rectangular,
        "zeros": zeros,
        "duplicate_rows": duplicate_rows,
        "duplicate_columns": duplicate_columns,
        "empty_coords": empty_coords,
        "columns_filled": columns_filled,
        "valid": rectangular and not duplicate_rows and not duplicate_columns,
    }


def format_report(report):
    lines = ["Grid: {} rows x {} columns".format(report["height"], report["width"])]
    if not report["rectangular"]:
        lines.append("Rows have inconsistent lengths")
    lines.append("Empty cells: {}".format(len(report["zeros"])))
    empty_lines = []
    for r, c in report["empty_coords"]:
        empty_lines.append("  empty at r{} c{}".format(r + 1, c + 1))
    lines += empty_lines
    row_lines = []
    for row in report["duplicate_rows"]:
        row_lines.append("  duplicates {} in row: {}".format(duplicates_in(row), format_cells(row)))
    lines += row_lines
    column_lines = []
    for col in report["duplicate_columns"]:
        column_lines.append("  duplicates {} in column: {}".format(duplicates_in(col), format_cells(col)))
    lines += column_lines
    flags = []
    for filled in report["columns_filled"]:
        flags.append("full" if filled else "open")
    lines.append("Columns: " + ", ".join(flags))
    lines.append("Verdict: " + ("consistent" if report["valid"] else "broken"))
    return lines


def main():
    sources = ["1 2 2 0\n3 4 1 2\n2 1 4 3\n4 3 1 0",
               "1 2 3 4\n3 4 1 2\n2 1 4 3\n4 3 2 1"]
    grids = []
    for text in sources:
        grids.append(parse_grid(text))
    reports = []
    for grid in grids:
        reports.append(validate(grid))
    for number, report in enumerate(reports, start=1):
        print("=== Puzzle {} ===".format(number))
        print("\n".join(format_report(report)))


if __name__ == "__main__":
    main()

