BUSINESS_START = 9
BUSINESS_END = 17
TIMEZONE_OFFSET = 6


def parse_hours(raw):
    """Turn a sequence of user supplied values into plain hour integers."""
    cleaned = [str(value).strip() for value in raw]
    bad = [token for token in cleaned if not token.lstrip("-").isdigit()]
    if bad:
        raise ValueError("not hour numbers: " + ", ".join(bad))
    hours = [int(token) for token in cleaned]
    out_of_day = [hour for hour in hours if not 0 <= hour <= 23]
    if out_of_day:
        raise ValueError("hours outside a day: %s" % out_of_day)
    return hours


def business_hours(hours):
    """Keep only the hours that fall inside the local business day."""
    return [hour for hour in hours if BUSINESS_START <= hour <= BUSINESS_END]


def to_foreign(hours, offset=TIMEZONE_OFFSET):
    """Shift local hours into the foreign timezone."""
    return [hour + offset for hour in hours]


def overlapping(foreign):
    """Foreign hours that are still within the standard business day."""
    return [hour for hour in foreign if BUSINESS_START <= hour <= BUSINESS_END]


def format_hour(hour):
    suffix = "am" if hour < 12 else "pm"
    return "{0} {1}".format(hour, suffix)


def format_hours(hours):
    return [format_hour(hour) for hour in hours]


def invite_block(label):
    return "INVITE\n  Time: {0} (foreign time)\n  Duration: 60 minutes".format(label)


def invites(labels):
    return [invite_block(label) for label in labels]


def schedule(meetings):
    """Return calendar invite blocks for every workable overlapping hour."""
    local = business_hours(parse_hours(meetings))
    foreign = to_foreign(local)
    available = overlapping(foreign)
    labels = format_hours(available)
    return invites(labels)


def summary(meetings):
    local = business_hours(parse_hours(meetings))
    pairs = [(hour, hour + TIMEZONE_OFFSET) for hour in local]
    usable = [(here, there) for here, there in pairs if there <= BUSINESS_END]
    return ["{0} local -> {1}".format(here, format_hour(there)) for here, there in usable]


def main():
    meetings = [3, 9, 10, 11, "12", 14, 18, 21]
    for line in summary(meetings):
        print(line)
    print("-" * 32)
    for block in schedule(meetings):
        print(block)
        print()


if __name__ == "__main__":
    main()

