    malformed = [index for index, row in enumerate(tables) if len(row) != 2]
    if malformed:
        raise ValueError("malformed rows at positions: %s" % malformed)
    return [(str(identifier), float(value)) for identifier, value in tables]


def extract_identifiers(rows):
    return [identifier for identifier, _ in rows]


def high_value_rows(rows):
    return [(identifier, value) for identifier, value in rows if value > 50]


def doubled_rows(rows):
    return [(identifier, value * 2) for identifier, value in rows]


def rows_starting_with_a(rows):
    return [(identifier, value) for identifier, value in rows
            if identifier.lower().startswith("a")]


def cross_product(rows, locations):
    return [(identifier, value, location)
            for identifier, value in rows
            for location in locations]


