def valid_frame(frame):
    if frame == "x":
        return True
    if len(frame) == 2 and frame[1] == "/":
        return frame[0].isdigit()
    return frame.isdigit() and 1 <= len(frame) <= 2


def digits_of(frame):
    return [int(char) for char in frame if char.isdigit()]


def throws_of(frame):
    if "x" in frame:
        return [10]
    if "/" in frame:
        first = int(frame[0])
        return [first, 10 - first]
    return digits_of(frame)


def bowl(frames):
    rounds = [frame.strip().lower() for frame in frames]
    broken = [frame for frame in rounds if not valid_frame(frame)]
    if broken:
        raise ValueError("unreadable rounds: " + ", ".join(broken))
    first_chars = [frame[0] for frame in rounds]
    first_pins = [10 if char == "x" else int(char) for char in first_chars]
    strikes = [frame for frame in rounds if "x" in frame]
    spares = [frame for frame in rounds if "/" in frame]
    plain = [frame for frame in rounds if "x" not in frame and "/" not in frame]
    plain_pins = [int(char) for frame in plain for char in frame]
    base_sums = [sum(digits_of(frame)) for frame in plain]
    stream = [pins for frame in rounds for pins in throws_of(frame)]
    total = 0
    cursor = 0
    for frame in rounds:
        throws = throws_of(frame)
        if "x" in frame:
            total += 10 + sum(stream[cursor + 1:cursor + 3])
        elif "/" in frame:
            total += 10 + sum(stream[cursor + 2:cursor + 3])
        else:
            total += sum(throws)
        cursor += len(throws)
    cheers = ["Strike! %d pins in one throw!" % 10 for _ in strikes]
    return {
        "total": total,
        "base": sum(base_sums),
        "pins_standing_after_open_rounds": 10 * len(plain) - sum(plain_pins),
        "strike_count": len(strikes),
        "spare_count": len(spares),
        "first_throws": first_pins,
        "cheers": cheers,
    }


def format_report(name, result):
    header = "%s: %d points (%d from open rounds)" % (
        name,
        result["total"],
        result["base"],
    )
    opening = "  first throws: " + " ".join(
        [str(pins) for pins in result["first_throws"]]
    )
    counts = "  %d strikes, %d spares, %d pins left standing" % (
        result["strike_count"],
        result["spare_count"],
        result["pins_standing_after_open_rounds"],
    )
    cheer_lines = ["  " + cheer for cheer in result["cheers"]]
    return "\n".join([header, opening, counts] + cheer_lines)


def main():
    games = [
        ("perfect game", ["x"] * 12),
