"""Relationship analysis for a connected system given as pairs of points."""


def validate(pairs):
    """Return the pairs as a list of 2-tuples, rejecting malformed entries."""
    bad = [item for item in pairs if not (isinstance(item, tuple) and len(item) == 2)]
    if bad:
        raise ValueError("not a connected pair: %r" % (bad[0],))
    return [(origin, destination) for origin, destination in pairs]


def unique(values):
    """Order-preserving de-duplication."""
    return list(dict.fromkeys(values))


def origins(pairs):
    return unique([origin for origin, _ in pairs])


def destinations(pairs):
    return unique([destination for _, destination in pairs])


def descending_pairs(pairs):
    return [(a, b) for a, b in pairs if a > b]


def reversed_pairs(pairs):
    return [(b, a) for a, b in pairs]


def bidirectional(pairs):
    return unique(pairs + reversed_pairs(pairs))


def categorize(points):
    """Assign each point a dummy category: its remainder modulo three."""
    return [(point, point % 3) for point in points]


def alerts(categories):
    return ["ALERT: point %d belongs to category zero" % point
            for point, category in categories if category == 0]


def color(nodes):
    pairs = validate(nodes)
    starts = origins(pairs)
    ends = destinations(pairs)
    points = unique(starts + ends)
    categories = categorize(points)
    return {
        "origins": starts,
        "destinations": ends,
        "descending": descending_pairs(pairs),
        "reversed": reversed_pairs(pairs),
        "edges": bidirectional(pairs),
        "categories": categories,
        "alerts": alerts(categories),
    }


def format_report(report):
    lines = ["origins: %s" % report["origins"],
             "destinations: %s" % report["destinations"],
             "descending connections: %s" % report["descending"],
             "reversed connections: %s" % report["reversed"],
             "bidirectional edge count: %d" % len(report["edges"])]
    lines += ["point %d -> category %d" % pair for pair in report["categories"]]
    return "\n".join(lines + report["alerts"])


def main():
    nodes = [(5, 2), (3, 9), (9, 1), (6, 6), (2, 7), (12, 4)]
    report = color(nodes)
    print(format_report(report))
    isolated = [point for point in report["origins"] if point not in report["destinations"]]
    print("origins that are never destinations: %s" % isolated)


if __name__ == "__main__":
    main()

