        result.append((b, a))
    return result


def bidirectional(pairs):
    return unique(pairs + reversed_pairs(pairs))


def categorize(points):
    """Assign each point a dummy category: its remainder modulo three."""
    result = []
    for point in points:
        result.append((point, point % 3))
    return result


def alerts(categories):
    result = []
    for point, category in categories:
        if category == 0:
            result.append("ALERT: point %d belongs to category zero" % point)
    return result


def color(nodes):
    pairs = validate(nodes)
    starts = origins(pairs)
    ends = destinations(pairs)
    points = unique(starts + ends)
    categories = categorize(points)
    return {
        "origins": starts,
        "destinations": ends,
        "descending": descending_pairs(pairs),
        "reversed": reversed_pairs(pairs),
        "edges": bidirectional(pairs),
        "categories": categories,
        "alerts": alerts(categories),
    }


def format_report(report):
    lines = ["origins: %s" % report["origins"],
             "destinations: %s" % report["destinations"],
             "descending connections: %s" % report["descending"],
             "reversed connections: %s" % report["reversed"],
             "bidirectional edge count: %d" % len(report["edges"])]
    temp = []
    for pair in report["categories"]:
        temp.append("point %d -> category %d" % pair)
    lines += temp
    return "\n".join(lines + report["alerts"])


def main():
    nodes = [(5, 2), (3, 9), (9, 1), (6, 6), (2, 7), (12, 4)]
    report = color(nodes)
    print(format_report(report))
    isolated = []
    for point in report["origins"]:
        if point not in report["destinations"]:
            isolated.append(point)
    print("origins that are never destinations: %s" % isolated)


if __name__ == "__main__":
