    bad = [name for start, end, name in events if not 0 <= start < end <= 24]
    if bad:
        raise ValueError("invalid hours for: " + ", ".join(bad))
    return events


def event_names(events):
    return [name for _, _, name in events]


def durations(events):
    return [end - start for start, end, _ in events]


def long_events(events):
    return [event for event in events if event[1] - event[0] > 2]


def start_hours(events):
    return [start for start, _, _ in events]


