    ordered = sorted(events, key=lambda event: (event[0], event[1]))
    return [
        (ordered[i], ordered[j])
        for i in range(len(ordered))
        for j in range(i + 1, len(ordered))
        if ordered[j][0] < ordered[i][1]
    ]


