def parse_entry(line):
    parts = []
    for field in line.split(","):
        parts.append(field.strip())
    if len(parts) != 3:
        raise ValueError("expected 'species, length, aggression': %r" % line)
    species, length, aggression = parts
    if not species:
        raise ValueError("species name must not be empty")
    if aggression not in ("peaceful", "aggressive"):
        raise ValueError("unknown aggression level: %r" % aggression)
    return (species, int(length), aggression)


def read_stock(lines):
    result = []
    for line in lines:
        if line.strip():
            result.append(parse_entry(line))
    return result


def balance(fishes):
    fishes = list(fishes)
    names = []
    for species, length, aggression in fishes:
        names.append(species)
    peaceful = []
    for species, length, aggression in fishes:
        if aggression == "peaceful":
            peaceful.append(species)
    aggressive_lengths = []
    for species, length, aggression in fishes:
        if aggression == "aggressive":
            aggressive_lengths.append(length)
    volumes = []
    for species, length, aggression in fishes:
        volumes.append(length * 3)
    thirsty = []
    for species, length, aggression in fishes:
        if length * 3 > 10:
            thirsty.append(species)
    labels = []
    for species in names:
        labels.append(species.upper())
    five_long = []
    for species, length, aggression in fishes:
        if length == 5:
            five_long.append(length)
    large_flags = []
    for species, length, aggression in fishes:
        large_flags.append(length > 8)
    return (names, peaceful, aggressive_lengths, volumes,
            thirsty, labels, five_long, large_flags)


def tank_volume(fishes):
    return sum(balance(fishes)[3])


def format_summary(fishes):
    (names, peaceful, aggressive_lengths, volumes,
     thirsty, labels, five_long, large_flags) = balance(fishes)
    rows = [
        ("species", ", ".join(labels)),
        ("peaceful", ", ".join(peaceful)),
        ("aggressive lengths", ", ".join(str(n) for n in aggressive_lengths)),
        ("water per fish", ", ".join(str(v) for v in volumes)),
        ("needs over 10 units", ", ".join(thirsty)),
        ("exactly five long", ", ".join(str(n) for n in five_long)),
    ]
    width = max(len(label) for label, value in rows)
    lines = []
    for label, value in rows:
        lines.append("%-*s : %s" % (width, label, value))
    big = []
    for name, is_big in zip(names, large_flags):
        if is_big:
            big.append(name)
    lines.append("%-*s : %s" % (width, "large fishes", ", ".join(big) or "none"))
    lines.append("%-*s : %d" % (width, "total water", sum(volumes)))
    return "\n".join(lines)


def main():
    stock_lines = [
        "tetra, 2, peaceful",
        "cichlid, 6, aggressive",
        "oscar, 9, aggressive",
        "guppy, 5, peaceful",
        "pleco, 12, peaceful",
    ]
    fishes = read_stock(stock_lines)
    print(format_summary(fishes))
    crowded = []
    for species, length, aggression in fishes:
        if length * 3 > tank_volume(fishes) / len(fishes):
            crowded.append(species)
    print("above average demand: " + ", ".join(crowded))
    print(balance([("tetra", 2, "peaceful"), ("cichlid", 6, "aggressive")]))


