CURRENT_YEAR_OFFSET = 30


def validate(actors):
    """Return the actor records as a list of tuples, rejecting malformed rows."""
    records = []
    for entry in actors:
        records.append(tuple(entry))
    bad_shapes = []
    for record in records:
        if len(record) != 3:
            bad_shapes.append(record)
    if bad_shapes:
        raise ValueError("each actor needs a name, an age and a vocal range: %r" % (bad_shapes,))
    bad_names = []
    for record in records:
        if not isinstance(record[0], str):
            bad_names.append(record)
    if bad_names:
        raise ValueError("actor names must be strings: %r" % (bad_names,))
    bad_ages = []
    for record in records:
        if not isinstance(record[1], int):
            bad_ages.append(record)
    if bad_ages:
        raise ValueError("actor ages must be integers: %r" % (bad_ages,))
    bad_ranges = []
    for record in records:
        if not isinstance(record[2], str):
            bad_ranges.append(record)
    if bad_ranges:
        raise ValueError("vocal ranges must be strings: %r" % (bad_ranges,))
    return records


def cast(actors):
    """Build the eight-part audition summary for a sequence of actor records."""
    records = validate(actors)
    names = []
    for name, age, vocal in records:
        names.append(name)
    young = []
    for name, age, vocal in records:
        if age < 30:
            young.append(name)
    soprano_ages = []
    for name, age, vocal in records:
        if vocal.lower() == "soprano":
            soprano_ages.append(age)
    retirement = []
    for name, age, vocal in records:
        retirement.append(age + CURRENT_YEAR_OFFSET)
    veterans = []
    for name, age, vocal in records:
        if age > 50:
            veterans.append(name)
    ranges = []
    for name, age, vocal in records:
        ranges.append(vocal.lower())
    quarter_century = []
    for name, age, vocal in records:
        if age == 25:
            quarter_century.append(age)
    senior_roles = []
    for name, age, vocal in records:
        senior_roles.append(age > 60)
    return (names, young, soprano_ages, retirement, veterans, ranges,
            quarter_century, senior_roles)


def summary_lines(actors):
    """Turn the summary into human-readable report lines."""
    (names, young, soprano_ages, retirement, veterans, ranges,
     quarter_century, senior_roles) = cast(actors)
    per_actor = []
    for name, vocal, senior in zip(names, ranges, senior_roles):
        per_actor.append(
            "%-10s retires in %2d years' time, sings %s%s"
            % (name, CURRENT_YEAR_OFFSET, vocal, " [senior role]" if senior else "")
        )
    retirement_notes = []
    for pair in zip(names, retirement):
        retirement_notes.append("%s -> %d" % pair)
    lines = list(per_actor)
    lines.append("retirement ages: " + ", ".join(retirement_notes))
    lines.append("under thirty: " + (", ".join(young) or "nobody"))
    lines.append("over fifty: " + (", ".join(veterans) or "nobody"))
    soprano_text = []
    for age in soprano_ages:
        soprano_text.append(str(age))
    lines.append("soprano ages: " + (", ".join(soprano_text) or "none"))
    lines.append("exactly twenty five: %d actor(s)" % len(quarter_century))
    return lines


def main():
    troupe = [
        ("alice", 25, "Soprano"),
        ("bob", 65, "Bass"),
        ("carla", 48, "MEZZO"),
        ("dmitri", 31, "Tenor"),
        ("elena", 25, "soprano"),
    ]
    for line in summary_lines(troupe):
        print(line)
    print()
    labels = ["names", "under 30", "soprano ages", "retirement ages",
              "over 50", "vocal ranges", "age 25", "senior eligible"]
    report = []
    for label, part in zip(labels, cast(troupe)):
        report.append("%-16s %s" % (label, part))
    for line in report:
        print(line)


if __name__ == "__main__":
