def validate(tiles):
    """Return the tiles as a list, raising ValueError on malformed entries."""
    checked = []
    for index, tile in enumerate(tiles):
        if len(tile) != 3:
            raise ValueError("tile %d must have three fields" % index)
        room, x, dirt = tile
        if not isinstance(room, str) or not room:
            raise ValueError("tile %d has no room name" % index)
        if not isinstance(x, int) or not isinstance(dirt, int):
            raise ValueError("tile %d has non-integer numbers" % index)
        if dirt < 0:
            raise ValueError("tile %d has negative dirt" % index)
        checked.append((room, x, dirt))
    return checked


def clean(tiles):
    """Build the eight itinerary lists for a sequence of floor-area tuples."""
    tiles = validate(tiles)
    rooms = []
    for room, x, dirt in tiles:
        rooms.append(room)
    dirty_rooms = []
    for room, x, dirt in tiles:
        if dirt > 0:
            dirty_rooms.append(room)
    spotless_positions = []
    for room, x, dirt in tiles:
        if dirt == 0:
            spotless_positions.append(x)
    cleaning_times = []
    for room, x, dirt in tiles:
        cleaning_times.append(dirt * 5)
    far_rooms = []
    for room, x, dirt in tiles:
        if x > 10:
            far_rooms.append(room)
    titled_rooms = []
    for room in rooms:
        titled_rooms.append(room.capitalize())
    origin_dirt = []
    for room, x, dirt in tiles:
        if x == 0:
            origin_dirt.append(dirt)
    intensive = []
    for room, x, dirt in tiles:
        intensive.append(dirt > 7)
    return (rooms, dirty_rooms, spotless_positions, cleaning_times,
            far_rooms, titled_rooms, origin_dirt, intensive)


def schedule(tiles):
    """Order the dirty tiles so the worst mess is handled first."""
    itinerary = clean(tiles)
    times = itinerary[3]
    needs_work = []
    for i in range(len(tiles)):
        if times[i] > 0:
            needs_work.append((tiles[i][0], tiles[i][1], times[i]))
    needs_work.sort(key=lambda entry: (-entry[2], entry[1]))
    return needs_work


def report(tiles):
    """Render a human readable summary of the itinerary."""
    (rooms, dirty_rooms, spotless_positions, cleaning_times,
     far_rooms, titled_rooms, origin_dirt, intensive) = clean(tiles)
    lines = ["Tiles surveyed: %d" % len(rooms)]
    lines.append("Rooms: " + ", ".join(titled_rooms))
    lines.append("Dirty rooms: " + (", ".join(dirty_rooms) or "none"))
    lines.append("Spotless at x: " + ", ".join(str(x) for x in spotless_positions))
    lines.append("Total minutes: %d" % sum(cleaning_times))
    lines.append("Beyond x=10: " + (", ".join(far_rooms) or "none"))
    lines.append("Dirt at origin: %d" % sum(origin_dirt))
    heavy = []
    for i, flag in enumerate(intensive):
        if flag:
            heavy.append(rooms[i])
    lines.append("Intensive: " + (", ".join(heavy) or "none"))
    for room, x, minutes in schedule(tiles):
        lines.append("  %-10s x=%-4d %3d min" % (room, x, minutes))
    return "\n".join(lines)


def main():
    floor = [("kitchen", 0, 8), ("hallway", 12, 0), ("study", 4, 3),
             ("porch", 18, 9), ("cellar", 0, 0)]
    print(report(floor))
    itinerary = clean(floor)
    labels = ["rooms", "dirty", "spotless_x", "minutes",
              "far", "titled", "origin_dirt", "intensive"]
    pairs = []
    for i, label in enumerate(labels):
        pairs.append("%s=%r" % (label, itinerary[i]))
    print("\n".join(pairs))


if __name__ == "__main__":
    main()

