def normalize(trails):
    """Return the trail records as clean (name, difficulty, length) tuples."""
    records = []
    for name, difficulty, length in trails:
        records.append((str(name).strip(), str(difficulty).strip().lower(), int(length)))
    bad = []
    for name, _, length in records:
        if length <= 0:
            bad.append(name)
    if bad:
        raise ValueError("non-positive trail lengths: " + ", ".join(bad))
    return records


def plan(trails):
    """Build the eight guide lists described in the mountain guide brief."""
    records = normalize(trails)
    names = []
    for name, _, _ in records:
        names.append(name)
    expert_names = []
    for name, difficulty, _ in records:
        if difficulty == "expert":
            expert_names.append(name)
    beginner_lengths = []
    for _, difficulty, length in records:
        if difficulty == "beginner":
            beginner_lengths.append(length)
    descent_times = []
    for _, _, length in records:
        descent_times.append(length / 10)
    long_names = []
    for name, _, length in records:
        if length > 500:
            long_names.append(name)
    ratings = []
    for _, difficulty, _ in records:
        ratings.append(difficulty.upper())
    exact_two_hundred = []
    for _, _, length in records:
        if length == 200:
            exact_two_hundred.append(length)
    marathon_flags = []
    for _, _, length in records:
        marathon_flags.append(length > 1000)
    return (names, expert_names, beginner_lengths, descent_times,
            long_names, ratings, exact_two_hundred, marathon_flags)


def difficulty_counts(ratings):
    """Count how many trails carry each difficulty rating."""
    labels = sorted(set(ratings))
    result = []
    for label in labels:
        result.append((label, ratings.count(label)))
    return result


def format_descent_table(names, descent_times):
    """Render one aligned line per trail showing its estimated descent time."""
    width = max(len(name) for name in names)
    result = []
    for name, minutes in zip(names, descent_times):
        result.append("{0:<{1}}  {2:>6.1f} min".format(name, width, minutes))
    return result


