def parse_vintages(lines):
    """Turn "name,year,rating" text lines into vintage tuples."""
    fields = []
    for line in lines:
        if line.strip():
            fields.append(line.split(","))
    result = []
    for f in fields:
        result.append((f[0].strip(), int(f[1]), int(f[2])))
    return result


def find_problems(vintages):
    """Describe every record that cannot be used in the report."""
    problems = []
    for v in vintages:
        if len(v) != 3:
            problems.append("%r: expected 3 fields, got %d" % (v, len(v)))
    extra = []
    for v in vintages:
        if len(v) == 3 and not 1800 <= v[1] <= 2100:
            extra.append("%s: year %r is out of range" % (v[0], v[1]))
    problems += extra
    extra = []
    for v in vintages:
        if len(v) == 3 and not 0 <= v[2] <= 100:
            extra.append("%s: rating %r is out of range" % (v[0], v[2]))
    problems += extra
    return problems


def evaluate(vintages):
    problems = find_problems(vintages)
    if problems:
        raise ValueError("; ".join(problems))
    names = []
    for name, year, rating in vintages:
        names.append(name)
    from_2010 = []
    for name, year, rating in vintages:
        if year == 2010:
            from_2010.append(name)
    chateau_ratings = []
    for name, year, rating in vintages:
        if name == "chateau":
            chateau_ratings.append(rating)
    normalized = []
    for name, year, rating in vintages:
        normalized.append(rating / 2)
    highly_rated = []
    for name, year, rating in vintages:
        if rating >= 90:
            highly_rated.append(name)
    lowercased = []
    for name, year, rating in vintages:
        lowercased.append(name.lower())
    years_at_85 = []
    for name, year, rating in vintages:
        if rating == 85:
            years_at_85.append(year)
    classics = []
    for name, year, rating in vintages:
        classics.append(year < 2000)
    return (
        names,
        from_2010,
        chateau_ratings,
        normalized,
        highly_rated,
        lowercased,
        years_at_85,
        classics,
    )


def format_report(vintages):
    """Render the eight computed lists as readable report lines."""
    labels = [
        "all vineyards",
        "2010 vintages",
        "chateau ratings",
        "normalized scores",
        "rated 90+",
        "lowercase names",
        "years scoring 85",
        "classic flags",
    ]
    sections = evaluate(vintages)
    body = []
    for label, section in zip(labels, sections):
        items = []
        for item in section:
            items.append(str(item))
        body.append("%-18s: %s" % (label, ", ".join(items) or "-"))
    average = sum(sections[3]) / len(sections[3]) if sections[3] else 0.0
    return body + ["%-18s: %.2f" % ("average score", average)]


def main():
    raw = [
        "chateau,1998,92",
        "valley,2010,85",
        "hillside,2010,90",
        "chateau,2004,78",
    ]
    vintages = parse_vintages(raw)
    for line in format_report(vintages):
        print(line)


