def _validate(poses):
    """Return the poses as a list of tuples, rejecting malformed entries."""
    entries = []
    for item in poses:
        entries.append(tuple(item))
    broken = []
    for index, item in enumerate(entries):
        if len(item) != 3:
            broken.append(index)
    if broken:
        raise ValueError("poses at %s must have three fields" % broken)
    bad_names = []
    for item in entries:
        if not isinstance(item[0], str):
            bad_names.append(item[0])
    if bad_names:
        raise TypeError("pose names must be strings: %r" % bad_names)
    bad_times = []
    for item in entries:
        if not isinstance(item[2], int):
            bad_times.append(item[0])
    if bad_times:
        raise TypeError("hold times must be integers: %r" % bad_times)
    return entries


def flow(poses):
    """Build the eight lists that make up a class instructional plan."""
    entries = _validate(poses)
    names = []
    for name, category, hold in entries:
        names.append(name)
    standing = []
    for name, category, hold in entries:
        if category == "standing":
            standing.append(name)
    resting_holds = []
    for name, category, hold in entries:
        if category == "resting":
            resting_holds.append(hold)
    beginner_holds = []
    for name, category, hold in entries:
        beginner_holds.append(hold / 2)
    long_holds = []
    for name, category, hold in entries:
        if hold > 60:
            long_holds.append(name)
    categories_upper = []
    for name, category, hold in entries:
        categories_upper.append(category.upper())
    lotus_holds = []
    for name, category, hold in entries:
        if name == "lotus":
            lotus_holds.append(hold)
    even_holds = []
    for name, category, hold in entries:
        even_holds.append(hold % 2 == 0)
    return (
        names,
        standing,
        resting_holds,
        beginner_holds,
        long_holds,
        categories_upper,
        lotus_holds,
        even_holds,
    )


def category_totals(poses):
    """List every category with the total seconds spent in it, alphabetically."""
    entries = _validate(poses)
    _categories = []
    for name, category, hold in entries:
        _categories.append(category)
    labels = sorted(set(_categories))
    _totals = []
    for label in labels:
        _holds = []
        for name, category, hold in entries:
            if category == label:
                _holds.append(hold)
        _totals.append((label, sum(_holds)))
    return _totals


def plan_report(poses):
    """Render the plan as a list of printable report lines."""
    names, standing, resting, beginner, long_holds, upper, lotus, even = flow(poses)
    lines = ["Poses: " + ", ".join(names)]
    lines.append("Standing: " + ", ".join(standing) if standing else "Standing: none")
    lines.append("Resting seconds: %d" % sum(resting))
    beginner_text = []
    for pair in zip(names, beginner):
        beginner_text.append("%s %.1fs" % pair)
    lines.append("Beginner: " + ", ".join(beginner_text))
    lines.append("Held over a minute: " + ", ".join(long_holds))
    lines.append("Categories: " + " ".join(upper))
    if lotus:
        lines.append("Lotus seconds: %s" % lotus)
    lines.append("Even holds: %d of %d" % (even.count(True), len(even)))
    _lines = []
    for pair in category_totals(poses):
        _lines.append("  %-10s %4ds" % pair)
    lines.extend(_lines)
    return lines


