def validate(panels):
    """Return the panel tuples after checking their shape and value ranges."""
    malformed = []
    for entry in panels:
        if len(entry) != 3:
            malformed.append(entry)
    if malformed:
        raise ValueError("each panel needs a location, an exposure and a voltage: %r" % (malformed,))
    bad_exposure = []
    for entry in panels:
        if not 0 <= entry[1] <= 100:
            bad_exposure.append(entry[0])
    if bad_exposure:
        raise ValueError("exposure must be between 0 and 100: %s" % ", ".join(bad_exposure))
    negative_voltage = []
    for entry in panels:
        if entry[2] < 0:
            negative_voltage.append(entry[0])
    if negative_voltage:
        raise ValueError("voltage cannot be negative: %s" % ", ".join(negative_voltage))
    result = []
    for entry in panels:
        result.append(tuple(entry))
    return result


def optimize(panels):
    """Compute the eight energy yield lists for a sequence of panel records."""
    checked = validate(panels)
    locations = []
    for location, _exposure, _voltage in checked:
        locations.append(location)
    full_sun = []
    for location, exposure, _voltage in checked:
        if exposure == 100:
            full_sun.append(location)
    low_sun_voltages = []
    for _location, exposure, voltage in checked:
        if exposure < 50:
            low_sun_voltages.append(voltage)
    wattage = []
    for _location, _exposure, voltage in checked:
        wattage.append(voltage * 5)
    strong = []
    for location, _exposure, voltage in checked:
        if voltage > 30:
            strong.append(location)
    upper = []
    for location, _exposure, _voltage in checked:
        upper.append(location.upper())
    three_quarter_sun = []
    for _location, exposure, voltage in checked:
        if exposure == 75:
            three_quarter_sun.append(voltage)
    underperforming = []
    for _location, _exposure, voltage in checked:
        underperforming.append(voltage < 10)
    return (
        locations,
        full_sun,
        low_sun_voltages,
        wattage,
        strong,
        upper,
        three_quarter_sun,
        underperforming,
    )


def yield_table(panels):
    """Render one aligned line per panel showing its estimated wattage and status."""
    locations, _full, _low, wattage, _strong, _upper, _three, weak = optimize(panels)
    lengths = []
    for location in locations:
        lengths.append(len(location))
    width = max(lengths) if locations else 0
    statuses = []
    for flag in weak:
        statuses.append("underperforming" if flag else "nominal")
    rows = zip(locations, wattage, statuses)
    lines = []
    for name, watts, status in rows:
        lines.append("%-*s %5d W  %s" % (width, name, watts, status))
    return lines


def summary(panels):
    """Describe the fleet: totals, best producers and panels needing attention."""
    _loc, full_sun, low_sun, wattage, strong, upper, three_quarter, weak = optimize(panels)
    lines = ["panels: %d" % len(upper), "total estimated wattage: %d W" % sum(wattage)]
    lines.append("full sunlight: %s" % (", ".join(full_sun) or "none"))
    lines.append("above 30 V: %s" % (", ".join(strong) or "none"))
    shaded = []
    for voltage in low_sun:
        shaded.append(str(voltage))
    lines.append("voltages under 50%% exposure: %s" % (", ".join(shaded) or "none"))
    partial = []
    for voltage in three_quarter:
        partial.append(str(voltage))
    lines.append("voltages at 75%% exposure: %s" % (", ".join(partial) or "none"))
    lines.append("underperforming count: %d" % weak.count(True))
    return lines


