def analyze(words):
    prefixes = []
    for word in words:
        prefixes.append(word[:3])
    ing_words = []
    for word in words:
        if word.endswith("ing"):
            ing_words.append(word)
    lengths = []
    for word in words:
        lengths.append(len(word))
    capitalized = []
    for word in words:
        capitalized.append(word.capitalize())
    five_letter = []
    for word in words:
        if len(word) == 5:
            five_letter.append(word)
    a_to_e = []
    for word in words:
        a_to_e.append(word.replace("a", "e"))
    with_z = []
    for word in words:
        if "z" in word:
            with_z.append(word)
    is_long = []
    for word in words:
        is_long.append(len(word) > 10)
    return (prefixes, ing_words, lengths, capitalized,
            five_letter, a_to_e, with_z, is_long)


def clean_tokens(raw):
    stripped = []
    for token in raw:
        stripped.append(token.strip())
    result = []
    for token in stripped:
        if token:
            result.append(token.lower())
    return result


def label_rows(words, result):
    prefixes, _ing, lengths, capitalized, _five, a_to_e, _z, is_long = result
    rows = []
    for index, word in enumerate(words):
        rows.append({
            "word": word,
            "prefix": prefixes[index],
            "length": lengths[index],
            "title": capitalized[index],
            "vowel_shift": a_to_e[index],
            "long": is_long[index],
        })
    return rows


def format_table(rows):
    headers = ["word", "prefix", "length", "title", "vowel_shift", "long"]
    widths = []
    for header in headers:
        row_lengths = []
        for row in rows:
            row_lengths.append(len(str(row[header])))
        widths.append(max([len(header)] + row_lengths))
    cells = []
    for header, width in zip(headers, widths):
        cells.append(header.ljust(width))
    dashes = []
    for width in widths:
        dashes.append("-" * width)
    lines = ["  ".join(cells), "  ".join(dashes)]
    for row in rows:
        values = []
        for header, width in zip(headers, widths):
            values.append(str(row[header]).ljust(width))
        lines.append("  ".join(values))
    return "\n".join(lines)


def summarize(words, result):
    prefixes, ing_words, lengths, _cap, five_letter, _ae, with_z, is_long = result
    average = sum(lengths) / len(lengths) if lengths else 0.0
    unique_prefixes = sorted(set(prefixes))
    long_flags = []
    for flag in is_long:
        if flag:
            long_flags.append(flag)
    long_count = len(long_flags)
    facts = [
        "tokens: %d" % len(words),
        "average length: %.2f" % average,
        "distinct prefixes: %s" % ", ".join(unique_prefixes),
        "ing-suffixed: %s" % (", ".join(ing_words) or "none"),
        "five-letter: %s" % (", ".join(five_letter) or "none"),
        "contains z: %s" % (", ".join(with_z) or "none"),
        "longer than ten: %d" % long_count,
    ]
    return facts


