def normalize(ancestors):
    """Strip and lower-case the text fields, coercing birth years to int."""
    malformed = []
    for index, record in enumerate(ancestors):
        if len(record) != 3:
            malformed.append(index)
    if malformed:
        raise ValueError("records at positions %s do not have three fields" % malformed)
    _result = []
    for name, year, country in ancestors:
        _result.append((name.strip().lower(), int(year), country.strip().lower()))
    return _result


def parse(ancestors):
    """Build the eight lineage lists described by the report specification."""
    people = normalize(ancestors)
    names = []
    for name, _, _ in people:
        names.append(name)
    born_before_1850 = []
    for name, year, _ in people:
        if year < 1850:
            born_before_1850.append(name)
    irish_birth_years = []
    for _, year, country in people:
        if country == "ireland":
            irish_birth_years.append(year)
    ages_in_1900 = []
    for _, year, _ in people:
        ages_in_1900.append(1900 - year)
    italian_names = []
    for name, _, country in people:
        if country == "italy":
            italian_names.append(name)
    countries_upper = []
    for _, _, country in people:
        countries_upper.append(country.upper())
    john_birth_years = []
    for name, year, _ in people:
        if name == "john":
            john_birth_years.append(year)
    leap_year_flags = []
    for _, year, _ in people:
        leap_year_flags.append(year % 4 == 0)
    return (names, born_before_1850, irish_birth_years, ages_in_1900,
            italian_names, countries_upper, john_birth_years, leap_year_flags)


def country_counts(countries_upper):
    """Map each country label to how many ancestors came from it."""
    return {country: countries_upper.count(country) for country in sorted(set(countries_upper))}


def format_report(ancestors):
    """Render the lineage report as a list of printable lines."""
    (names, early, irish_years, ages, italians,
     countries_upper, johns, leaps) = parse(ancestors)
    lines = []
    for name, age in zip(names, ages):
        lines.append("%s was %d years old in 1900" % (name.title(), age))
    _early_lines = []
    for name in early:
        _early_lines.append("%s was born before 1850" % name.title())
    lines += _early_lines
    _italian_lines = []
    for name in italians:
        _italian_lines.append("%s came from Italy" % name.title())
    lines += _italian_lines
    _john_lines = []
    for year in johns:
        _john_lines.append("an ancestor named John was born in %d" % year)
    lines += _john_lines
    _irish_lines = []
    for year in irish_years:
        _irish_lines.append("Irish ancestor born in %d" % year)
    lines += _irish_lines
    _country_lines = []
    for country, count in country_counts(countries_upper).items():
        _country_lines.append("%s: %d ancestor(s)" % (country, count))
    lines += _country_lines
    leap_names = []
    for name, is_leap in zip(names, leaps):
        if is_leap:
            leap_names.append(name)
    lines.append("born in a leap year: %s" % ", ".join(leap_names))
    return lines


def oldest_generation(ancestors):
    """Names of the ancestors sharing the earliest birth year on record."""
    people = normalize(ancestors)
    earliest = min(year for _, year, _ in people)
    _result = []
    for name, year, _ in people:
        if year == earliest:
            _result.append(name)
    return _result


