def validate(sculptures):
    """Return the entries as a list of tuples, rejecting malformed records."""
    records = []
    for item in sculptures:
        records.append(tuple(item))
    wrong_size = []
    for i, rec in enumerate(records):
        if len(rec) != 3:
            wrong_size.append(i)
    if wrong_size:
        raise ValueError("records %s do not have three fields" % wrong_size)
    bad_text = []
    for i, rec in enumerate(records):
        if not isinstance(rec[0], str) or not isinstance(rec[1], str):
            bad_text.append(i)
    if bad_text:
        raise ValueError("records %s have non-string shape or material" % bad_text)
    bad_volume = []
    for i, rec in enumerate(records):
        if not isinstance(rec[2], int) or rec[2] < 0:
            bad_volume.append(i)
    if bad_volume:
        raise ValueError("records %s have an invalid volume" % bad_volume)
    return records


def estimate(sculptures):
    """Build the eight foundry manifest lists for the given sculptures."""
    records = validate(sculptures)
    shapes = []
    for shape, _material, _volume in records:
        shapes.append(shape)
    bronze_shapes = []
    for shape, material, _volume in records:
        if material == "bronze":
            bronze_shapes.append(shape)
    cube_volumes = []
    for shape, _material, volume in records:
        if shape == "cube":
            cube_volumes.append(volume)
    masses = []
    for _shape, _material, volume in records:
        masses.append(volume * 8)
    large_shapes = []
    for shape, _material, volume in records:
        if volume > 100:
            large_shapes.append(shape)
    loud_materials = []
    for _shape, material, _volume in records:
        loud_materials.append(material.upper())
    clay_volumes = []
    for _shape, material, volume in records:
        if material == "clay":
            clay_volumes.append(volume)
    round_volumes = []
    for _shape, _material, volume in records:
        round_volumes.append(volume % 10 == 0)
    return (shapes, bronze_shapes, cube_volumes, masses,
            large_shapes, loud_materials, clay_volumes, round_volumes)


def material_totals(sculptures):
    """Total volume ordered by material name."""
    records = validate(sculptures)
    materials = sorted(set(material for _shape, material, _volume in records))
    result = []
    for m in materials:
        result.append((m, sum(v for _s, mat, v in records if mat == m)))
    return result


def format_manifest(sculptures):
    """Render the manifest and the per-material totals as report lines."""
    manifest = estimate(sculptures)
    labels = ["shapes", "bronze shapes", "cube volumes", "masses",
              "volume > 100", "materials", "clay volumes", "multiple of 10"]
    lines = []
    for label, values in zip(labels, manifest):
        lines.append("%-15s %s" % (label, values))
    totals = material_totals(sculptures)
    _totals_lines = []
    for material, volume in totals:
        _totals_lines.append("total %-9s %d" % (material, volume))
    lines += _totals_lines
    heaviest = max(manifest[3]) if manifest[3] else 0
    lines.append("%-15s %d" % ("heaviest mass", heaviest))
    return lines


