def validate(events):
    """Check the raw event records before any analysis is attempted."""
    malformed = []
    for index, record in enumerate(events):
        if len(record) != 4:
            malformed.append(index)
    if malformed:
        raise ValueError(f"records with wrong arity at positions: {malformed}")
    non_numeric = []
    for name, start, end, _ in events:
        if not isinstance(start, int) or not isinstance(end, int):
            non_numeric.append(name)
    if non_numeric:
        raise TypeError(f"non-integer years in: {non_numeric}")
    reversed_spans = []
    for name, start, end, _ in events:
        if start > end:
            reversed_spans.append(name)
    if reversed_spans:
        raise ValueError(f"end year precedes start year in: {reversed_spans}")
    return list(events)


def correlate(events):
    """Return ancient names, long-event timelines, European centuries and single-year events."""
    records = validate(events)
    ancient_names = []
    for name, start, _, _ in records:
        if start < 0:
            ancient_names.append(name)
    durations = []
    for _, start, end, _ in records:
        durations.append(end - start)
    long_events = []
    for record, span in zip(records, durations):
        if span > 100:
            long_events.append((record[0], span))
    timelines = []
    for name, span in long_events:
        timelines.append(f"{name}: {span}")
    european = []
    for record in records:
        if record[3] == "Europe":
            european.append(record)
    european_centuries = []
    for _, start, _, _ in european:
        european_centuries.append(start // 100)
    single_year = []
    for record in records:
        if record[1] == record[2]:
            single_year.append(record)
    return ancient_names, timelines, european_centuries, single_year


def region_counts(events):
    """Count how many events each region contributes."""
    regions = sorted({region for *_, region in events})
    result = []
    for region in regions:
        result.append((region, sum(1 for *_, name in events if name == region)))
    return result


def century_label(century):
    """Human readable label for a floor-divided century value."""
    if century < 0:
        return f"{abs(century)}th century BCE"
    return f"{century + 1}th century CE"


def summarize(events):
    """Build a printable report out of the correlation results."""
    ancient_names, timelines, centuries, single_year = correlate(events)
    lines = ["Ancient events: " + (", ".join(ancient_names) or "none")]
    lines.append("Events longer than a century:")
    _entries = []
    for entry in timelines:
        _entries.append(f"  {entry}")
    lines.extend(_entries)
    lines.append("European starting centuries:")
    _centuries = []
    for value in centuries:
        _centuries.append(f"  {century_label(value)}")
    lines.extend(_centuries)
    _single_year_names = []
    for record in single_year:
        _single_year_names.append(record[0])
    lines.append("Single-year events: " + (", ".join(_single_year_names) or "none"))
    lines.append("Events per region:")
    _region_lines = []
    for region, count in region_counts(events):
        _region_lines.append(f"  {region}: {count}")
    lines.extend(_region_lines)
    return "\n".join(lines)


def main():
    events = [
        ("Rome", -753, 476, "Europe"),
        ("Ptolemaic Egypt", -305, -30, "Africa"),
        ("Battle of Hastings", 1066, 1066, "Europe"),
        ("Han Dynasty", -206, 220, "Asia"),
        ("Moon Landing", 1969, 1969, "America"),
        ("Byzantine Empire", 330, 1453, "Europe"),
    ]
    print(correlate([("Rome", -753, 476, "Europe")]))
    print(summarize(events))


if __name__ == "__main__":
    main()

