HUB_CODE = "LHR"
DOMESTIC_PREFIX = "DOM"
OVERSIZE_LIMIT = 50
FRAGILE_LIMIT = 10


def parse_manifest(lines):
    """Turn 'name,flight,weight,destination' text rows into bag tuples."""
    rows = []
    for line in lines:
        if line.strip():
            rows.append(line.split(","))
    result = []
    for n, f, w, d in rows:
        result.append((n.strip(), f.strip().upper(), int(w), d.strip().upper()))
    return result


def find_invalid(bags):
    """Report bags whose recorded weight cannot come from a real scale."""
    result = []
    for name, flight, weight, _ in bags:
        if weight <= 0:
            result.append(f"{name}/{flight}: invalid weight {weight}")
    return result


def accepted(bags):
    result = []
    for bag in bags:
        if bag[2] > 0:
            result.append(bag)
    return result


def route(bags):
    oversized = []
    for bag in bags:
        if bag[2] > OVERSIZE_LIMIT:
            oversized.append(bag)
    oversized_warnings = []
    for bag in oversized:
        oversized_warnings.append(bag[0])
    excess_weights = []
    for bag in oversized:
        excess_weights.append(bag[2] - OVERSIZE_LIMIT)
    international = []
    for bag in bags:
        if bag[3] == HUB_CODE:
            international.append(bag)
    routing_tags = []
    for bag in international:
        routing_tags.append(f"{bag[3]}/{bag[1]}")
    domestic = []
    for bag in bags:
        if bag[1].startswith(DOMESTIC_PREFIX):
            domestic.append(bag)
    domestic_weights = []
    for bag in domestic:
        domestic_weights.append(bag[2])
    fragile_alerts = []
    for bag in bags:
        if bag[2] < FRAGILE_LIMIT:
            fragile_alerts.append(f"FRAGILE: {bag[0]} on {bag[1]} ({bag[2]} lb)")
    return (oversized_warnings, excess_weights, routing_tags,
            domestic_weights, fragile_alerts)


def format_report(bags, result):
    warnings, excess, tags, weights, fragile = result
    lines = [f"Processed {len(bags)} bag(s)"]
    _extra = []
    for name, over in zip(warnings, excess):
        _extra.append(f"  OVERSIZE {name}: {over} lb over the limit")
    lines += _extra
    _extra = []
    for tag in tags:
        _extra.append(f"  ROUTE {tag} -> international hub")
    lines += _extra
    lines.append(f"  DOMESTIC load: {sum(weights)} lb across {len(weights)} bag(s)")
    _extra = []
    for alert in fragile:
        _extra.append(f"  {alert}")
    lines += _extra
    return "\n".join(lines)


def main():
    manifest = [
        "Smith,DOM123,55,JFK",
        "Okafor,INT880,62,LHR",
        "Reyes,DOM204,8,ORD",
        "Chen,INT451,23,LHR",
        "Novak,DOM317,49,ATL",
        "Bad Record,DOM999,0,JFK",
    ]
    bags = parse_manifest(manifest)
    for problem in find_invalid(bags):
        print("REJECTED", problem)
    clean = accepted(bags)
    print(format_report(clean, route(clean)))
    print(route([("Smith", "DOM123", 55, "JFK")]))


if __name__ == "__main__":
    main()

