def validate(pets):
    """Return the pets that are well formed, rejecting any malformed record."""
    malformed = [entry for entry in pets if len(entry) != 4]
    if malformed:
        raise ValueError("malformed pet records: {}".format(malformed))
    bad_levels = [entry for entry in pets if not 0 <= entry[2] <= 100]
    if bad_levels:
        raise ValueError("hunger out of range: {}".format(bad_levels))
    return list(pets)


def roll_call(pets):
    return [name for name, _species, _hunger, _happiness in pets]


def hungry_group(pets):
    return [pet for pet in pets if pet[2] > 80]


def feeding_alerts(pets):
    return ["Feed {}".format(pet[0]) for pet in hungry_group(pets)]


def mood_scores(pets):
    return [happiness - hunger for _name, _species, hunger, happiness in pets]


def dragons(pets):
    return [pet for pet in pets if pet[1] == "dragon"]


def dragon_happiness(pets):
    return [happiness for _name, _species, _hunger, happiness in dragons(pets)]


def happy_pets(pets):
    return [pet for pet in pets if pet[2] < 20 and pet[3] > 80]


def action_items(pets):
    return ["Play with {}".format(name) for name, _s, _h, happiness in pets
            if happiness < 50]


def manage(pets):
    checked = validate(pets)
    return (roll_call(checked),
            feeding_alerts(checked),
            mood_scores(checked),
            dragon_happiness(checked),
            happy_pets(checked),
            action_items(checked))


def format_report(pets):
    names, alerts, moods, scaly_joy, content, actions = manage(pets)
    mood_lines = ["  {}: mood {:+d}".format(name, score)
                  for name, score in zip(names, moods)]
    content_names = [pet[0] for pet in content]
    lines = ["Roll call: " + ", ".join(names)]
    lines.extend(mood_lines)
    lines.extend(["ALERT: " + alert for alert in alerts])
    lines.extend(["TODO: " + item for item in actions])
    if scaly_joy:
        lines.append("Dragon happiness: average {:.1f}".format(
            sum(scaly_joy) / len(scaly_joy)))
    if content_names:
        lines.append("Full and happy: " + ", ".join(content_names))
    return lines


def main():
    pets = [("Rex", "dog", 90, 100),
