            ("Norbert", "dragon", 85, 40),
            ("Mittens", "cat", 10, 88),
            ("Bubbles", "fish", 45, 30)]
    for line in format_report(pets):
        print(line)
    print(manage([("Rex", "dog", 90, 100)]))


if __name__ == "__main__":
