        if len(entry) != 4:
            bad.append(entry)
    if bad:
        raise ValueError("malformed module records: %r" % (bad,))
    checked = []
    for name, o2, pw, crew in modules:
        checked.append((str(name), float(o2), float(pw), int(crew)))
    negatives = []
    for name, o2, pw, crew in checked:
        if o2 < 0 or pw < 0 or crew < 0:
            negatives.append(name)
    if negatives:
        raise ValueError("negative values in: %s" % ", ".join(negatives))
    return checked


def allocate(modules):
    """Verify life support for a list of (name, oxygen, power, crew) modules."""
    records = validate(modules)
    resource_loads = []
    for name, o2, pw, crew in records:
        resource_loads.append(o2 + pw)
    crewed_names = []
    for name, o2, pw, crew in records:
        if crew > 0:
            crewed_names.append(name)
    high_power = []
    for m in records:
        if m[2] > 50:
            high_power.append(m)
    high_power_statuses = []
    for name, o2, pw, crew in high_power:
        high_power_statuses.append("%s: %d" % (name, crew))
    active_modules = []
    for m in records:
        if not (m[3] == 0 and m[1] == 0):
            active_modules.append(m)
    crewed_oxygen = []
    for name, o2, pw, crew in records:
        if crew > 0:
            crewed_oxygen.append(o2)
    oxygen_heavy = []
    for m in records:
        if m[1] > m[2]:
            oxygen_heavy.append(m)
    warnings = []
    for name, o2, pw, crew in records:
        if pw > 90:
            warnings.append("WARNING: %s draws %.0f units of power" % (name, pw))
    return (resource_loads, crewed_names, high_power_statuses, active_modules,
            crewed_oxygen, oxygen_heavy, warnings)


def berth_summary(active_modules):
    """Summarise berths per active module and the station total."""
    berths = []
    for name, o2, pw, crew in active_modules:
        berths.append((name, crew))
    total = sum(crew for name, crew in berths)
    return berths, total


def format_report(modules):
    loads, crewed, statuses, active, oxygen, heavy, warnings = allocate(modules)
    berths, total_berths = berth_summary(active)
    lines = ["Station life support report", "-" * 27]
    temp_list1 = []
    for m, load in zip(validate(modules), loads):
        temp_list1.append("%-10s load=%6.1f" % (m[0], load))
    lines += temp_list1
    lines.append("Crewed modules: %s" % (", ".join(crewed) or "none"))
    temp_list2 = []
    for status in statuses:
        temp_list2.append("High power -> " + status)
    lines += temp_list2
    lines.append("Active modules: %d of %d" % (len(active), len(modules)))
    lines.append("Crewed oxygen draw: %.1f" % sum(oxygen))
    temp_list3 = []
    for name, o2, pw, crew in heavy:
        temp_list3.append("Oxygen-heavy: %s" % name)
    lines += temp_list3
    lines += warnings
    temp_list4 = []
    for name, crew in berths:
        if crew:
            temp_list4.append("Berths in %s: %d" % (name, crew))
    lines += temp_list4
    lines.append("Total berths: %d" % total_berths)
    return "\n".join(lines)


def main():
    station = [
        ("Hab", 20, 60, 4),
        ("Lab", 15, 95, 3),
        ("Storage", 0, 10, 0),
        ("Greenhouse", 70, 40, 2),
        ("Reactor", 5, 120, 0),
    ]
    print(format_report(station))
    print()
    print(allocate([("Hab", 20, 60, 4)]))


if __name__ == "__main__":
    main()

