PEANUT_WORDS = ("peanut", "groundnut")
DAIRY_WORDS = ("milk", "cheese", "butter", "cream", "yogurt")


def matching_ingredients(ingredients, words):
    result = []
    for item in ingredients:
        if any(w in item.lower() for w in words):
            result.append(item)
    return result


def has_peanuts(ingredients):
    return bool(matching_ingredients(ingredients, PEANUT_WORDS))


def has_dairy(ingredients):
    return bool(matching_ingredients(ingredients, DAIRY_WORDS))


def validate(meals):
    malformed = []
    for meal in meals:
        if len(meal) != 4:
            malformed.append(meal)
    if malformed:
        raise ValueError("each meal needs name, ingredients, calories, vegetarian flag")
    empty = []
    for name, ingredients, _, _ in meals:
        if not ingredients:
            empty.append(name)
    if empty:
        raise ValueError("meals without ingredients: " + ", ".join(empty))


def scan(meals):
    validate(meals)
    vegetarian_names = []
    for name, _, _, veg in meals:
        if veg:
            vegetarian_names.append(name)
    peanut_meals = []
    for meal in meals:
        if has_peanuts(meal[1]):
            peanut_meals.append(meal)
    calorie_densities = []
    for _, ingredients, calories, _ in meals:
        calorie_densities.append(calories / len(ingredients))
    simple_meals = []
    for meal in meals:
        if len(meal[1]) < 5:
            simple_meals.append(meal)
    menu_descriptions = []
    for name, _, calories, _ in simple_meals:
        menu_descriptions.append(f"{name}: {calories}")
    meat_ingredients = []
    for _, ingredients, _, veg in meals:
        if not veg:
            meat_ingredients.append(ingredients)
    heavy_meals = []
    for meal in meals:
        if meal[2] > 800:
            heavy_meals.append(meal)
    warning_labels = []
    for name, ingredients, _, _ in meals:
        if has_dairy(ingredients):
            warning_labels.append(
                f"WARNING: {name} contains dairy ({', '.join(matching_ingredients(ingredients, DAIRY_WORDS))})"
            )
    return (vegetarian_names, peanut_meals, calorie_densities, simple_meals,
            menu_descriptions, meat_ingredients, heavy_meals, warning_labels)


def report(meals):
    (veg, peanut, densities, simple, descriptions,
     meats, heavy, warnings) = scan(meals)
    lines = ["Vegetarian meals: " + (", ".join(veg) or "none")]
    _peanut_lines = []
    for meal in peanut:
        _peanut_lines.append(f"Peanut allergen in {meal[0]}")
    lines += _peanut_lines
    _density_lines = []
    for (name, _, _, _), density in zip(meals, densities):
        _density_lines.append(f"Density {name}: {density:.1f} kcal/ingredient")
    lines += _density_lines
    _simple_lines = []
    for text in descriptions:
        _simple_lines.append(f"Simple menu -> {text}")
    lines += _simple_lines
    flat_meat = []
    for group in meats:
        for item in group:
            flat_meat.append(item)
    lines.append("Meat-side ingredients: " + (", ".join(sorted(set(flat_meat))) or "none"))
    _heavy_lines = []
    for name, _, calories, _ in heavy:
        _heavy_lines.append(f"Heavy: {name} at {calories} kcal")
    lines += _heavy_lines
    lines.extend(warnings)
    lines.append(f"{len(simple)} of {len(meals)} meals are simple")
    return lines


def main():
    meals = [
        ("Salad", ["lettuce", "tomato", "olive oil"], 180, True),
        ("Peanut Stir Fry", ["noodles", "peanut butter", "pepper", "soy sauce", "tofu"], 820, True),
        ("Steak Plate", ["beef steak", "butter", "potato"], 950, False),
        ("Cheese Omelette", ["egg", "cheddar cheese", "milk"], 430, True),
        ("Chicken Wrap", ["tortilla", "chicken", "yogurt sauce", "lettuce"], 610, False),
    ]
    for line in report(meals):
        print(line)


if __name__ == "__main__":
    main()

