def parse_roster(lines):
    records = []
    for line in lines:
        if line.strip():
            records.append(line.strip())
    rows = []
    for record in records:
        rows.append(record.split(","))
    for row in rows:
        if len(row) != 4:
            raise ValueError("expected username,rating,ping,role but got: %r" % (row,))
    _result = []
    for r in rows:
        _result.append((r[0].strip(), int(r[1]), int(r[2]), r[3].strip().lower()))
    return _result


def matchmake(players):
    lobby = []
    for name, rating, ping, role in players:
        lobby.append(name)
    high_ping = []
    for p in players:
        if p[2] > 100:
            high_ping.append(p)
    skill_tiers = []
    for name, rating, ping, role in players:
        skill_tiers.append(rating / 500)
    support_players = []
    for p in players:
        if p[3] == "support":
            support_players.append(p)
    invites = []
    for p in support_players:
        invites.append("Invite %s (rating %d)" % (p[0], p[1]))
    damage_ratings = []
    for name, rating, ping, role in players:
        if role == "damage":
            damage_ratings.append(rating)
    elite = []
    for p in players:
        if p[1] > 2000 and p[2] < 50:
            elite.append(p)
    warnings = []
    for p in players:
        if p[2] > 200:
            warnings.append("%s has unstable ping: %dms" % (p[0], p[2]))
    return (lobby, high_ping, skill_tiers, support_players, invites,
            damage_ratings, elite, warnings)


def average(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def tier_summary(lobby, skill_tiers):
    pairs = list(zip(lobby, skill_tiers))
    _result = []
    for name, tier in pairs:
        _result.append("%s -> tier %.1f" % (name, tier))
    return _result


def format_report(result):
    lobby, high_ping, skill_tiers, support_players, invites, damage_ratings, elite, warnings = result
    lines = ["Lobby (%d): %s" % (len(lobby), ", ".join(lobby))]
    lines.extend(tier_summary(lobby, skill_tiers))
    lines.append("Average damage rating: %.1f" % average(damage_ratings))
    lines.extend("Laggy: %s (%dms)" % (p[0], p[2]) for p in high_ping)
    lines.extend(invites)
    _support_names = []
    for p in support_players:
        _support_names.append(p[0])
    lines.append("Support roster: %s" % ", ".join(_support_names))
    _elite_names = []
    for p in elite:
        _elite_names.append(p[0])
    lines.append("Elite squad: %s" % ", ".join(_elite_names))
    lines.extend(warnings)
    return lines


def main():
    roster_lines = [
        "Pro, 2500, 20, damage",
        "Medic, 1800, 140, support",
        "Tank, 900, 45, tank",
        "Sniper, 2200, 35, damage",
        "Healer, 2400, 260, support",
    ]
    players = parse_roster(roster_lines)
    result = matchmake(players)
    for line in format_report(result):
        print(line)
    solo = matchmake([("Pro", 2500, 20, "damage")])
    print(solo)


if __name__ == "__main__":
    main()

