def parse_source(text):
    """Turn raw source text into (lineno, raw, indent, is_comment) tuples."""
    numbered = list(enumerate(text.splitlines(), 1))
    _ret = []
    for n, raw in numbered:
        if raw.strip():
            _ret.append((n, raw, len(raw) - len(raw.lstrip(" ")), raw.strip().startswith("#")))
    return _ret


def validate(lines):
    """Reject malformed records before tokenizing."""
    wrong_arity = []
    for line in lines:
        if len(line) != 4:
            wrong_arity.append(line)
    if wrong_arity:
        raise ValueError("records must be 4-tuples: %r" % (wrong_arity,))
    bad_indent = []
    for line in lines:
        if not isinstance(line[2], int) or line[2] < 0:
            bad_indent.append(line[0])
    if bad_indent:
        raise ValueError("invalid indentation on lines %r" % (bad_indent,))
    return lines


def tokenize(lines):
    raw_strings = []
    for _, raw, _, _ in lines:
        raw_strings.append(raw)
    comment_lines = []
    for line in lines:
        if line[3]:
            comment_lines.append(line)
    block_depths = []
    for _, _, indent, _ in lines:
        block_depths.append(indent // 4)
    return_lines = []
    for line in lines:
        if "return" in line[1]:
            return_lines.append(line)
    syntax_nodes = []
    for n, _, indent, c in lines:
        if not c:
            syntax_nodes.append("%d: %d" % (n, indent // 4))
    comment_indents = []
    for _, _, indent, c in lines:
        if c:
            comment_indents.append(indent)
    whitespace_lines = []
    for line in lines:
        if line[1].endswith(" "):
            whitespace_lines.append(line)
    stripped_strings = []
    for _, raw, _, _ in lines:
        stripped_strings.append(raw.strip())
    return (
        raw_strings,
        comment_lines,
        block_depths,
        return_lines,
        syntax_nodes,
        comment_indents,
        whitespace_lines,
        stripped_strings,
    )


FIELDS = (
    "raw strings",
    "comment lines",
    "block depths",
    "return lines",
    "syntax nodes",
    "comment indents",
    "trailing whitespace",
