def validate(segments):
    """Return a list of human-readable problems found in the raw segment list."""
    bad_shape = []
    for i, seg in enumerate(segments):
        if len(seg) != 4:
            bad_shape.append(i)
    problems = []
    for i in bad_shape:
        problems.append("segment %d does not have 4 fields" % i)
    if bad_shape:
        return problems
    reversed_times = []
    for i, seg in enumerate(segments):
        if seg[2] < seg[1]:
            reversed_times.append(i)
    _tmp = []
    for i in reversed_times:
        _tmp.append("segment %d ends before it starts" % i)
    problems += _tmp
    empty_text = []
    for i, seg in enumerate(segments):
        if not seg[3].strip():
            empty_text.append(i)
    _tmp = []
    for i in empty_text:
        _tmp.append("segment %d has no transcript" % i)
    problems += _tmp
    return problems


def normalize(segments):
    """Lowercase speaker names and collapse whitespace inside the transcripts."""
    _result = []
    for s, start, end, t in segments:
        _result.append((s.lower(), start, end, " ".join(t.split())))
    return _result


def align(segments):
    durations = []
    for _, start, end, _ in segments:
        durations.append(end - start)
    host_text = []
    for speaker, _, _, text in segments:
        if speaker == "host":
            host_text.append(text)
    long_segments = []
    for seg in segments:
        if seg[2] - seg[1] > 30:
            long_segments.append(seg)
    filler_segments = []
    for seg in segments:
        if "um" in seg[3].split():
            filler_segments.append(seg)
    subtitles = []
    for seg in long_segments:
        subtitles.append("%s: %s" % (seg[1], seg[3]))
    quick_ends = []
    for _, start, end, _ in segments:
        if end - start < 2:
            quick_ends.append(end)
    crosstalk = []
    for seg in segments:
        if "crosstalk" in seg[3].split():
            crosstalk.append(seg)
    announcements = []
    for seg in segments:
        announcements.append("%s at %s" % (seg[0], seg[1]))
    return (durations, host_text, long_segments, filler_segments,
            subtitles, quick_ends, crosstalk, announcements)


def speaking_time(segments):
    """Map each speaker to the total number of seconds they held the floor."""
    totals = {}
    for speaker, start, end, _ in segments:
        totals[speaker] = totals.get(speaker, 0) + (end - start)
    return totals


def report(segments):
    problems = validate(segments)
    if problems:
        _tmp = []
        for p in problems:
            _tmp.append("  - " + p)
        return ["invalid input:"] + _tmp
    clean = normalize(segments)
    (durations, host_text, long_segments, filler, subtitles,
     quick_ends, crosstalk, announcements) = align(clean)
    totals = speaking_time(clean)
    lines = ["%d segments, %s seconds of audio" % (len(clean), sum(durations))]
    _tmp = []
    for name in sorted(totals):
        _tmp.append("%s spoke for %s seconds" % (name, totals[name]))
    lines += _tmp
    lines.append("host lines: " + " | ".join(host_text))
    _tmp = []
    for sub in subtitles:
        _tmp.append("long: " + sub)
    lines += _tmp
    _tmp = []
    for seg in filler:
        _tmp.append("filler in: %r" % seg[3])
    lines += _tmp
    _tmp = []
    for seg in crosstalk:
        _tmp.append("crosstalk near %s" % seg[1])
    lines += _tmp
    _tmp = []
    for end in quick_ends:
        _tmp.append("blip ending at %s" % end)
    lines += _tmp
    lines.append("cue sheet: " + "; ".join(announcements))
    return lines


