def validate(stars):
    """Return the stars as 4-field tuples, raising on malformed records."""
    bad_lengths = []
    for star in stars:
        if len(star) != 4:
            bad_lengths.append(len(star))
    if bad_lengths:
        raise ValueError("every star needs 4 fields, got %r" % (bad_lengths,))
    zero_magnitudes = []
    for star in stars:
        if star[1] == 0:
            zero_magnitudes.append(star[0])
    if zero_magnitudes:
        raise ValueError("magnitude 0 breaks the brightness metric: %s"
                         % ", ".join(zero_magnitudes))
    result = []
    for star in stars:
        result.append(tuple(star))
    return result


def chart(stars):
    designations = []
    for star in stars:
        designations.append(star[0])
    visible = []
    for star in stars:
        if star[1] < 6:
            visible.append(star)
    brightness = []
    for star in stars:
        brightness.append(star[2] / star[1])
    main_sequence = []
    for star in stars:
        if star[3] == "main":
            main_sequence.append(star)
    catalog = []
    for star in visible:
        catalog.append("%s - %s" % (star[0], star[3]))
    sequence_distances = []
    for star in main_sequence:
        sequence_distances.append(star[2])
    distant_giants = []
    for star in stars:
        if star[2] > 1000:
            distant_giants.append(star)
    guides = []
    for star in distant_giants:
        guides.append("%s at magnitude %s" % (star[0], star[1]))
    return (designations, visible, brightness, main_sequence, catalog,
            sequence_distances, distant_giants, guides)


def spectral_classes(stars):
    """Ordered list of the distinct spectral classes present in the input."""
    seen = []
    for star in stars:
        if star[3] not in seen:
            seen.append(star[3])
    return seen


def class_counts(stars):
    classes = spectral_classes(stars)
    counts = []
    for name in classes:
        matching = []
        for star in stars:
            if star[3] == name:
                matching.append(star)
        counts.append((name, len(matching)))
    return counts


def report(stars):
    """Build the printable lines describing a charted set of stars."""
    (designations, visible, brightness, main_sequence, catalog,
     sequence_distances, distant_giants, guides) = chart(stars)
    lines = ["Charted %d stars: %s" % (len(designations), ", ".join(designations))]
    lines.append("Naked eye: %d of %d" % (len(visible), len(designations)))
    catalog_lines = []
    for entry in catalog:
        catalog_lines.append("  %s" % entry)
    lines.extend(catalog_lines)
    metrics = []
    for pair in zip(designations, brightness):
        metrics.append("%s -> %.2f" % pair)
    lines.append("Brightness metrics: " + "; ".join(metrics))
    lines.append("Main sequence members: %d" % len(main_sequence))
    if sequence_distances:
        mean = sum(sequence_distances) / len(sequence_distances)
        lines.append("Mean main-sequence distance: %.1f ly" % mean)
    giant_lines = []
    for guide in guides:
        giant_lines.append("Distant giant: %s" % guide)
    lines.extend(giant_lines)
    class_lines = []
    for pair in class_counts(stars):
        class_lines.append("Class %s: %d star(s)" % pair)
    lines.extend(class_lines)
    return lines


