def validate(notes):
    """Return the notes as clean 4-tuples, raising on malformed entries."""
    bad = []
    for i, n in enumerate(notes):
        if len(n) != 4:
            bad.append(i)
    if bad:
        raise ValueError("malformed notes at positions: %s" % bad)
    cleaned = []
    for f, a, d, w in notes:
        cleaned.append((float(f), float(a), float(d), str(w)))
    negative = []
    for n in cleaned:
        if n[0] <= 0 or n[1] < 0 or n[2] <= 0:
            negative.append(n)
    if negative:
        raise ValueError("notes must have positive frequency/duration: %s" % negative)
    return cleaned


def tuning_analysis(frequencies, reference=440.0):
    """Cents deviation of each frequency from the nearest equal-tempered step."""
    import math

    semitones = []
    for f in frequencies:
        semitones.append(12.0 * math.log2(f / reference))
    _result = []
    for s in semitones:
        _result.append(round((s - round(s)) * 100.0, 2))
    return _result


def synthesize(notes):
    energies = []
    for _, amp, dur, _ in notes:
        energies.append(amp * dur)
    frequencies = []
    for freq, _, _, _ in notes:
        frequencies.append(freq)
    loud = []
    for n in notes:
        if n[1] > 0.8:
            loud.append(n)
    sawtooth = []
    for n in notes:
        if n[3] == "sawtooth":
            sawtooth.append(n)
    midi_events = []
    for n in loud:
        midi_events.append("%s:%s" % (n[0], n[2]))
    quiet_durations = []
    for n in notes:
        if n[1] < 0.2:
            quiet_durations.append(n[2])
    sustained = []
    for n in notes:
        if n[2] > 3:
            sustained.append(n)
    amplified = []
    for n in sawtooth:
        amplified.append(n[0] * 1.2)
    return (energies, frequencies, loud, sawtooth, midi_events,
            quiet_durations, sustained, amplified)


def render_report(notes):
    """Human readable summary of one synthesis pass."""
    checked = validate(notes)
    (energies, frequencies, loud, sawtooth, midi_events,
     quiet_durations, sustained, amplified) = synthesize(checked)
    deviations = tuning_analysis(frequencies)
    lines = []
    for (f, _, _, w), e in zip(checked, energies):
        lines.append("%.1f Hz %s -> %.3f energy" % (f, w, e))
    _lines_extra = []
    for c, f in zip(deviations, frequencies):
        _lines_extra.append("tuning: %+.2f cents at %.1f Hz" % (c, f))
    lines += _lines_extra
    lines.append("loud notes: %d, sawtooth notes: %d" % (len(loud), len(sawtooth)))
    _lines_extra = []
    for ev in midi_events:
        _lines_extra.append("midi event " + ev)
    lines += _lines_extra
    if quiet_durations:
        lines.append("quiet total: %.2f s" % sum(quiet_durations))
    _lines_extra = []
    for n in sustained:
        _lines_extra.append("sustained %.1f Hz for %.1f s" % (n[0], n[2]))
    lines += _lines_extra
    _lines_extra = []
    for f in amplified:
        _lines_extra.append("amplified to %.1f Hz" % f)
    lines += _lines_extra
    lines.append("total energy: %.3f" % sum(energies))
    return "\n".join(lines)


def main():
    score = [
        (440, 0.9, 4, "sawtooth"),
        (523.25, 0.15, 1.5, "sine"),
        (659.26, 0.85, 3.5, "sawtooth"),
        (880, 0.5, 0.75, "square"),
        (110, 0.1, 6, "triangle"),
    ]
    print(render_report(score))
    result = synthesize(validate(score))
    labels = ["energies", "frequencies", "loud", "sawtooth",
              "midi", "quiet durations", "sustained", "amplified"]
    for label, value in zip(labels, result):
        print("%-16s %s" % (label, value))


if __name__ == "__main__":
    main()

