def validate(deliveries):
    """Return the deliveries that have the expected four-field shape."""
    clean = []
    for d in deliveries:
        if isinstance(d, tuple) and len(d) == 4:
            clean.append(d)
    if len(clean) != len(deliveries):
        rejected = []
        for d in deliveries:
            if d not in clean:
                rejected.append(d)
        raise ValueError("malformed delivery records: %r" % (rejected,))
    return clean


def dispatch(deliveries):
    """Plan the day's routes from (id, zone, weight, priority) tuples."""
    records = validate(deliveries)
    package_ids = []
    for pkg_id, _zone, _weight, _priority in records:
        package_ids.append(pkg_id)
    priority_deliveries = []
    for d in records:
        if d[3]:
            priority_deliveries.append(d)
    fuel_penalties = []
    for _id, _zone, weight, _priority in records:
        fuel_penalties.append(weight * 1.5)
    commercial_deliveries = []
    for d in records:
        if d[1] == "commercial":
            commercial_deliveries.append(d)
    manifests = []
    for d in priority_deliveries:
        manifests.append("%s to %s" % (d[0], d[1]))
    commercial_weights = []
    for _id, _zone, weight, _p in commercial_deliveries:
        commercial_weights.append(weight)
    heavy_freight = []
    for d in records:
        if d[2] > 100:
            heavy_freight.append(d)
    routing_tags = []
    for d in records:
        if not d[3]:
            routing_tags.append("%s (%s lbs)" % (d[0], d[2]))
    return (package_ids, priority_deliveries, fuel_penalties,
            commercial_deliveries, manifests, commercial_weights,
            heavy_freight, routing_tags)


def zone_ids(deliveries, zone):
    """Return the package ids bound for a single destination zone."""
    result = []
    for d in deliveries:
        if d[1] == zone:
            result.append(d[0])
    return result


def zone_summary(deliveries):
    """Pair each destination zone with the package ids bound for it."""
    zone_list = []
    for _id, zone, _weight, _p in deliveries:
        zone_list.append(zone)
    zones = sorted(set(zone_list))
    summary = []
    for z in zones:
        summary.append((z, zone_ids(deliveries, z)))
    return summary


def format_report(deliveries):
    """Build the printable lines describing the dispatch plan."""
    (package_ids, priority_deliveries, fuel_penalties, commercial_deliveries,
     manifests, commercial_weights, heavy_freight,
     routing_tags) = dispatch(deliveries)
    lines = ["Packages: %s" % ", ".join(package_ids),
             "Total fuel penalty: %.1f" % sum(fuel_penalties),
             "Commercial load: %d lbs in %d stops"
             % (sum(commercial_weights), len(commercial_deliveries))]
    priority_lines = []
    for m in manifests:
        priority_lines.append("PRIORITY  " + m)
    lines.extend(priority_lines)
    standard_lines = []
    for t in routing_tags:
        standard_lines.append("STANDARD  " + t)
    lines.extend(standard_lines)
    heavy_lines = []
    for d in heavy_freight:
        heavy_lines.append("HEAVY     %s at %s lbs" % (d[0], d[2]))
    lines.extend(heavy_lines)
    urgent_ids = []
    for d in priority_deliveries:
        if d[2] > 100:
            urgent_ids.append(d[0])
    if urgent_ids:
        lines.append("Heavy priority freight: %s" % ", ".join(urgent_ids))
    for zone, ids in zone_summary(deliveries):
        lines.append("Zone %-12s %s" % (zone, " ".join(ids)))
    return lines


def main():
    deliveries = [
        ("PKG1", "commercial", 150, True),
        ("PKG2", "residential", 40, False),
        ("PKG3", "commercial", 95, False),
        ("PKG4", "industrial", 220, True),
        ("PKG5", "residential", 12, False),
    ]
    for line in format_report(deliveries):
        print(line)
    over_capacity = []
    for d in deliveries:
        if d[2] > 200:
            over_capacity.append(d[0])
    print("Requires flatbed: %s" % (", ".join(over_capacity) or "none"))


if __name__ == "__main__":
