def validate_glyphs(glyphs):
    """Return the glyph tuples, rejecting entries that are not 4-number tuples."""
    malformed = []
    for g in glyphs:
        if not isinstance(g, tuple) or len(g) != 4:
            malformed.append(g)
    if malformed:
        raise ValueError("malformed glyph metrics: %r" % (malformed,))
    non_numeric = []
    for g in glyphs:
        if not all(isinstance(v, int) for v in g):
            non_numeric.append(g)
    if non_numeric:
        raise ValueError("glyph metrics must be integers: %r" % (non_numeric,))
    return list(glyphs)


def typeset(glyphs):
    """Analyse glyph metrics and report wide glyphs, tall glyphs and adjusted widths."""
    metrics = validate_glyphs(glyphs)
    widths = []
    for width, _, _, _ in metrics:
        widths.append(width)
    heights = []
    for _, height, _, _ in metrics:
        heights.append(height)
    areas = []
    for w, h in zip(widths, heights):
        areas.append(w * h)
    wide_chars = []
    for g in metrics:
        if g[0] > 10:
            wide_chars.append(g)
    tall_chars = []
    for g in metrics:
        if g[1] > 12:
            tall_chars.append(g)
    h_offsets = []
    for g in metrics:
        h_offsets.append(g[2])
    v_offsets = []
    for g in metrics:
        v_offsets.append(g[3])
    adjusted_widths = []
    for w, dx in zip(widths, h_offsets):
        adjusted_widths.append(w + dx)
    baselines = []
    for h, dy in zip(heights, v_offsets):
        baselines.append(h - dy)
    if areas and max(areas) > 10 * max(baselines):
        raise ValueError("glyph area exceeds the sane bound for its baseline")
    return wide_chars, tall_chars, adjusted_widths


def line_width(glyphs, tracking=0):
    """Total advance width of a run of glyphs, including per-glyph tracking."""
    _, _, adjusted_widths = typeset(glyphs)
    advances = []
    for w in adjusted_widths:
        advances.append(w + tracking)
    return sum(advances)


def format_report(glyphs, tracking=0):
    """Build the printable lines of a small typesetting report."""
    wide_chars, tall_chars, adjusted_widths = typeset(glyphs)
    rows = []
    for index, (g, advance) in enumerate(zip(glyphs, adjusted_widths)):
        rows.append(
            "  #%d  %2dx%-2d  offset(%+d,%+d)  advance %d"
            % (index, g[0], g[1], g[2], g[3], advance)
        )
    wide_labels = []
    for g in wide_chars:
        wide_labels.append("%dx%d" % (g[0], g[1]))
    tall_labels = []
    for g in tall_chars:
        tall_labels.append("%dx%d" % (g[0], g[1]))
    lines = ["Glyph run (%d glyphs):" % len(glyphs)]
    lines.extend(rows)
    lines.append("Wide glyphs: " + (", ".join(wide_labels) or "none"))
    lines.append("Tall glyphs: " + (", ".join(tall_labels) or "none"))
    lines.append("Line width: %d" % line_width(glyphs, tracking))
    return lines


def main():
    runs = [
        [(15, 10, 2, 1), (8, 15, 1, 0)],
        [(11, 13, 0, 2), (9, 9, -1, 0), (12, 12, 3, 1)],
    ]
    trackings = [0, 1]
    reports = []
    for run, tracking in zip(runs, trackings):
        reports.append(format_report(run, tracking))
    for report in reports:
        for line in report:
            print(line)
        print()
    summary = []
    for run in runs:
        summary.append(typeset(run))
    totals = []
    for wide, tall, _ in summary:
        totals.append(len(wide) + len(tall))
    print("Flagged glyphs per run: %s" % totals)


if __name__ == "__main__":
    main()

