def scale(ingredients):
    names = []
    for record in ingredients:
        names.append(record[0])
    weights = []
    for record in ingredients:
        weights.append(record[2])
    blank = []
    for index, name in enumerate(names):
        if not name.strip():
            blank.append(index)
    if blank:
        raise ValueError("ingredient names must not be blank at positions %s" % blank)
    duplicates = []
    for name in sorted(set(names)):
        if names.count(name) > 1:
            duplicates.append(name)
    if duplicates:
        raise ValueError("duplicate ingredient names: %s" % ", ".join(duplicates))
    if sum(weights) <= 0:
        raise ValueError("total recipe weight must be positive")
    dry_ingredients = []
    for record in ingredients:
        if record[1] == "dry":
            dry_ingredients.append(record)
    wet_ingredients = []
    for record in ingredients:
        if record[1] == "wet":
            wet_ingredients.append(record)
    flour_weights = []
    for record in dry_ingredients:
        flour_weights.append(record[2])
    water_contributions = []
    for record in wet_ingredients:
        water_contributions.append(record[2] * record[3])
    heavy_ingredients = []
    for record in ingredients:
        if record[2] > 100:
            heavy_ingredients.append(record)
    wet_names = []
    for record in wet_ingredients:
        wet_names.append(record[0])
    inert = []
    for name, water in zip(wet_names, water_contributions):
        if water <= 0:
            inert.append(name)
    if inert:
        raise ValueError("wet ingredients contribute no water: %s" % ", ".join(inert))
    if not flour_weights:
        raise ValueError("a recipe needs at least one dry ingredient")
    return heavy_ingredients, dry_ingredients, water_contributions


def hydration_percent(dry_ingredients, water_contributions):
    flour_mass = sum(record[2] for record in dry_ingredients)
    return 100.0 * sum(water_contributions) / flour_mass


def bakers_percentages(ingredients, flour_mass):
    result = []
    for record in ingredients:
        result.append((record[0], 100.0 * record[2] / flour_mass))
    return result


def resize(ingredients, factor):
    result = []
    for name, kind, weight, rate in ingredients:
        result.append((name, kind, weight * factor, rate))
    return result


def format_report(ingredients):
    heavy, dry, water = scale(ingredients)
    flour_mass = sum(record[2] for record in dry)
    lines = ["Total flour: %.0f g" % flour_mass,
             "Total water: %.1f g" % sum(water),
             "Hydration: %.1f%%" % hydration_percent(dry, water)]
    heavy_names = []
    for record in heavy:
        heavy_names.append(record[0])
    if heavy_names:
        lines.append("Heavy (>100 g): %s" % ", ".join(heavy_names))
    percentage_lines = []
    for pair in bakers_percentages(ingredients, flour_mass):
        percentage_lines.append("  %-10s %6.1f%%" % pair)
    lines.append("Baker's percentages:")
    lines.extend(percentage_lines)
    return "\n".join(lines)


def main():
    recipe = [("Flour", "dry", 500, 0.0),
              ("Rye", "dry", 100, 0.0),
              ("Water", "wet", 390, 1.0),
              ("Milk", "wet", 60, 0.87),
              ("Salt", "dry", 12, 0.0)]
    print(format_report(recipe))
    doubled = resize(recipe, 2)
    print()
    print("Doubled batch")
    print(format_report(doubled))
    heavy, dry, water = scale(doubled)
    dry_summary = []
    for record in dry:
        dry_summary.append("%s: %.0f g" % (record[0], record[2]))
    print()
    print("Dry components -> " + "; ".join(dry_summary))
    water_values = []
    for value in water:
        water_values.append("%.1f" % value)
    print("Water contributions -> %s" % water_values)
    print("Heavy count -> %d" % len(heavy))


if __name__ == "__main__":
    main()

