MULTIPLIER_CODES = {"M": 0, "S": 1, "D": 2, "T": 3}
CODE_BY_MULTIPLIER = {value: code for code, value in MULTIPLIER_CODES.items()}


def parse_throws(notation):
    """Turn a string like 'T20 D15 S5 M' into a list of (multiplier, segment)."""
    tokens = [token.upper() for token in notation.split()]
    unknown = [token for token in tokens if token[0] not in MULTIPLIER_CODES]
    if unknown:
        raise ValueError("unknown throw codes: " + ", ".join(unknown))
    malformed = [token for token in tokens if token[1:] and not token[1:].isdigit()]
    if malformed:
        raise ValueError("malformed throw codes: " + ", ".join(malformed))
    return [(MULTIPLIER_CODES[token[0]], int(token[1:] or 0)) for token in tokens]


def describe(throw):
    """Render a single throw back into dart notation."""
    multiplier, segment = throw
    if multiplier == 0:
        return "M"
    return f"{CODE_BY_MULTIPLIER[multiplier]}{segment}"


def score(throws):
    segments = [segment for _multiplier, segment in throws]
    multipliers = [multiplier for multiplier, _segment in throws]
    totals = [multiplier * segment for multiplier, segment in zip(multipliers, segments)]
    singles = [throw for throw in throws if throw[0] == 1]
    doubles = [throw for throw in throws if throw[0] == 2]
    trebles = [throw for throw in throws if throw[0] == 3]
    bullseyes = [throw for throw in throws if throw[1] == 25]
    misses = [throw for throw in throws if throw[0] == 0]
    if len(singles) + len(doubles) + len(trebles) + len(misses) != len(throws):
        raise ValueError("multipliers must be 0, 1, 2 or 3")
    illegal_bulls = [throw for throw in bullseyes if throw[0] == 3]
    if illegal_bulls:
        raise ValueError("the bullseye cannot be trebled: " + ", ".join(describe(t) for t in illegal_bulls))
    return totals, doubles, trebles


def checkout_candidates(remaining):
    """Doubles (including the bull) that would finish the leg exactly."""
    finishers = [(2, segment) for segment in list(range(1, 21)) + [25]]
    return [throw for throw in finishers if throw[0] * throw[1] == remaining]


def format_report(notation, start=501):
    throws = parse_throws(notation)
    totals, doubles, trebles = score(throws)
    lines = [f"  {describe(throw):>4} = {total:>2}" for throw, total in zip(throws, totals)]
    remaining = start - sum(totals)
    lines.append(f"  scored {sum(totals)}, {remaining} left")
    if doubles:
        lines.append("  doubles: " + " ".join(describe(throw) for throw in doubles))
    if trebles:
        lines.append("  trebles: " + " ".join(describe(throw) for throw in trebles))
    checkouts = [describe(throw) for throw in checkout_candidates(remaining)]
    if checkouts:
        lines.append("  checkout on: " + " ".join(checkouts))
    return "\n".join(lines)


def main():
    visits = ["T20 T20 T20", "S5 D25 M", "D20 S1 T19", "T19 D12 S20"]
    reports = [format_report(visit) for visit in visits]
    for visit, report in zip(visits, reports):
        print(f"{visit}:")
        print(report)
    print(score([(2, 15), (3, 20)]))


if __name__ == "__main__":
    main()

