def validate_holds(holds):
    """Return the holds as 4-tuples of numbers, raising on malformed entries."""
    bad_lengths = []
    for h in holds:
        if len(h) != 4:
            bad_lengths.append(h)
    if bad_lengths:
        raise ValueError("each hold needs 4 fields, got: %r" % (bad_lengths[0],))
    non_numeric = []
    for h in holds:
        if any(not isinstance(v, (int, float)) for v in h):
            non_numeric.append(h)
    if non_numeric:
        raise ValueError("non-numeric hold: %r" % (non_numeric[0],))
    result = []
    for h in holds:
        result.append(tuple(h))
    return result


def evaluate(holds):
    """Analyse a wall and return (challenging holds, high holds, difficulty scores)."""
    horizontals = []
    for h in holds:
        horizontals.append(h[0])
    verticals = []
    for h in holds:
        verticals.append(h[1])
    challenging = []
    for h in holds:
        if h[2] < 3:
            challenging.append(h)
    slippery = []
    for h in holds:
        if h[3] < 0.5:
            slippery.append(h)
    high = []
    for h in holds:
        if h[1] > 10:
            high.append(h)
    wide = []
    for h in holds:
        if h[0] > 5:
            wide.append(h)
    difficulty = []
    for h in holds:
        if h[2] > 0:
            difficulty.append(h[1] / h[2])
    high_grips = []
    for h in high:
        high_grips.append(h[2])
    print("span: x %s..%s, y %s..%s" % (min(horizontals), max(horizontals),
                                        min(verticals), max(verticals)))
    print("slippery: %d, wide: %d, high grip sizes: %s" % (len(slippery), len(wide), high_grips))
    return challenging, high, difficulty


def format_hold(hold):
    x, y, grip, friction = hold
    return "x=%-4s y=%-4s grip=%-3s friction=%.2f" % (x, y, grip, friction)


def hardest_holds(holds, limit=3):
    """The holds with the highest vertical/grip ratio, hardest first."""
    scorable = []
    for h in holds:
        if h[2] > 0:
            scorable.append(h)
    ranked = sorted(scorable, key=lambda h: h[1] / h[2], reverse=True)
    return ranked[:limit]


def build_report(holds):
    challenging, high, difficulty = evaluate(holds)
    lines = ["Wall report (%d holds)" % len(holds)]
    lines.append("challenging holds (grip < 3):")
    challenging_lines = []
    for h in challenging:
        challenging_lines.append(" - " + format_hold(h))
    lines.extend(challenging_lines)
    lines.append("high holds (y > 10):")
    high_lines = []
    for h in high:
        high_lines.append(" - " + format_hold(h))
    lines.extend(high_lines)
    rounded = []
    for score in difficulty:
        rounded.append(round(score, 2))
    lines.append("difficulty scores: %s" % rounded)
    if difficulty:
        lines.append("mean difficulty: %.2f" % (sum(difficulty) / len(difficulty)))
    lines.append("hardest moves:")
    hardest_lines = []
    for h in hardest_holds(holds):
        hardest_lines.append(" - " + format_hold(h))
    lines.extend(hardest_lines)
    return "\n".join(lines)


def main():
    raw_routes = [
        ("example", [(10, 15, 2, 0.8), (2, 5, 5, 0.4)]),
        ("overhang", [(1, 3, 4, 0.9), (7, 12, 2, 0.35), (6, 18, 1, 0.55),
                      (3, 9, 0, 0.7), (9, 11, 3, 0.45)]),
    ]
    routes = []
    for name, holds in raw_routes:
        routes.append((name, validate_holds(holds)))
    for name, holds in routes:
        print("=== %s ===" % name)
        print(build_report(holds))


