"""Kerning analysis: spot letter pairs whose default spacing or collision risk
needs manual attention."""

SPACING_TIGHT = 0
SPACING_LOOSE = 10
RISK_HIGH = 80
RISK_SAFE = 20

DIAGNOSTICS = {}


def validate(pairs):
    """Normalise the raw pairings, rejecting anything malformed."""
    wrong_size = []
    for p in pairs:
        if len(p) != 4:
            wrong_size.append(p)
    if wrong_size:
        raise ValueError("each pairing needs 4 fields: %r" % (wrong_size,))
    non_numeric = []
    for p in pairs:
        if not isinstance(p[2], int) or not isinstance(p[3], int):
            non_numeric.append(p)
    if non_numeric:
        raise ValueError("spacing and risk must be integers: %r" % (non_numeric,))
    _temp = []
    for a, b, space, risk in pairs:
        _temp.append((str(a), str(b), int(space), int(risk)))
    return _temp


def kern(pairs):
    """Return the tight pairs, the high risk pairs and the adjusted spacings."""
    first_letters = []
    for p in pairs:
        first_letters.append(p[0])
    second_letters = []
    for p in pairs:
        second_letters.append(p[1])
    tight_pairs = []
    for p in pairs:
        if p[2] < SPACING_TIGHT:
            tight_pairs.append(p)
    loose_pairs = []
    for p in pairs:
        if p[2] > SPACING_LOOSE:
            loose_pairs.append(p)
    high_risk_pairs = []
    for p in pairs:
        if p[3] > RISK_HIGH:
            high_risk_pairs.append(p)
    safe_pairs = []
    for p in pairs:
        if p[3] < RISK_SAFE:
            safe_pairs.append(p)
    adjusted_spacings = []
    for p in pairs:
        adjusted_spacings.append(p[2] + p[3])
    risky_seconds = []
    for p in high_risk_pairs:
        risky_seconds.append(p[1])
    DIAGNOSTICS.update(
        first_letters=first_letters,
        second_letters=second_letters,
        loose_pairs=loose_pairs,
        safe_pairs=safe_pairs,
        risky_seconds=risky_seconds,
    )
    return tight_pairs, high_risk_pairs, adjusted_spacings


def format_pairs(pairs):
    """Render pairings as the bare two-letter combinations."""
    _temp = []
    for a, b, _space, _risk in pairs:
        _temp.append(a + b)
    return ", ".join(_temp) or "(none)"


def spacing_table(pairs, adjusted_spacings):
    """One report line per pairing, showing the default and adjusted spacing."""
    _temp = []
    for (a, b, space, risk), new_space in zip(pairs, adjusted_spacings):
        _temp.append("%s%s  risk %3d  %+d -> %+d" % (a, b, risk, space, new_space))
    return _temp


def alphabet_in_play(first_letters, second_letters):
    """Every distinct glyph mentioned by the pairings, in sorted order."""
    return sorted({letter for letter in first_letters + second_letters})


def main():
    raw = [('A', 'V', -2, 50), ('L', 'O', 15, 90), ('T', 'a', -3, 85), ('n', 'n', 4, 10)]
    pairs = validate(raw)
    tight_pairs, high_risk_pairs, adjusted_spacings = kern(pairs)

    print("tight pairs:    ", format_pairs(tight_pairs))
    print("loose pairs:    ", format_pairs(DIAGNOSTICS["loose_pairs"]))
    print("high risk pairs:", format_pairs(high_risk_pairs))
    print("safe pairs:     ", format_pairs(DIAGNOSTICS["safe_pairs"]))
    print("glyphs:         ", " ".join(alphabet_in_play(DIAGNOSTICS["first_letters"],
                                                        DIAGNOSTICS["second_letters"])))
    print("risky seconds:  ", " ".join(DIAGNOSTICS["risky_seconds"]) or "(none)")
    for line in spacing_table(pairs, adjusted_spacings):
        print("  " + line)

    overshoot = []
    for value in adjusted_spacings:
        if value > SPACING_LOOSE:
            overshoot.append(value - SPACING_LOOSE)
    if overshoot:
        print("total overshoot beyond %d: %d" % (SPACING_LOOSE, sum(overshoot)))


