    ]
    return shape_errors + field_errors + penalty_errors


def rank(boats):
    names = [boat[0] for boat in boats]
    finish_times = [boat[1] for boat in boats]
    corrected_times = [
        finish - handicap + penalty for _, finish, handicap, penalty in boats
    ]
    penalized_boats = [boat for boat in boats if boat[3] > 0]
    clean_boats = [boat for boat in boats if boat[3] == 0]
    fast_boats = [boat for boat in boats if boat[1] < 60]
    slow_boats = [boat for boat in boats if boat[1] > 90]
    fast_handicaps = [boat[2] for boat in fast_boats]
    print("fleet: %s" % ", ".join(names))
    print("finish times: %s" % finish_times)
    print("clean boats: %d, slow boats: %d" % (len(clean_boats), len(slow_boats)))
    print("handicaps of the fast boats: %s" % fast_handicaps)
