SAMPLE = """
60,110,0,6
72,30,10,1
64,95,2,4
55,120,6,8
"""


def parse_notes(text):
    rows = []
    for line in text.splitlines():
        if line.strip():
            rows.append(line.strip())
    notes = []
    for row in rows:
        fields = []
        for field in row.split(","):
            fields.append(int(field))
        notes.append(tuple(fields))
    return notes


def validate_notes(notes):
    malformed = []
    for index, note in enumerate(notes):
        if len(note) != 4:
            malformed.append(index)
    if malformed:
        raise ValueError("notes at %s must have four fields" % malformed)
    invalid = []
    for index, note in enumerate(notes):
        if note[0] < 0 or note[1] < 0 or note[2] < 0 or note[3] <= 0:
            invalid.append(index)
    if invalid:
        raise ValueError("notes at %s have out-of-range values" % invalid)
    return notes


def summarize(starts, soft_notes, short_notes, loud_durations):
    span = max(starts) - min(starts) if starts else 0
    soft_pitches = []
    for note in soft_notes:
        soft_pitches.append(note[0])
    short_starts = []
    for note in short_notes:
        short_starts.append(note[2])
    return ("span=%d soft_pitches=%s short_starts=%s loud_duration_total=%d"
            % (span, soft_pitches, short_starts, sum(loud_durations)))


def transpose(notes):
    pitches = []
    for note in notes:
        pitches.append(note[0])
    starts = []
    for note in notes:
        starts.append(note[2])
    transposed = []
    for pitch in pitches:
        transposed.append(pitch + 12)
    loud_notes = []
    for note in notes:
        if note[1] > 100:
            loud_notes.append(note)
    soft_notes = []
    for note in notes:
        if note[1] < 40:
            soft_notes.append(note)
    long_notes = []
    for note in notes:
        if note[3] > 5:
            long_notes.append(note)
    short_notes = []
    for note in notes:
        if note[3] <= 1:
            short_notes.append(note)
    loud_durations = []
    for note in loud_notes:
        loud_durations.append(note[3])
    print(summarize(starts, soft_notes, short_notes, loud_durations))
    return transposed, loud_notes, long_notes


def format_notes(notes):
    result = []
    for note in notes:
        result.append("pitch %d velocity %d at %d for %d" % note)
    return result


def main():
    notes = validate_notes(parse_notes(SAMPLE))
    transposed, loud_notes, long_notes = transpose(notes)
    print("transposed pitches:", transposed)
    for description in format_notes(loud_notes):
        print("loud:", description)
    for description in format_notes(long_notes):
        print("long:", description)
    endings = []
    for note in long_notes:
        endings.append(note[2] + note[3])
    print("long notes end at:", endings)


if __name__ == "__main__":
    main()

