def validate_batches(batches):
    malformed = []
    for batch in batches:
        if len(batch) != 4:
            malformed.append(batch)
    if malformed:
        raise ValueError(f"each batch needs 4 fields, got {malformed}")
    bad_weights = []
    for batch in batches:
        if batch[1] <= 0:
            bad_weights.append(batch[0])
    if bad_weights:
        raise ValueError(f"raw material weight must be positive: {bad_weights}")


def yield_ratios(batches):
    result = []
    for _, weight, oil, _ in batches:
        result.append(oil / weight)
    return result


def categorize_by_yield(batches, ratios):
    high = []
    for batch, ratio in zip(batches, ratios):
        if ratio * 100 > HIGH_YIELD_CUTOFF:
            high.append(batch)
    low = []
    for batch, ratio in zip(batches, ratios):
        if ratio * 100 < LOW_YIELD_CUTOFF:
            low.append(batch)
    return high, low


def categorize_by_speed(batches):
    fast = []
    for batch in batches:
        if batch[3] < FAST_HOURS:
            fast.append(batch)
    slow = []
    for batch in batches:
        if batch[3] > SLOW_HOURS:
            slow.append(batch)
    return fast, slow


def oil_volumes(selected):
    result = []
    for batch in selected:
        result.append(batch[2])
    return result


def format_summary(names, weights, low_yield, slow, fast_oils):
    lines = []
    for name, weight in zip(names, weights):
        lines.append(f"{name}: {weight:g} kg raw material")
    low_yield_lines = []
    for batch in low_yield:
        low_yield_lines.append(f"low yield below {LOW_YIELD_CUTOFF:g}%: {batch[0]}")
    lines += low_yield_lines
    slow_lines = []
    for batch in slow:
        slow_lines.append(f"slow run: {batch[0]} took {batch[3]:g} h")
    lines += slow_lines
    lines.append(f"oil from fast batches: {sum(fast_oils):g} L")
    return lines


def distill(batches):
    validate_batches(batches)
    names = []
    for batch in batches:
        names.append(batch[0])
    weights = []
    for batch in batches:
        weights.append(batch[1])
    ratios = yield_ratios(batches)
    high_yield, low_yield = categorize_by_yield(batches, ratios)
    fast, slow = categorize_by_speed(batches)
    fast_oils = oil_volumes(fast)
    for line in format_summary(names, weights, low_yield, slow, fast_oils):
        print(line)
    return ratios, high_yield, fast


