def validate_segments(segments):
    wrong_size = []
    for index, segment in enumerate(segments):
        if len(segment) != 4:
            wrong_size.append(index)
    if wrong_size:
        raise ValueError("segments with wrong arity: %s" % wrong_size)
    negative = []
    for index, seg in enumerate(segments):
        if seg[0] < 0 or seg[1] < 0:
            negative.append(index)
    if negative:
        raise ValueError("segments with negative depth or time: %s" % negative)
    gas_totals = []
    for _, _, oxygen, nitrogen in segments:
        gas_totals.append(oxygen + nitrogen)
    unbalanced = []
    for index, total in enumerate(gas_totals):
        if abs(total - 1.0) > 1e-6:
            unbalanced.append(index)
    if unbalanced:
        raise ValueError("segments whose gas mix does not sum to 1.0: %s" % unbalanced)


def partial_pressures(depths, oxygen_fractions):
    result = []
    for depth, fraction in zip(depths, oxygen_fractions):
        result.append(depth * fraction)
    return result


def risk_notes(shallow_segments, short_segments, deep_nitrogen):
    notes = []
    for depth, _, _, _ in shallow_segments:
        notes.append("shallow stop at %dm leaves little buffer" % depth)
    short_notes = []
    for _, time, _, _ in short_segments:
        short_notes.append("bottom time of %d min is barely a dive" % time)
    notes += short_notes
    narcosis_notes = []
    for fraction in deep_nitrogen:
        if fraction > 0.65:
            narcosis_notes.append("deep segment breathing %.0f%% nitrogen risks narcosis" % (fraction * 100))
    notes += narcosis_notes
    return notes


def format_profile(depths, times, pressures):
    rows = []
    for depth, time, pressure in zip(depths, times, pressures):
        rows.append("%6d %8d %10.2f" % (depth, time, pressure))
    return ["%6s %8s %10s" % ("depth", "time", "ppO2")] + rows


def plan(segments):
    validate_segments(segments)
    depths = []
    for depth, _, _, _ in segments:
        depths.append(depth)
    bottom_times = []
    for _, time, _, _ in segments:
        bottom_times.append(time)
    oxygen_fractions = []
    for _, _, oxygen, _ in segments:
        oxygen_fractions.append(oxygen)
    oxygen_partial_pressures = partial_pressures(depths, oxygen_fractions)
    deep_segments = []
    for segment in segments:
        if segment[0] > 30:
            deep_segments.append(segment)
    shallow_segments = []
    for segment in segments:
        if segment[0] < 10:
            shallow_segments.append(segment)
    long_segments = []
    for segment in segments:
        if segment[1] > 40:
            long_segments.append(segment)
    short_segments = []
    for segment in segments:
        if segment[1] <= 5:
            short_segments.append(segment)
    deep_nitrogen = []
    for _, _, _, nitrogen in deep_segments:
        deep_nitrogen.append(nitrogen)
    for line in format_profile(depths, bottom_times, oxygen_partial_pressures):
        print(line)
    for note in risk_notes(shallow_segments, short_segments, deep_nitrogen):
        print("warning: " + note)
    return oxygen_partial_pressures, deep_segments, long_segments


def main():
    dive = [(40, 50, 0.3, 0.7), (5, 3, 0.2, 0.8), (18, 45, 0.32, 0.68), (36, 12, 0.28, 0.72)]
    pressures, deep_segments, long_segments = plan(dive)
    exceeded = []
    for index, pressure in enumerate(pressures):
        if pressure > 1.4:
            exceeded.append("segment %d at ppO2 %.2f bar" % (index, pressure))
    print("deep segments: %d, long segments: %d" % (len(deep_segments), len(long_segments)))
    decompression_stops = []
    for segment in deep_segments:
        decompression_stops.append((segment[0] // 3) * 3)
    print("suggested first stops: %s" % decompression_stops)
    total_minutes = sum(time for _, time, _, _ in long_segments)
    print("time spent on long segments: %d min" % total_minutes)
    for message in exceeded:
        print("oxygen limit: " + message)


if __name__ == "__main__":
