def validate(runners):
    """Reject entries that are not (name, personal best, season best, reaction)."""
    malformed = []
    for entry in runners:
        if len(entry) != 4:
            malformed.append(entry)
    if malformed:
        raise ValueError("malformed competitor entries: %r" % (malformed,))
    negative = []
    for entry in runners:
        if min(entry[1:]) <= 0:
            negative.append(entry[0])
    if negative:
        raise ValueError("non-positive times for: %s" % ", ".join(negative))
    return runners


def seed(runners):
    names = []
    for runner in runners:
        names.append(runner[0])
    reaction_times = []
    for runner in runners:
        reaction_times.append(runner[3])
    average_times = []
    for runner in runners:
        average_times.append((runner[1] + runner[2]) / 2)
    elite_runners = []
    for runner in runners:
        if (runner[1] + runner[2]) / 2 < 10.0:
            elite_runners.append(runner)
    standard_runners = []
    for runner in runners:
        if (runner[1] + runner[2]) / 2 >= 10.0:
            standard_runners.append(runner)
    quick_starters = []
    for runner in runners:
        if runner[3] < 0.15:
            quick_starters.append(runner)
    slow_starters = []
    for runner in runners:
        if runner[3] > 0.2:
            slow_starters.append(runner)
    elite_personal_bests = []
    for runner in elite_runners:
        elite_personal_bests.append(runner[1])
    print("seeded %d athletes: %s" % (len(names), ", ".join(names)))
    print("reaction spread: %.3f - %.3f" % (min(reaction_times), max(reaction_times)))
    print("elite personal bests: %s" % elite_personal_bests)
    _standard_names = []
    for runner in standard_runners:
        _standard_names.append(runner[0])
    print("standard field: %s" % _standard_names)
    _slow_names = []
    for runner in slow_starters:
        _slow_names.append(runner[0])
    print("slow starters: %s" % _slow_names)
    return average_times, elite_runners, quick_starters


def lane_assignments(runners, average_times):
    """Fastest average gets the middle lanes, working outwards."""
    ranked = sorted(zip(runners, average_times), key=lambda pair: pair[1])
    lanes = [4, 5, 3, 6, 2, 7, 1, 8]
    _assignments = []
    for index, pair in enumerate(ranked):
        if index < len(lanes):
            _assignments.append((lanes[index], pair[0][0], pair[1]))
    return _assignments


def format_report(runners, average_times, elite_runners, quick_starters):
    elite_names = []
    for runner in elite_runners:
        elite_names.append(runner[0])
    quick_names = []
    for runner in quick_starters:
        quick_names.append(runner[0])
    lines = []
    for runner, average in zip(runners, average_times):
        lines.append("%-8s avg %5.2f  %s" % (runner[0], average,
                                     "ELITE" if runner in elite_runners else "STANDARD"))
    lines.append("elite: %s" % (", ".join(elite_names) or "none"))
    lines.append("quick starters: %s" % (", ".join(quick_names) or "none"))
    return lines


def main():
    heat = validate([
        ('John', 9.8, 10.0, 0.12),
        ('Mark', 10.5, 10.7, 0.25),
        ('Ade', 9.91, 9.87, 0.141),
        ('Tomas', 10.02, 9.95, 0.18),
        ('Bruno', 10.31, 10.44, 0.22),
    ])
    average_times, elite_runners, quick_starters = seed(heat)
    for line in format_report(heat, average_times, elite_runners, quick_starters):
        print(line)
    for lane, name, average in lane_assignments(heat, average_times):
        print("lane %d: %-8s %.2f" % (lane, name, average))
    medal_hopes = []
    for lane, name, average in lane_assignments(heat, average_times):
        if average < 10.0:
            medal_hopes.append(name)
    print("medal hopes: %s" % ", ".join(medal_hopes))


if __name__ == '__main__':
    main()

