def parse_sample(line):
    _fields = []
    for field in line.split(','):
        _fields.append(field.strip())
    horizon, depth, acidity, moisture = _fields
    return (horizon, int(depth), float(acidity), int(moisture))


def load_samples(lines):
    _result = []
    for line in lines:
        if line.strip():
            _result.append(parse_sample(line))
    return _result


def validate(samples):
    problems = []
