        _wet_lines.append("  %s (%d%% moisture)" % (sample[0], sample[3]))
    lines += _wet_lines
    _adjusted_strs = []
    for d in adjusted_depths:
        _adjusted_strs.append(str(d))
    lines.append("Adjusted depths: %s" % ", ".join(_adjusted_strs))
    return "\n".join(lines)


