LAST_RUN = {}


def parse_row(row):
    fields = []
    for field in row.split(","):
        fields.append(int(field.strip()))
    if len(fields) != 4:
        raise ValueError("a throw needs speed, angle, offset and weight: %r" % row)
    return tuple(fields)


def parse_throws(rows):
    filled = []
    for row in rows:
        if row.strip():
            filled.append(row)
    _temp = []
    for row in filled:
        _temp.append(parse_row(row))
    return _temp


def average(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def simulate(throws):
    speeds = []
    for throw in throws:
        speeds.append(throw[0])
    weights = []
    for throw in throws:
        weights.append(throw[3])
    energies = []
    for speed, weight in zip(speeds, weights):
        energies.append(weight * speed * speed)
    pocket_hits = []
    for throw in throws:
        if throw[2] < 2:
            pocket_hits.append(throw)
    wide_hits = []
    for throw in throws:
        if throw[2] > 5:
            wide_hits.append(throw)
    sharp_angle_hits = []
    for throw in throws:
        if throw[1] > 4:
            sharp_angle_hits.append(throw)
    flat_angle_hits = []
    for throw in throws:
        if throw[1] < 2:
            flat_angle_hits.append(throw)
    pocket_offsets = []
    for throw in pocket_hits:
        pocket_offsets.append(throw[2])
    LAST_RUN.clear()
    LAST_RUN.update(
        speeds=speeds,
        weights=weights,
        wide_hits=wide_hits,
        flat_angle_hits=flat_angle_hits,
        pocket_offsets=pocket_offsets,
    )
    return energies, pocket_hits, sharp_angle_hits


def format_report(result):
    energies, pocket_hits, sharp_angle_hits = result
    lines = []
    for index, energy in enumerate(energies, 1):
        lines.append("throw %d: energy %d" % (index, energy))
    _temp1 = []
    for offset in LAST_RUN["pocket_offsets"]:
        _temp1.append("pocket hit at offset %d" % offset)
    lines += _temp1
    _temp2 = []
    for throw in LAST_RUN["wide_hits"]:
        _temp2.append("wide hit at %d mph, offset %d" % (throw[0], throw[2]))
    lines += _temp2
    _temp3 = []
    for throw in sharp_angle_hits:
        _temp3.append("sharp angle %d degrees" % throw[1])
    lines += _temp3
