def validate(caches):
    """Return the caches as a list of 4-tuples, rejecting malformed entries."""
    cleaned = []
    for cache in caches:
        cleaned.append(tuple(cache))
    bad = []
    for cache in cleaned:
        if len(cache) != 4:
            bad.append(cache)
    if bad:
        raise ValueError("each cache needs lat, lon, terrain, puzzle: %r" % (bad[0],))
    return cleaned


def navigate(caches):
    """Survey the caches and report difficulty scores and the notable groups."""
    caches = validate(caches)
    latitudes = []
    for cache in caches:
        latitudes.append(cache[0])
    longitudes = []
    for cache in caches:
        longitudes.append(cache[1])
    total_difficulties = []
    for _, _, terrain, puzzle in caches:
        total_difficulties.append(terrain + puzzle)
    extreme_terrain = []
    for cache in caches:
        if cache[2] > 4:
            extreme_terrain.append(cache)
    flat_terrain = []
    for cache in caches:
        if cache[2] < 2:
            flat_terrain.append(cache)
    hard_puzzles = []
    for cache in caches:
        if cache[3] == 5:
            hard_puzzles.append(cache)
    easy_puzzles = []
    for cache in caches:
        if cache[3] == 1:
            easy_puzzles.append(cache)
    extreme_difficulties = []
    for cache in extreme_terrain:
        extreme_difficulties.append(cache[2] + cache[3])
    print("surveyed %d caches between latitude %.1f and %.1f"
          % (len(caches), min(latitudes), max(latitudes)))
    print("longitude span: %.1f to %.1f" % (min(longitudes), max(longitudes)))
    print("flat terrain: %d, easy puzzles: %d" % (len(flat_terrain), len(easy_puzzles)))
    if extreme_difficulties:
        print("extreme terrain difficulty scores: %s" % extreme_difficulties)
    return total_difficulties, extreme_terrain, hard_puzzles


def bearing_labels(caches):
    """Label each cache by the hemisphere quadrant it sits in."""
    caches = validate(caches)
    result = []
    for lat, lon, _, _ in caches:
        result.append("%s%s" % ("N" if lat >= 0 else "S", "E" if lon >= 0 else "W"))
    return result


def format_report(caches):
    """Build printable lines describing every cache and its difficulty."""
    scores, extreme_terrain, hard_puzzles = navigate(caches)
    labels = bearing_labels(caches)
    flags = []
    for cache in caches:
        flags.append("extreme" if cache in extreme_terrain else "normal")
    puzzles = []
    for cache in caches:
        puzzles.append("tough" if cache in hard_puzzles else "fair")
    lines = []
    for index, cache in enumerate(caches):
        lines.append("%2d %-2s (%7.2f, %8.2f) score=%2d terrain=%s puzzle=%s"
                     % (index + 1, labels[index], cache[0], cache[1],
                        scores[index], flags[index], puzzles[index]))
    return lines


def hardest(caches):
    """Return the caches whose total difficulty equals the maximum observed."""
    scores, _, _ = navigate(caches)
    if not scores:
        return []
    top = max(scores)
    result = []
    for cache, score in zip(caches, scores):
        if score == top:
            result.append(cache)
    return result


