def validate(jumps):
    """Reject malformed jump records before any analysis is attempted."""
    bad_shapes = []
    for jump in jumps:
        if len(jump) != 4:
            bad_shapes.append(jump)
    if bad_shapes:
        raise ValueError("each jump needs 4 fields, got %r" % (bad_shapes[0],))
    inverted = []
    for jump in jumps:
        if jump[1] >= jump[0]:
            inverted.append(jump)
    if inverted:
        raise ValueError("deployment must be below exit: %r" % (inverted[0],))
    return jumps


def average_fall_rate(jumps):
    """Feet per second of descent during freefall, one value per jump."""
    rates = []
    for exit_alt, dep, dur, _ in jumps:
        if dur > 0:
            rates.append((exit_alt - dep) / dur)
    if not rates:
        return 0.0
    return sum(rates) / len(rates)


def review(jumps):
    exit_altitudes = []
    for jump in jumps:
        exit_altitudes.append(jump[0])
    deployment_altitudes = []
    for jump in jumps:
        deployment_altitudes.append(jump[1])
    freefall_distances = []
    for exit_alt, dep in zip(exit_altitudes, deployment_altitudes):
        freefall_distances.append(exit_alt - dep)
    high_altitude_exits = []
    for jump in jumps:
        if jump[0] > 15000:
            high_altitude_exits.append(jump)
    low_altitude_exits = []
    for jump in jumps:
        if jump[0] < 10000:
            low_altitude_exits.append(jump)
    dangerous_deployments = []
    for jump in jumps:
        if jump[1] < 2000:
            dangerous_deployments.append(jump)
    safe_deployments = []
    for jump in jumps:
        if jump[1] > 3000:
            safe_deployments.append(jump)
    dangerous_wing_loadings = []
    for jump in dangerous_deployments:
        dangerous_wing_loadings.append(jump[3])

    print("jumps reviewed: %d" % len(jumps))
    print("high exits: %d, low exits: %d" % (len(high_altitude_exits), len(low_altitude_exits)))
    print("safe deployments: %d, dangerous: %d" % (len(safe_deployments), len(dangerous_deployments)))
    if dangerous_wing_loadings:
        print("wing loadings at risk: %s" % (dangerous_wing_loadings,))

    return freefall_distances, high_altitude_exits, dangerous_deployments


def format_report(jumps, freefall_distances, high_altitude_exits, dangerous_deployments):
    """Build a human readable line per jump, plus summary lines."""
    lines = []
    for index, (jump, fall) in enumerate(zip(jumps, freefall_distances)):
        lines.append(
            "jump %d: exit %d ft, pull %d ft, %d ft of freefall, WL %.2f"
            % (index + 1, jump[0], jump[1], fall, jump[3])
        )
    flagged = []
    for jump in dangerous_deployments:
        flagged.append("  WARNING low pull on jump %d" % (jumps.index(jump) + 1))
    lines.extend(flagged)
    lines.append("high altitude exits: %d" % len(high_altitude_exits))
    lines.append("mean fall rate: %.1f ft/s" % average_fall_rate(jumps))
    return "\n".join(lines)


def main():
    logbook = [
        (18000, 4000, 60, 1.5),
        (9000, 1000, 30, 2.0),
        (13500, 3500, 55, 1.1),
        (16000, 1800, 70, 1.8),
    ]
    validate(logbook)
    distances, high_exits, dangerous = review(logbook)
    print(format_report(logbook, distances, high_exits, dangerous))
    deep_falls = []
    for distance in distances:
        if distance > 10000:
            deep_falls.append(distance)
    print("falls longer than 10000 ft: %s" % (deep_falls,))


