def percentages(proportions):
    """Return each proportion as a percentage of the list's total."""
    total = sum(proportions)
    if total == 0:
        result = []
        for _ in proportions:
            result.append(0.0)
        return result
    result = []
    for p in proportions:
        result.append(round(p * 100.0 / total, 2))
    return result


def scale(proportions, factor):
    """Return the proportions multiplied by the given factor."""
    result = []
    for p in proportions:
        result.append(p * factor)
    return result


def validate(recipes):
    """Reject recipes whose fields are not a name, a base code and pigments."""
    bad_shapes = []
    for r in recipes:
        if len(r) != 3:
            bad_shapes.append(r)
    if bad_shapes:
        raise ValueError("each recipe needs a name, a base code and proportions")
    bad_names = []
    for r in recipes:
        if not isinstance(r[0], str):
            bad_names.append(r[0])
    if bad_names:
        raise TypeError("color names must be strings: %r" % (bad_names,))
    bad_codes = []
    for r in recipes:
        if not isinstance(r[1], int):
            bad_codes.append(r[0])
    if bad_codes:
        raise TypeError("base codes must be integers for: %r" % (bad_codes,))
    negatives = []
    for r in recipes:
        if min(r[2], default=0) < 0:
            negatives.append(r[0])
    if negatives:
        raise ValueError("proportions must be non-negative for: %r" % (negatives,))


def formulate(recipes):
    """Derive eight lists describing the given pigment recipes."""
    validate(recipes)
    base_one = []
    for name, code, _ in recipes:
        if code == 1:
            base_one.append(name)
    totals = []
    for _, _, props in recipes:
        totals.append(sum(props))
    doubled = []
    for _, _, props in recipes:
        doubled.append(scale(props, 2))
    many_pigments = []
    for name, _, props in recipes:
        if len(props) > 3:
            many_pigments.append(name)
    codes_plus_ten = []
    for _, code, _ in recipes:
        codes_plus_ten.append(code + 10)
    strong = []
    for _, _, props in recipes:
        for p in props:
            if p > 20:
                strong.append(p)
    upper_names = []
    for name, _, _ in recipes:
        upper_names.append(name.upper())
    shares = []
    for _, _, props in recipes:
        shares.append(percentages(props))
    return (base_one, totals, doubled, many_pigments,
            codes_plus_ten, strong, upper_names, shares)


def report(recipes):
    """Render a human readable summary of the formulation results."""
    (base_one, totals, doubled, many_pigments,
     codes_plus_ten, strong, upper_names, shares) = formulate(recipes)
    lines = ["Recipes analysed: %d" % len(recipes)]
    lines.append("Base code 1: " + ", ".join(base_one))
    totals_strs = []
    for t in totals:
        totals_strs.append(str(t))
    lines.append("Totals: " + ", ".join(totals_strs))
    codes_strs = []
    for c in codes_plus_ten:
        codes_strs.append(str(c))
    lines.append("Shifted codes: " + ", ".join(codes_strs))
    lines.append("Complex recipes: " + ", ".join(many_pigments))
    strong_strs = []
    for p in strong:
        strong_strs.append(str(p))
    lines.append("Strong pigments: " + ", ".join(strong_strs))
    for name, scaled, share in zip(upper_names, doubled, shares):
        parts = []
        for s in share:
            parts.append("%s%%" % s)
        lines.append("%-8s scaled=%s shares=%s" % (name, scaled, ", ".join(parts)))
    return "\n".join(lines)


