def deviations(scores):
    """Return how far each health score is from a perfect score of 100."""
    result = []
    for score in scores:
        result.append(100 - score)
    return result


def average_health(scores):
    """Mean of a site's health scores; 0.0 when no scores were recorded."""
    if not scores:
        return 0.0
    return sum(scores) / len(scores)


def to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32


def is_endangered(temperature, scores):
    return temperature > 30 or average_health(scores) < 50


def validate(reefs):
    """Raise ValueError naming every malformed reef record."""
    problems = []
    for entry in reefs:
        if len(entry) != 3:
            problems.append(str(entry))
    if problems:
        raise ValueError("malformed reef records: " + ", ".join(problems))
    bad_scores = []
    for name, _, scores in reefs:
        if not isinstance(scores, list):
            bad_scores.append(name)
    if bad_scores:
        raise ValueError("health scores must be lists: " + ", ".join(bad_scores))


def monitor(reefs):
    validate(reefs)
    hot_sites = []
    for name, temperature, _ in reefs:
        if temperature > 30:
            hot_sites.append(name)
    averages = []
    for _, _, scores in reefs:
        averages.append(average_health(scores))
    scaled_scores = []
    for _, _, scores in reefs:
        for score in scores:
            scaled_scores.append(score * 10)
    triple_sites = []
    for name, _, scores in reefs:
        if len(scores) == 3:
            triple_sites.append(name)
    fahrenheit = []
    for _, temperature, _ in reefs:
        fahrenheit.append(to_fahrenheit(temperature))
    critical_scores = []
    for _, _, scores in reefs:
        for score in scores:
            if score < 20:
                critical_scores.append(score)
    alerts = []
    for name, temperature, scores in reefs:
        if is_endangered(temperature, scores):
            alerts.append("{} is in danger".format(name))
    deviation_lists = []
    for _, _, scores in reefs:
        deviation_lists.append(deviations(scores))
    return (
        hot_sites,
        averages,
        scaled_scores,
        triple_sites,
        fahrenheit,
        critical_scores,
        alerts,
        deviation_lists,
    )


def format_report(reefs):
    """Build one human readable line per reef site, plus the alert lines."""
    _, averages, _, _, fahrenheit, _, alerts, deviation_lists = monitor(reefs)
    names = []
    for name, _, _ in reefs:
        names.append(name)
    rows = zip(names, fahrenheit, averages, deviation_lists)
    lines = []
    for name, temp_f, avg, gaps in rows:
        lines.append("{:<8} {:>6.1f}F  avg={:>5.1f}  gaps={}".format(name, temp_f, avg, gaps))
    return lines + alerts


def main():
    reefs = [
        ("north", 32, [50, 60]),
        ("south", 27.5, [88, 91, 95]),
        ("east", 30.2, [18, 42, 70]),
        ("west", 24, [12]),
    ]
    for line in format_report(reefs):
        print(line)
    _, _, scaled, triples, _, critical, _, _ = monitor(reefs)
    print("scaled:", scaled)
    print("three-score sites:", triples)
    print("critical scores:", critical)


