def acceleration(distances):
    """Year over year acceleration rates from consecutive retreat distances."""
    _result = []
    for i in range(1, len(distances)):
        _result.append(distances[i] - distances[i - 1])
    return _result


def validate(glaciers):
    """Reject records that are not (name, latitude, list-of-distances)."""
    malformed = []
    for entry in glaciers:
        if len(entry) != 3:
            malformed.append(entry)
    if malformed:
        raise ValueError("each glacier needs a name, a latitude and distances: %r" % (malformed,))
    bad_latitudes = []
    for name, lat, _ in glaciers:
        if abs(lat) > 90:
            bad_latitudes.append(name)
    if bad_latitudes:
        raise ValueError("latitude out of range for: %s" % ", ".join(bad_latitudes))
    bad_series = []
    for name, _, series in glaciers:
        if not isinstance(series, list):
            bad_series.append(name)
    if bad_series:
        raise ValueError("retreat distances must be a list for: %s" % ", ".join(bad_series))


def to_centimetres(series):
    """Convert metre readings to centimetres."""
    _result = []
    for distance in series:
        _result.append(distance * 100)
    return _result


def join_numbers(values):
    """Render numeric readings as a comma separated string."""
    _parts = []
    for value in values:
        _parts.append("%g" % value)
    return ", ".join(_parts)


def track(glaciers):
    validate(glaciers)
    polar_names = []
    for name, lat, _ in glaciers:
        if lat > 60:
            polar_names.append(name)
    totals = []
    for _, _, series in glaciers:
        totals.append(sum(series))
    centimetres = []
    for _, _, series in glaciers:
        centimetres.append(to_centimetres(series))
    well_sampled = []
    for name, _, series in glaciers:
        if len(series) > 20:
            well_sampled.append(name)
    abs_latitudes = []
    for _, lat, _ in glaciers:
        abs_latitudes.append(abs(lat))
    large_retreats = []
    for _, _, series in glaciers:
        for d in series:
            if d > 10:
                large_retreats.append(d)
    summaries = []
    for name, lat, _ in glaciers:
        summaries.append("%s at %g deg" % (name, lat))
    accelerations = []
    for _, _, series in glaciers:
        accelerations.append(acceleration(series))
    return (polar_names, totals, centimetres, well_sampled,
            abs_latitudes, large_retreats, summaries, accelerations)


def fastest_accelerating(glaciers):
    """Name of the glacier whose latest acceleration rate is highest."""
    latest = []
    for name, _, series in glaciers:
        if len(series) > 1:
            latest.append((name, acceleration(series)[-1]))
    if not latest:
        return None
    return max(latest, key=lambda pair: pair[1])[0]


def report(glaciers):
    """Render a plain text report from the tracked lists."""
    polar, totals, centimetres, well_sampled, _, large, summaries, rates = track(glaciers)
    lines = []
    for summary, total, cm in zip(summaries, totals, centimetres):
        lines.append("%s: total %g m (%s cm)" % (summary, total, join_numbers(cm)))
    _extra = []
    for (name, _, _), rate in zip(glaciers, rates):
        _extra.append("%s acceleration: %s" % (name, join_numbers(rate) or "n/a"))
    lines += _extra
    lines.append("above 60 deg: %s" % (", ".join(polar) or "none"))
    lines.append("long records: %s" % (", ".join(well_sampled) or "none"))
    lines.append("retreats over 10 m: %s" % (join_numbers(large) or "none"))
    leader = fastest_accelerating(glaciers)
    if leader:
        lines.append("fastest accelerating: %s" % leader)
    return "\n".join(lines)


def main():
    glaciers = [
        ("icy", 65, [5, 7]),
        ("southpeak", -47.5, [12, 11, 15, 22]),
        ("still", 61, [3]),
    ]
    print(report(glaciers))


if __name__ == "__main__":
    main()

