TRANSMISSION_RATE = 0.9
MIN_OUTPUT_THRESHOLD = 10
IDEAL_CAPACITY = 100
FEET_PER_METRE = 3.28084
LARGE_DIAMETER = 80
FULL_MONTH_DAYS = 30


def efficiency_percentages(daily_outputs):
    _result = []
    for output in daily_outputs:
        _result.append(round(output / IDEAL_CAPACITY * 100, 2))
    return _result


def validate(turbines):
    problems = []
    for record in turbines:
        if len(record) != 3:
            problems.append("turbine %r must be (id, diameter, outputs)" % (record,))
    bad_ids = []
    for record in turbines:
        if not isinstance(record[0], int):
            bad_ids.append(record[0])
    _problems_extra = []
    for bad in bad_ids:
        _problems_extra.append("identifier %r is not an integer" % (bad,))
    problems += _problems_extra
    negative = []
    for record in turbines:
        if record[1] <= 0:
            negative.append(record[0])
    _problems_extra2 = []
    for tid in negative:
        _problems_extra2.append("turbine %d has a non-positive diameter" % tid)
    problems += _problems_extra2
    if problems:
        raise ValueError("; ".join(problems))
    return turbines


def evaluate(turbines):
    validate(turbines)
    large_diameter_ids = []
    for tid, diameter, _ in turbines:
        if diameter > LARGE_DIAMETER:
            large_diameter_ids.append(tid)
    total_outputs = []
    for _, _, outputs in turbines:
        total_outputs.append(sum(outputs))
    transmitted = []
    for _, _, outputs in turbines:
        _inner = []
        for output in outputs:
            _inner.append(round(output * TRANSMISSION_RATE, 4))
        transmitted.append(_inner)
    full_month_ids = []
    for tid, _, outputs in turbines:
        if len(outputs) == FULL_MONTH_DAYS:
            full_month_ids.append(tid)
    diameters_in_feet = []
    for _, diameter, _ in turbines:
        diameters_in_feet.append(round(diameter * FEET_PER_METRE, 3))
    low_outputs = []
    for _, _, outputs in turbines:
        for output in outputs:
            if output < MIN_OUTPUT_THRESHOLD:
                low_outputs.append(output)
    identifier_strings = []
    for tid, _, _ in turbines:
        identifier_strings.append(str(tid))
    efficiencies = []
    for _, _, outputs in turbines:
        efficiencies.append(efficiency_percentages(outputs))
    return (
        large_diameter_ids,
        total_outputs,
        transmitted,
        full_month_ids,
        diameters_in_feet,
        low_outputs,
        identifier_strings,
        efficiencies,
    )


def format_report(turbines):
    large, totals, transmitted, full_month, feet, low, names, effs = evaluate(turbines)
    lines = []
    for name, total, width, eff in zip(names, totals, feet, effs):
        lines.append(
            "turbine %s: total=%.2f, diameter=%.3f ft, mean efficiency=%.2f%%"
            % (name, total, width, sum(eff) / len(eff) if eff else 0.0)
        )
    lines.append("oversized turbines: %s" % (large or "none"))
    lines.append("turbines with a full month of data: %s" % (full_month or "none"))
    lines.append("outputs below threshold: %s" % (low or "none"))
    delivered = []
    for values in transmitted:
        delivered.append(round(sum(values), 2))
    lines.append("delivered energy after transmission: %s" % delivered)
    return "\n".join(lines)


def main():
    _outputs_11 = []
    for day in range(FULL_MONTH_DAYS):
        _outputs_11.append(float(day % 40))
    fleet = [
        (5, 90, [50, 60]),
        (7, 75, [12, 8, 45, 9]),
        (11, 120, _outputs_11),
    ]
    print(format_report(fleet))


if __name__ == "__main__":
    main()

