def average(concentrations):
    return sum(concentrations) / len(concentrations)


def ratios_to_average(concentrations):
    mean = average(concentrations)
    return [round(value / mean, 4) for value in concentrations]


def scale(concentrations, factor=1000):
    return [value * factor for value in concentrations]


def validate(vents):
    empty = [vent_id for vent_id, depth, concs in vents if not concs]
    if empty:
        raise ValueError("vents without readings: %s" % empty)
    negative = [vent_id for vent_id, depth, concs in vents if depth < 0]
    if negative:
        raise ValueError("vents with negative depth: %s" % negative)


def sample(vents):
    validate(vents)
    deep_ids = [vent_id for vent_id, depth, concs in vents if depth > 2000]
    peak_concentrations = [max(concs) for vent_id, depth, concs in vents]
    scaled = [scale(concs) for vent_id, depth, concs in vents]
    rich_ids = [vent_id for vent_id, depth, concs in vents if len(concs) > 5]
    depths_km = [depth / 1000.0 for vent_id, depth, concs in vents]
    toxicity = [
        (value, value > 50)
        for vent_id, depth, concs in vents
        for value in concs
    ]
    labels = ["vent %d @ %gm" % (vent_id, depth) for vent_id, depth, concs in vents]
    ratio_lists = [ratios_to_average(concs) for vent_id, depth, concs in vents]
    return (
        deep_ids,
        peak_concentrations,
        scaled,
        rich_ids,
        depths_km,
        toxicity,
        labels,
        ratio_lists,
    )


def toxic_fraction(toxicity):
    flags = [flag for value, flag in toxicity]
    return sum(flags) / len(flags)


def report(vents):
    (deep_ids, peaks, scaled, rich_ids, depths_km,
     toxicity, labels, ratio_lists) = sample(vents)
    lines = [
        "%s peak=%g depth=%gkm" % (label, peak, km)
        for label, peak, km in zip(labels, peaks, depths_km)
    ]
    lines += ["spread %.4f" % (max(r) - min(r)) for r in ratio_lists]
    lines.append("deep vents: %s" % deep_ids)
    lines.append("vents with many readings: %s" % rich_ids)
    lines.append("scaled totals: %s" % [sum(group) for group in scaled])
    lines.append("toxic fraction: %.2f" % toxic_fraction(toxicity))
    return lines


def main():
    vents = [
        (9, 3000, [10, 20]),
        (4, 1500, [5, 12, 55, 60, 61, 70]),
        (7, 2400, [80, 45, 30]),
    ]
    for line in report(vents):
        print(line)


if __name__ == "__main__":
    main()

