def magnitude_shifts(magnitudes):
    """Differences between consecutive tremor magnitudes."""
    result = []
    for earlier, later in zip(magnitudes, magnitudes[1:]):
        result.append(later - earlier)
    return result


def largest_swing(shifts):
    """Biggest absolute magnitude change in one volcano's shift series."""
    swings = []
    for shift in shifts:
        swings.append(abs(shift))
    return max(swings, default=0.0)


def round_shifts(shifts):
    """Shifts rounded for display."""
    rounded = []
    for shift in shifts:
        rounded.append(round(shift, 2))
    return rounded


def validate(volcanoes):
    """Reject entries that are not (name, elevation, magnitude list) triples."""
    bad_shapes = []
    for entry in volcanoes:
        if len(entry) != 3:
            bad_shapes.append(entry)
    if bad_shapes:
        raise ValueError("each volcano needs a name, an elevation and magnitudes: %r" % (bad_shapes[0],))
    bad_names = []
    for entry in volcanoes:
        if not isinstance(entry[0], str):
            bad_names.append(entry)
    if bad_names:
        raise ValueError("volcano name must be a string: %r" % (bad_names[0],))
    bad_magnitudes = []
    for name, _, mags in volcanoes:
        if not isinstance(mags, list):
            bad_magnitudes.append(name)
    if bad_magnitudes:
        raise ValueError("tremor magnitudes must be a list for %s" % bad_magnitudes[0])


def analyze(volcanoes):
    validate(volcanoes)
    high_volcanoes = []
    for name, elevation, _ in volcanoes:
        if elevation > 3000:
            high_volcanoes.append(name)
    peak_magnitudes = []
    for _, _, mags in volcanoes:
        if mags:
            peak_magnitudes.append(max(mags))
    energy_proxies = []
    for _, _, mags in volcanoes:
        for mag in mags:
            energy_proxies.append(mag ** 2)
    busy_volcanoes = []
    for name, _, mags in volcanoes:
        if len(mags) > 50:
            busy_volcanoes.append(name)
    elevations_feet = []
    for _, elevation, _ in volcanoes:
        elevations_feet.append(elevation * 3.28084)
    dangerous = []
    for _, _, mags in volcanoes:
        for mag in mags:
            if mag > 6:
                dangerous.append(mag)
    lowercase_names = []
    for name, _, _ in volcanoes:
        lowercase_names.append(name.lower())
    shift_series = []
    for _, _, mags in volcanoes:
        shift_series.append(magnitude_shifts(mags))
    return (
        high_volcanoes,
        peak_magnitudes,
        energy_proxies,
        busy_volcanoes,
        elevations_feet,
        dangerous,
        lowercase_names,
        shift_series,
    )


def summarize(volcanoes):
    """Build one human readable line per volcano."""
    _, peaks, _, _, feet, _, names, shifts = analyze(volcanoes)
    biggest_swings = []
    for series in shifts:
        biggest_swings.append(largest_swing(series))
    rows = zip(names, feet, peaks, biggest_swings)
    lines = []
    for row in rows:
        lines.append("%-10s %8.0f ft  peak %.1f  max swing %.1f" % row)
    return lines


def main():
    volcanoes = [
        ("Peak", 4000, [3, 4]),
        ("Kilauea", 1247, [2.1, 3.4, 6.2, 5.0]),
        ("Etna", 3357, [4.0, 6.5, 6.8, 2.2]),
        ("Rainier", 4392, [1.0]),
    ]
    high, peaks, energies, busy, feet, dangerous, lowered, shifts = analyze(volcanoes)
    print("above 3000 m:", high)
    print("peak magnitudes:", peaks)
    print("energy proxies:", energies)
    print("more than 50 tremors:", busy)
    rounded_feet = []
    for f in feet:
        rounded_feet.append(round(f, 1))
    print("elevations in feet:", rounded_feet)
    print("dangerous tremors:", dangerous)
    print("names lowercased:", lowered)
    displayed_shifts = []
    for series in shifts:
        displayed_shifts.append(round_shifts(series))
    print("magnitude shifts:", displayed_shifts)
    for line in summarize(volcanoes):
        print(line)


if __name__ == "__main__":
    main()

