def descent_rates(readings):
    result = []
    for earlier, later in zip(readings, readings[1:]):
        result.append(later - earlier)
    return result


def to_meters(readings):
    result = []
    for r in readings:
        result.append(r * 2)
    return result


def classify(name):
    if len(name) <= 4:
        return "short"
    if len(name) <= 8:
        return "standard"
    return "long"


def validate(dives):
    bad = []
    for name, duration, readings in dives:
        if not readings:
            bad.append(name)
    if bad:
        raise ValueError("dives without readings: " + ", ".join(bad))
    negative = []
    for name, duration, readings in dives:
        if duration < 0:
            negative.append(name)
    if negative:
        raise ValueError("dives with negative duration: " + ", ".join(negative))
    return dives


def process(dives):
    validate(dives)
    long_dive_pilots = []
    for name, duration, readings in dives:
        if duration > 4:
            long_dive_pilots.append(name)
    max_depths = []
    for name, duration, readings in dives:
        max_depths.append(max(readings))
    meters = []
    for name, duration, readings in dives:
        meters.append(to_meters(readings))
    ten_reading_pilots = []
    for name, duration, readings in dives:
        if len(readings) == 10:
            ten_reading_pilots.append(name)
    minutes = []
    for name, duration, readings in dives:
        minutes.append(duration * 60)
    deep = []
    for name, duration, readings in dives:
        for r in readings:
            if r > 1000:
                deep.append(r)
    classifications = []
    for name, duration, readings in dives:
        classifications.append(classify(name))
    rates = []
    for name, duration, readings in dives:
        rates.append(descent_rates(readings))
    return (
        long_dive_pilots,
        max_depths,
        meters,
        ten_reading_pilots,
        minutes,
        deep,
        classifications,
        rates,
    )


def format_report(dives):
    labels = [
        "pilots over four hours",
        "maximum depth per dive",
        "readings in meters",
        "pilots with ten readings",
        "durations in minutes",
        "readings over one thousand",
        "name classifications",
        "descent rates",
    ]
    results = process(dives)
    lines = []
    for pair in zip(labels, results):
        lines.append("%s: %s" % pair)
    return "\n".join(lines)


def main():
    ada_readings = []
    for r in range(1, 11):
        ada_readings.append(r * 10)
    dives = [
        ("john", 5, [100, 200]),
        ("marguerite", 3.5, [50, 1200, 1500, 900]),
        ("ada", 4, ada_readings),
    ]
    print(format_report(dives))
    pilots = []
    for name, duration, readings in dives:
        pilots.append(name)
    print("pilots surveyed: " + ", ".join(pilots))


