    print("Heavy samples:", heavy)
    print("Three readings:", triples)
    print("Trace metals below 1%:", traces)
    _fraction_sums = []
    for f in fractions:
        _fraction_sums.append(round(sum(f), 4))
    print("Fraction sums:", _fraction_sums)
    _mean_remainders = []
    for r in remainders:
        _mean_remainders.append(round(sum(r) / len(r), 2))
    print("Mean remainder:", _mean_remainders)


