INCHES_PER_METER = 39.3701
GRAMS_PER_KILOGRAM = 1000.0
HEAVY_LIMIT = 50
BUSY_JUMP_COUNT = 10
LONG_JUMP_LIMIT = 20


def energy_profile(jumps):
    result = []
    for length in jumps:
        result.append(round(length ** 2, 2))
    return result


def to_inches(jumps):
    result = []
    for length in jumps:
        result.append(round(length * INCHES_PER_METER, 2))
    return result


def validate(kangaroos):
    problems = []
    for ident, weight, jumps in kangaroos:
        if not jumps:
            problems.append(ident)
    if problems:
        raise ValueError("kangaroos without jumps: {}".format(problems))
    light = []
    for ident, weight, jumps in kangaroos:
        if weight <= 0:
            light.append(ident)
    if light:
        raise ValueError("kangaroos with non-positive weight: {}".format(light))


def track(kangaroos):
    validate(kangaroos)
    heavy_ids = []
    for ident, weight, jumps in kangaroos:
        if weight > HEAVY_LIMIT:
            heavy_ids.append(ident)
    longest_jumps = []
    for ident, weight, jumps in kangaroos:
        longest_jumps.append(max(jumps))
    jumps_in_inches = []
    for ident, weight, jumps in kangaroos:
        jumps_in_inches.append(to_inches(jumps))
    busy_ids = []
    for ident, weight, jumps in kangaroos:
        if len(jumps) > BUSY_JUMP_COUNT:
            busy_ids.append(ident)
    weights_in_grams = []
    for ident, weight, jumps in kangaroos:
        weights_in_grams.append(weight * GRAMS_PER_KILOGRAM)
    long_jumps = []
    for ident, weight, jumps in kangaroos:
        for length in jumps:
            if length > LONG_JUMP_LIMIT:
                long_jumps.append(length)
    tags = []
    for ident, weight, jumps in kangaroos:
        tags.append("K-{}".format(ident))
    energies = []
    for ident, weight, jumps in kangaroos:
        energies.append(energy_profile(jumps))
    return (
        heavy_ids,
        longest_jumps,
        jumps_in_inches,
        busy_ids,
        weights_in_grams,
        long_jumps,
        tags,
        energies,
    )


def format_report(tags, longest_jumps, weights_in_grams, energies):
    totals = []
    for profile in energies:
        totals.append(sum(profile))
    rows = zip(tags, longest_jumps, weights_in_grams, totals)
    result = []
    for row in rows:
        result.append("{:<6} longest={:>6.2f}m mass={:>9.1f}g energy={:>9.2f}".format(*row))
    return result


