def decelerations(speeds):
    """Drop in speed between each pair of consecutive dives."""
    result = []
    for i in range(len(speeds) - 1):
        result.append(speeds[i] - speeds[i + 1])
    return result


def reduce_wind(speeds, resistance=5):
    """Every dive speed lowered by the wind resistance."""
    result = []
    for speed in speeds:
        result.append(speed - resistance)
    return result


def validate(flights):
    """Reject malformed records before they are measured."""
    wrong_shape = []
    for record in flights:
        if len(record) != 3:
            wrong_shape.append(record)
    if wrong_shape:
        raise ValueError("each flight needs identifier, wingspan and speeds: %r" % (wrong_shape[0],))
    empty = []
    for record in flights:
        if not record[2]:
            empty.append(record[0])
    if empty:
        raise ValueError("no dives recorded for: %s" % ", ".join(empty))
    return flights


def evaluate(flights):
    validate(flights)
    wide_falcons = []
    for name, span, _ in flights:
        if span > 40:
            wide_falcons.append(name)
    fastest_dive = []
    for _, _, speeds in flights:
        fastest_dive.append(max(speeds))
    wind_adjusted = []
    for _, _, speeds in flights:
        wind_adjusted.append(reduce_wind(speeds))
    frequent_divers = []
    for name, _, speeds in flights:
        if len(speeds) > 5:
            frequent_divers.append(name)
    spans_in_metres = []
    for _, span, _ in flights:
        spans_in_metres.append(round(span * 0.0254, 3))
    fast_speeds = []
    for _, _, speeds in flights:
        for speed in speeds:
            if speed > 100:
                fast_speeds.append(speed)
    labels = []
    for name, _, _ in flights:
        labels.append(name.upper())
    slowdowns = []
    for _, _, speeds in flights:
        slowdowns.append(decelerations(speeds))
    return (
        wide_falcons,
        fastest_dive,
        wind_adjusted,
        frequent_divers,
        spans_in_metres,
        fast_speeds,
        labels,
        slowdowns,
    )


def format_report(flights):
    """Human readable summary of the per-falcon derived values."""
    _, fastest, adjusted, _, metres, _, labels, slowdowns = evaluate(flights)
    rows = zip(labels, metres, fastest, adjusted, slowdowns)
    lines = []
    for label, span, top, corrected, drops in rows:
        corrected_parts = []
        for speed in corrected:
            corrected_parts.append(str(speed))
        corrected_text = ", ".join(corrected_parts)
        drop_parts = []
        for drop in drops:
            drop_parts.append(str(drop))
        drop_text = ", ".join(drop_parts) or "none"
        lines.append(
            "%s: span %.3f m, top dive %s, wind adjusted [%s], decelerations [%s]"
            % (label, span, top, corrected_text, drop_text)
        )
    return "\n".join(lines)


def main():
    flights = [
        ("fast", 50, [90, 110]),
        ("stoop", 38, [130, 121, 118, 140, 99, 145, 150]),
        ("glide", 44, [80, 76, 71]),
    ]
    print(format_report(flights))
    wide, fastest, _, frequent, _, quick, _, _ = evaluate(flights)
    print("wide wingspans:", ", ".join(wide))
    print("frequent divers:", ", ".join(frequent))
    print("speeds above 100:", quick)
    print("record dive:", max(fastest))


if __name__ == "__main__":
    main()

