def daily_shifts(levels):
    """Return the differences between consecutive acidity readings."""
    return [later - earlier for earlier, later in zip(levels, levels[1:])]


def total_swing(shifts):
    """Return the summed magnitude of one batch's daily shifts."""
    return sum([abs(step) for step in shifts])


def validate(batches):
    """Raise ValueError if any batch record is malformed."""
    bad_names = [entry for entry in batches if not str(entry[0]).strip()]
    if bad_names:
        raise ValueError("every batch needs a non-empty name")
    bad_times = [name for name, time, _ in batches if time < 0]
    if bad_times:
        raise ValueError("negative fermentation time: %s" % ", ".join(bad_times))
    empty = [name for name, _, acidity in batches if not acidity]
    if empty:
        raise ValueError("no acidity readings for: %s" % ", ".join(empty))
    return batches


def process(batches):
    long_fermenting = [name for name, time, _ in batches if time > 10]
    peak_acidity = [max(acidity) for _, _, acidity in batches]
    scaled_acidity = [level * 100 for _, _, acidity in batches for level in acidity]
    seven_readings = [name for name, _, acidity in batches if len(acidity) == 7]
    hours = [time * 24 for _, time, _ in batches]
    overly_acidic = [level for _, _, acidity in batches for level in acidity if level > 5]
    premium_labels = ["Premium %s" % name for name, _, _ in batches]
    shifts = [daily_shifts(acidity) for _, _, acidity in batches]
    return (
        long_fermenting,
        peak_acidity,
        scaled_acidity,
        seven_readings,
        hours,
        overly_acidic,
        premium_labels,
        shifts,
    )


def summarize(batches):
    """Build one human readable line per batch from the processed lists."""
    _, peaks, _, _, hours, _, labels, shifts = process(batches)
    swing = [round(total_swing(batch_shifts), 2) for batch_shifts in shifts]
    return [
        "%s: peak %.2f, %d h, total swing %.2f" % row
        for row in zip(labels, peaks, hours, swing)
    ]


def main():
    batches = validate([
        ("sour", 12, [3, 6]),
        ("mild", 8, [1.2, 1.5, 1.4]),
        ("weekly", 14, [2, 3, 4, 5, 6, 7, 8]),
    ])
    results = process(batches)
    names = [
        "long fermenting", "peak acidity", "scaled acidity", "seven readings",
        "hours", "overly acidic", "premium labels", "daily shifts",
    ]
    for name, values in zip(names, results):
        print("%-16s %s" % (name, values))
    for line in summarize(batches):
        print(line)


if __name__ == "__main__":
    main()

