def to_kilometers(readings):
    """Convert a list of metre readings into kilometres."""
    _result = []
    for reading in readings:
        _result.append(reading / 1000.0)
    return _result


def climb_rates(readings):
    """Return the differences between consecutive altitude readings."""
    _result = []
    for earlier, later in zip(readings, readings[1:]):
        _result.append(later - earlier)
    return _result


def validate(balloons):
    """Reject flights that carry no altitude readings at all."""
    problems = []
    for bid, _weight, altitudes in balloons:
        if not altitudes:
            problems.append("balloon %d has no altitude readings" % bid)
    if problems:
        raise ValueError("; ".join(problems))


def analyze(balloons):
    validate(balloons)
    heavy_ids = []
    for bid, weight, _altitudes in balloons:
        if weight > 10:
            heavy_ids.append(bid)
    peak_altitudes = []
    for _bid, _weight, altitudes in balloons:
        peak_altitudes.append(max(altitudes))
    altitudes_km = []
    for _bid, _weight, altitudes in balloons:
        altitudes_km.append(to_kilometers(altitudes))
    chatty_ids = []
    for bid, _weight, altitudes in balloons:
        if len(altitudes) > 50:
            chatty_ids.append(bid)
    weights_oz = []
    for _bid, weight, _altitudes in balloons:
        weights_oz.append(weight * 35.27396)
    stratospheric = []
    for _bid, _weight, altitudes in balloons:
        for altitude in altitudes:
            if altitude > 30000:
                stratospheric.append(altitude)
    heavy_alerts = []
    for bid in heavy_ids:
        heavy_alerts.append("ALERT: balloon %d carries a heavy payload" % bid)
    all_climb_rates = []
    for _bid, _weight, altitudes in balloons:
        all_climb_rates.append(climb_rates(altitudes))
    return (heavy_ids, peak_altitudes, altitudes_km, chatty_ids,
            weights_oz, stratospheric, heavy_alerts, all_climb_rates)


def format_report(balloons, results):
    (heavy_ids, peak_altitudes, altitudes_km, chatty_ids,
     weights_oz, stratospheric, heavy_alerts, all_climb_rates) = results
    identifiers = []
    for bid, _weight, _altitudes in balloons:
        identifiers.append(bid)
    lines = []
    for bid, peak, kms, ounces, rates \
            in zip(identifiers, peak_altitudes, altitudes_km, weights_oz, all_climb_rates):
        lines.append("balloon %d: peak %.0f m (%.2f km), payload %.1f oz, climb rates %s"
                     % (bid, peak, max(kms), ounces, rates))
    lines.extend(heavy_alerts)
    if chatty_ids:
        labels = []
        for bid in chatty_ids:
            labels.append("#%d" % bid)
        lines.append("long-duration flights: " + ", ".join(labels))
    if stratospheric:
        peaks_km = []
        for value in to_kilometers(stratospheric):
            peaks_km.append("%.1f" % value)
        lines.append("stratospheric samples (km): " + ", ".join(peaks_km))
    return "\n".join(lines)


def main():
    long_climb = []
    for step in range(60):
        long_climb.append(20000 + 500 * step)
    balloons = [
        (2, 15, [10000, 12000]),
        (7, 4.5, [1500, 2800, 3100, 2900]),
        (9, 22, long_climb),
    ]
    results = analyze(balloons)
    print(format_report(balloons, results))
    totals = []
    for index, items in enumerate(results, start=1):
        totals.append("list %d holds %d item(s)" % (index, len(items)))
    print("\n".join(totals))


