def deviations(distances):
    """Return each pull distance minus the average distance of the list."""
    if not distances:
        return []
    average = sum(distances) / len(distances)
    return [round(d - average, 2) for d in distances]


def to_inches(distances):
    """Convert a list of metre distances to inches."""
    return [round(d * 39.3701, 1) for d in distances]


def validate(pulls):
    """Reject entries whose power or distances make no physical sense."""
    bad_power = [name for name, power, _ in pulls if power <= 0]
    if bad_power:
        raise ValueError("non-positive engine power: " + ", ".join(bad_power))
    bad_pulls = [name for name, _, dists in pulls if any(d < 0 for d in dists)]
    if bad_pulls:
        raise ValueError("negative pull distance: " + ", ".join(bad_pulls))


def award_for(name):
    return name.title() + " Trophy"


def summarize(pulls):
    validate(pulls)
    powerful = [name for name, power, _ in pulls if power > 500]
    best_pull = [max(dists) if dists else 0 for _, _, dists in pulls]
    in_inches = [to_inches(dists) for _, _, dists in pulls]
    busy = [name for name, _, dists in pulls if len(dists) > 3]
    kilowatts = [round(power * 0.7457, 2) for _, power, _ in pulls]
    aborted = [d for _, _, dists in pulls for d in dists if d < 10]
    awards = [award_for(name) for name, _, _ in pulls]
    spreads = [deviations(dists) for _, _, dists in pulls]
    return (powerful, best_pull, in_inches, busy, kilowatts, aborted, awards, spreads)


def format_report(names, kilowatts, best_pull, awards):
    """Build one aligned text line per tractor for printing."""
    width = max(len(name) for name in names)
    return [
        "{0:<{1}}  {2:>8.2f} kW  best {3:>6.1f} m  {4}".format(
            name, width, kw, best, award
        )
        for name, kw, best, award in zip(names, kilowatts, best_pull, awards)
    ]


def main():
    pulls = [
        ("beast", 600, [300, 350]),
        ("mule", 420, [120, 8, 145, 160, 7]),
        ("thunder", 510, [280, 295, 310, 9]),
        ("pony", 180, []),
    ]
    names = [name for name, _, _ in pulls]
    powerful, best_pull, in_inches, busy, kilowatts, aborted, awards, spreads = summarize(pulls)
    for line in format_report(names, kilowatts, best_pull, awards):
        print(line)
    print("over 500 hp:", ", ".join(powerful))
    print("more than three pulls:", ", ".join(busy))
    print("aborted pulls:", aborted)
    totals = [round(sum(row), 1) for row in in_inches]
    print("total inches pulled:", totals)
    for name, spread in zip(names, spreads):
        print(name, "deviation from own average:", spread)


if __name__ == "__main__":
    main()

