def bounce_deltas(heights):
    return [heights[i + 1] - heights[i] for i in range(len(heights) - 1)]


def double_heights(heights):
    return [height * 2 for height in heights]


def validation_errors(sessions):
    errors = [
        f"session {index}: expected a 3-tuple, got {len(session)} fields"
        for index, session in enumerate(sessions)
        if len(session) != 3
    ]
    errors += [
        f"session {index}: jumper name must be a string"
        for index, (name, _, _) in enumerate(sessions)
        if not isinstance(name, str)
    ]
    errors += [
        f"session {index}: {name} has no recorded bounces"
        for index, (name, _, heights) in enumerate(sessions)
        if not heights
    ]
    return errors


def elite_certificate(name):
    return f"CERTIFICATE OF ELITE BOUNCING: {name.upper()}"


def analyze(sessions):
    problems = validation_errors(sessions)
    if problems:
        raise ValueError("; ".join(problems))
    high_tension_jumpers = [name for name, tension, _ in sessions if tension > 80]
    peak_heights = [max(heights) for _, _, heights in sessions]
    doubled_heights = [double_heights(heights) for _, _, heights in sessions]
    fifty_bounce_jumpers = [name for name, _, heights in sessions if len(heights) == 50]
    relaxed_tensions = [tension - 10 for _, tension, _ in sessions]
    massive_bounces = [h for _, _, heights in sessions for h in heights if h > 5]
    certificates = [elite_certificate(name) for name, _, _ in sessions]
    height_changes = [bounce_deltas(heights) for _, _, heights in sessions]
    return (
        high_tension_jumpers,
        peak_heights,
        doubled_heights,
        fifty_bounce_jumpers,
        relaxed_tensions,
        massive_bounces,
        certificates,
        height_changes,
    )


def report_lines(sessions):
    high, peaks, doubled, fifty, relaxed, massive, certs, changes = analyze(sessions)
    lines = [
        f"{name}: peak={peak}, relaxed tension={tension}, changes={delta}"
        for (name, _, _), peak, tension, delta in zip(sessions, peaks, relaxed, changes)
    ]
    lines += [f"doubled heights -> {heights}" for heights in doubled]
    lines.append(f"over-tension jumpers: {', '.join(high) or 'none'}")
    lines.append(f"fifty-bounce jumpers: {', '.join(fifty) or 'none'}")
