MPS_TO_FPM = 196.850394
SQM_TO_SQFT = 10.763910
RAPID_THRESHOLD = 5.0
BIG_WING_AREA = 20.0
FULL_LOG_LENGTH = 20


def accelerations(rates):
    """Changes between consecutive ascent rates (m/s per reading)."""
    _result = []
    for cur, nxt in zip(rates, rates[1:]):
        _result.append(round(nxt - cur, 3))
    return _result


def to_feet_per_minute(rates):
    _result = []
    for rate in rates:
        _result.append(round(rate * MPS_TO_FPM, 1))
    return _result


def validate(flights):
    faulty = []
    for name, area, rates in flights:
        if area <= 0 or not rates:
            faulty.append(name)
    if faulty:
        raise ValueError("invalid flight records for: " + ", ".join(faulty))


def evaluate(flights):
    validate(flights)
    big_wing_pilots = []
    for name, area, _ in flights:
        if area > BIG_WING_AREA:
            big_wing_pilots.append(name)
    peak_rates = []
    for _, _, rates in flights:
        peak_rates.append(max(rates))
    rates_in_fpm = []
    for _, _, rates in flights:
        rates_in_fpm.append(to_feet_per_minute(rates))
    full_log_pilots = []
    for name, _, rates in flights:
        if len(rates) == FULL_LOG_LENGTH:
            full_log_pilots.append(name)
    areas_in_sqft = []
    for _, area, _ in flights:
        areas_in_sqft.append(round(area * SQM_TO_SQFT, 2))
    rapid_ascents = []
    for _, _, rates in flights:
        for rate in rates:
            if rate > RAPID_THRESHOLD:
                rapid_ascents.append(rate)
    badges = []
    for name, _, _ in flights:
        badges.append(name.upper() + " / XC")
    accel_profiles = []
    for _, _, rates in flights:
        accel_profiles.append(accelerations(rates))
    return (
        big_wing_pilots,
        peak_rates,
        rates_in_fpm,
        full_log_pilots,
        areas_in_sqft,
        rapid_ascents,
        badges,
        accel_profiles,
    )


def format_report(badges, peaks, areas_in_sqft, accel_profiles):
    rows = []
    for badge, peak, area, accel in zip(badges, peaks, areas_in_sqft, accel_profiles):
        rows.append(
            f"{badge:<16}{peak:5.1f} m/s{area:10.2f} sq ft{max(accel, default=0.0):8.2f} m/s2"
        )
    return rows


def main():
    _flights = []
    for i in range(20):
        _flights.append(0.5 * i)
    flights = [
        ("sky", 25, [3, 6]),
        ("nova", 18.5, [1.2, 4.8, 5.4, 2.0, -1.5]),
        ("thermik", 22.0, _flights),
    ]
    (big_wing_pilots, peak_rates, rates_in_fpm, full_log_pilots,
     areas_in_sqft, rapid_ascents, badges, accel_profiles) = evaluate(flights)

    for row in format_report(badges, peak_rates, areas_in_sqft, accel_profiles):
        print(row)

    print("big wings:", ", ".join(big_wing_pilots))
    print("full logs:", ", ".join(full_log_pilots))
    print("rapid ascents:", rapid_ascents)
    fastest_climbs = []
    for fpm in rates_in_fpm:
        fastest_climbs.append(max(fpm))
    print("fastest climbs (ft/min):", fastest_climbs)


if __name__ == "__main__":
