def clean_durations(flashes):
    """Keep only numeric readings that lasted longer than one second."""
    return [float(f) for f in flashes if isinstance(f, (int, float)) and f > 1.0]


def round_durations(durations):
    """Snap each duration to the nearest whole second."""
    return [round(d) for d in durations]


def short_flashes(rounded):
    return [d for d in rounded if d == 1]


def long_flashes(rounded):
    return [d for d in rounded if d >= 3]


def morse_characters(rounded):
    """One second is a dot, anything longer is a dash."""
    return ['.' if d == 1 else '-' for d in rounded]


def intervals_between(rounded):
    """Gap between the end of one flash and the start of the next."""
    return [later - earlier for earlier, later in zip(rounded, rounded[1:])]


def long_breaks(intervals):
    return [gap for gap in intervals if gap > 5]


def format_timestamp(seconds):
    hours, remainder = divmod(int(seconds), 3600)
    minutes, secs = divmod(remainder, 60)
    return "{:02d}:{:02d}:{:02d}".format(hours, minutes, secs)


def flash_timestamps(rounded):
    """Start time of every recorded flash, assuming they run back to back."""
    starts = [sum(rounded[:index]) for index in range(len(rounded))]
    return [format_timestamp(start) for start in starts]


def analyze(flashes):
    valid = clean_durations(flashes)
    rounded = round_durations(valid)
    morse = morse_characters(rounded)
    gaps = long_breaks(intervals_between(rounded))
    stamps = flash_timestamps(rounded)
    return morse, gaps, stamps


def report(flashes):
    morse, gaps, stamps = analyze(flashes)
    rounded = round_durations(clean_durations(flashes))
    entries = ["{} {}".format(stamp, char) for stamp, char in zip(stamps, morse)]
    lines = ["signal: " + "".join(morse)]
    lines.append("dots: {}".format(len(short_flashes(rounded))))
    lines.append("dashes: {}".format(len(long_flashes(rounded))))
    lines.append("long breaks: {}".format(", ".join(str(g) for g in gaps) or "none"))
    lines.extend(entries)
    return lines


def main():
    observed = [0.4, 1.2, 3.6, 1.1, "x", 7.4, 1.3, 2.8, 0.9, 4.2]
    for line in report(observed):
        print(line)


if __name__ == "__main__":
    main()

