def _action_word(height):
    if height == 0:
        return "pause"
    if height == 1:
        return "handoff"
    if height == 2:
        return "hold"
    return "cross" if height % 2 else "column"


def active_throws(throws):
    return [t for t in throws if t != 0]


def split_by_hand(active):
    same_hand = [t for t in active if t % 2 == 0]
    crossing = [t for t in active if t % 2 == 1]
    return same_hand, crossing


def landing_times(throws):
    return [height + index for index, height in enumerate(throws)]


def landing_beats(times, period):
    return [time % period for time in times]


def catch_heights(throws):
    return [t - 1 for t in throws]


def high_throws(active):
    return [t for t in active if t > 3]


def sequence_strings(throws):
    return ["beat %d: %s (%d)" % (i, _action_word(h), h) for i, h in enumerate(throws)]


def is_valid_pattern(beats):
    return sorted(beats) == list(range(len(beats)))


def validate(throws):
    if not isinstance(throws, list):
        raise TypeError("throws must be a list of integers")
    bad = [t for t in throws if not isinstance(t, int) or isinstance(t, bool)]
    if bad:
        raise TypeError("invalid throw heights: %r" % (bad,))
    negatives = [t for t in throws if t < 0]
    if negatives:
        raise ValueError("throw heights must be non-negative: %r" % (negatives,))
    active = active_throws(throws)
    same_hand, crossing = split_by_hand(active)
    times = landing_times(throws)
    beats = landing_beats(times, len(throws)) if throws else []
    catches = catch_heights(throws)
    highs = high_throws(active)
    strings = sequence_strings(throws)
    print("active: %d (same-hand %d, crossing %d)" % (len(active), len(same_hand), len(crossing)))
    print("high throws: %r" % (highs,))
    print("valid siteswap: %s" % is_valid_pattern(beats))
    return beats, catches, strings


def report(patterns):
    lines = []
    for pattern in patterns:
        beats, catches, strings = validate(pattern)
        label = "".join([str(t) for t in pattern])
        lines.append("%s -> beats %r catches %r" % (label, beats, catches))
        lines.extend(["   " + text for text in strings])
    return lines


def main():
    patterns = [[3, 3, 3], [5, 3, 1], [4, 4, 1], [5, 0, 1]]
    for line in report(patterns):
        print(line)


if __name__ == "__main__":
    main()

