        raise ValueError("negative radial distance at indices: %s" % negatives)


def classify(radius, intensity):
    if intensity <= 0.8:
        return "faint"
    return "inner-intense" if radius < 50 else "outer-intense"


def summarize(inner, outer, radians):
    lines = ["inner ring nodes: %d" % len(inner), "outer ring nodes: %d" % len(outer)]
    _temp_radians = []
    for value in radians:
        _temp_radians.append("  %.3f rad" % value)
    lines += _temp_radians
    _temp_outer = []
    for node in outer:
        _temp_outer.append(round(node[0], 1))
    lines.append("outer radii: %s" % _temp_outer)
    return "\n".join(lines)


def measure(nodes):
    validate(nodes)
    radial_distances = []
    for node in nodes:
        radial_distances.append(node[0])
    intense_nodes = []
    for node in nodes:
        if node[2] > 0.8:
            intense_nodes.append(node)
