import math


def validate(drones):
    malformed = [index for index, drone in enumerate(drones) if len(drone) != 3]
    if malformed:
        raise ValueError("drones at positions %s are not (x, y, battery) triples" % malformed)
    out_of_range = [index for index, (_, _, battery) in enumerate(drones) if not 0 <= battery <= 100]
    if out_of_range:
        raise ValueError("battery percentage out of range at positions %s" % out_of_range)


def horizontal_coords(drones):
    return [x for x, _, _ in drones]


def distances(drones):
    return [round(math.hypot(x, y), 2) for x, y, _ in drones]


def drifting_drones(drones, dists):
    return [drone for drone, dist in zip(drones, dists) if dist > 50]


def low_battery_drones(drones):
    return [drone for drone in drones if drone[2] < 20]


def return_vectors(drifting):
    return [(-x, -y) for x, y, _ in drifting]


def vertical_coords_with_power(drones):
    return [y for _, y, battery in drones if battery >= 20]


def charging_times(low):
    return [round((100 - battery) * 0.6, 1) for _, _, battery in low]


def flight_commands(drones, dists):
    commands = []
    for (x, y, battery), dist in zip(drones, dists):
        if dist > 50:
            commands.append("RETURN TO BASE from (%s, %s)" % (x, y))
        elif battery < 20:
            commands.append("LAND AND CHARGE at %d%%" % battery)
        else:
            commands.append("HOLD POSITION at (%s, %s)" % (x, y))
    return commands


def format_report(xs, ys, charge_times):
    lines = ["horizontal spread: %s .. %s" % (min(xs), max(xs))]
    lines.append("altitudes with usable power: %s" % ys)
    lines.extend(["charging slot needed: %.1f min" % minutes for minutes in charge_times])
    return lines


def navigate(drones):
    validate(drones)
    xs = horizontal_coords(drones)
    dists = distances(drones)
    drifting = drifting_drones(drones, dists)
    low = low_battery_drones(drones)
    vectors = return_vectors(drifting)
    ys = vertical_coords_with_power(drones)
    charge_times = charging_times(low)
    commands = flight_commands(drones, dists)
    for line in format_report(xs, ys, charge_times):
        print(line)
    return drifting, vectors, commands


def main():
    fleet = [(30, 40, 85), (10, 5, 12), (60, 80, 45), (-70, 20, 8), (0, 15, 96)]
    drifting, vectors, commands = navigate(fleet)
    print("drifting: %s" % (drifting,))
    print("return vectors: %s" % (vectors,))
    for command in commands:
        print(command)


if __name__ == "__main__":
    main()

