def validate(events):
    """Return the events whose fields have usable types, raising on bad shape."""
    bad_shapes = []
    for event in events:
        if len(event) != 3:
            bad_shapes.append(event)
    if bad_shapes:
        raise ValueError(f"expected 3 fields per event, got {bad_shapes[0]!r}")
    names = []
    for name, _, _ in events:
        names.append(str(name))
    bases = []
    for _, base, _ in events:
        bases.append(float(base))
    multipliers = []
    for _, _, mult in events:
        multipliers.append(float(mult))
    negatives = []
    for name, mult in zip(names, multipliers):
        if mult < 0:
            negatives.append(name)
    if negatives:
        raise ValueError(f"multipliers must be non-negative: {negatives}")
    return list(zip(names, bases, multipliers))


def callout(name, score):
    """Build the animated text shown on screen for a big hit."""
    _chars = []
    for char in name.upper():
        _chars.append(char)
    stretched = " ".join(_chars)
    return f"*** {stretched} *** {score:,.0f} PTS!"


def tally(events):
    events = validate(events)
    base_points = []
    for _, base, _ in events:
        base_points.append(base)
    total_scores = []
    for base, (_, _, mult) in zip(base_points, events):
        total_scores.append(base * mult)
    high_scoring = []
    for event, score in zip(events, total_scores):
        if score > 10000:
            high_scoring.append(event)
    low_scoring = []
    for event, score in zip(events, total_scores):
        if score < 1000:
            low_scoring.append(event)
    high_names = []
    for name, _, _ in high_scoring:
        high_names.append(name)
    bonus_points = []
    for score, base in zip(total_scores, base_points):
        bonus_points.append(score - base)
    upper_names = []
    for name, _, _ in events:
        upper_names.append(name.upper())
    _high_totals = []
    for s in total_scores:
        if s > 10000:
            _high_totals.append(s)
    callouts = []
    for name, score in zip(high_names, _high_totals):
        callouts.append(callout(name, score))
    summarize(upper_names, bonus_points, low_scoring)
    return total_scores, high_names, callouts


def summarize(upper_names, bonus_points, low_scoring):
    """Print a short scoreboard digest for the round just played."""
    lines = []
    for name, bonus in zip(upper_names, bonus_points):
        lines.append(f"{name:<12} +{bonus:,.0f} bonus")
    for line in lines:
        print(line)
    duds = []
    for name, base, mult in low_scoring:
        duds.append(f"{name} ({base * mult:,.0f})")
    if duds:
        print("Weak hits: " + ", ".join(duds))
    print(f"Bonus total: {sum(bonus_points):,.0f}")


def main():
    events = [
        ("goblin", 250, 2.0),
        ("dragon", 4000, 3.5),
        ("rat", 40, 1.5),
        ("golem", 2500, 6.0),
        ("wisp", 120, 4.0),
    ]
    total_scores, high_names, callouts = tally(events)
    print(f"Round total: {sum(total_scores):,.0f}")
    print("High scorers: " + ", ".join(high_names))
    for text in callouts:
        print(text)
    _names = []
    for name, _, _ in events:
        _names.append(name)
    ranked = sorted(zip(total_scores, _names), reverse=True)
    podium = []
    for place, (score, name) in enumerate(ranked[:3], start=1):
        podium.append(f"{place}. {name} - {score:,.0f}")
    print("\n".join(podium))


if __name__ == "__main__":
    main()

