def validate_pins(pins):
    """Reject malformed pin descriptions before any force is computed."""
    malformed = [i for i, pin in enumerate(pins) if len(pin) != 3]
    if malformed:
        raise ValueError("pins %s are not (length, tension, bound) triples" % malformed)
    negative = [i for i, pin in enumerate(pins) if pin[0] <= 0 or pin[1] < 0]
    if negative:
        raise ValueError("pins %s have a non-physical length or tension" % negative)


def lifting_force(length, tension):
    """Force needed to push a pin of the given length against its spring."""
    return round(length * 0.35 + tension * 1.4, 2)


def optimal_angle(tension):
    """Pick angle that lifts a bound pin without overshooting the shear line."""
    return round(max(5.0, 42.0 - tension * 3.5), 1)


def click_intensity(length, tension):
    """Tactile feedback felt when a pin drops onto the shear line."""
    return round(tension * 2.0 / length, 2)


def pick(pins):
    validate_pins(pins)
    lengths = [pin[0] for pin in pins]
    forces = [lifting_force(length, pin[1]) for length, pin in zip(lengths, pins)]

    bound_indices = [i for i, pin in enumerate(pins) if pin[2]]
    set_indices = [i for i, pin in enumerate(pins) if not pin[2]]
    bound_pins = [pins[i] for i in bound_indices]
    set_pins = [pins[i] for i in set_indices]

    bound_tensions = [pin[1] for pin in bound_pins]
    pick_angles = [optimal_angle(tension) for tension in bound_tensions]
    click_levels = [click_intensity(pin[0], pin[1]) for pin in set_pins]

    bound_steps = [
        "Step {0}: lift pin {1} with {2} N at {3} deg".format(
            order, index + 1, forces[index], angle)
        for order, (index, angle) in enumerate(zip(bound_indices, pick_angles), 1)
    ]
    set_steps = [
        "Step {0}: hold pin {1} at shear line, click {2}".format(
            order, index + 1, click)
        for order, (index, click) in enumerate(
            zip(set_indices, click_levels), len(bound_steps) + 1)
    ]
    unlocking_sequence = bound_steps + set_steps
    return bound_pins, set_pins, unlocking_sequence


def report(bound_pins, set_pins, unlocking_sequence):
    lines = ["Bound pins resisting rotation: %d" % len(bound_pins)]
    lines += ["  len=%s tension=%s" % (pin[0], pin[1]) for pin in bound_pins]
    lines.append("Set pins at the shear line: %d" % len(set_pins))
    lines += ["  len=%s tension=%s" % (pin[0], pin[1]) for pin in set_pins]
    lines.append("Unlocking sequence:")
    lines += ["  " + step for step in unlocking_sequence]
    return "\n".join(lines)


def main():
