        (4.1, 4.5, True),
        (7.5, 1.8, False),
        (5.9, 5.0, True),
    ]
    bound_pins, set_pins, unlocking_sequence = pick(lock)
    print(report(bound_pins, set_pins, unlocking_sequence))


if __name__ == "__main__":
    main()

