def validate(plants):
    """Return the observations that have the four expected fields."""
    bad = []
    for obs in plants:
        if len(obs) != 4:
            bad.append(obs)
    if bad:
        labels = []
        for obs in bad:
            labels.append(str(obs))
        raise ValueError("malformed observations: " + "; ".join(labels))
    return list(plants)


def analyze(plants):
    """Build the eight part ecological summary for a plant survey."""
    records = validate(plants)
    species = []
    for name, _alt, _petals, _acid in records:
        species.append(name)
    altitudes = []
    for _name, alt, _petals, _acid in records:
        altitudes.append(alt)
    high = []
    for obs in records:
        if obs[1] > 2000:
            high.append(obs)
    high_species = []
    for name, _alt, _petals, _acid in high:
        high_species.append(name)
    high_acidity = []
    for _name, _alt, _petals, acid in high:
        high_acidity.append(acid)
    normalized_acidity = []
    for acid in high_acidity:
        normalized_acidity.append(acid * 0.9)
    high_petals = []
    for _name, _alt, petals, _acid in high:
        high_petals.append(petals)
    seed_yield = []
    for petals in high_petals:
        seed_yield.append(petals * 3)
    labels = []
    for name in high_species:
        labels.append(name + " alpine")
    return (
        species,
        altitudes,
        high_species,
        high_acidity,
        normalized_acidity,
        high_petals,
        seed_yield,
        labels,
    )


def altitude_band(altitude):
    """Name the vegetation band a single altitude reading belongs to."""
    if altitude > 2000:
        return "alpine"
    if altitude > 1000:
        return "montane"
    return "lowland"


def band_counts(altitudes):
    """Count how many readings fall in each vegetation band."""
    bands = []
    for alt in altitudes:
        bands.append(altitude_band(alt))
    return {band: bands.count(band) for band in ("alpine", "montane", "lowland")}


def format_report(summary):
    """Render the summary tuple as a short human readable report."""
    species, altitudes, _high, _acid, norm, petals, yields, labels = summary
    counts = band_counts(altitudes)
    lines = ["Surveyed species: " + ", ".join(species)]
    lines.append("Band counts: " + ", ".join(
        "%s=%d" % (band, counts[band]) for band in sorted(counts)))
    detail = []
    for row in zip(labels, norm, petals, yields):
        detail.append("%s: acidity %.2f, petals %d, expected seeds %d" % row)
    lines.extend(detail)
    return "\n".join(lines)


