def validate(bolts):
    """Check that every bolt record has the expected four fields."""
    malformed = []
    for index, bolt in enumerate(bolts):
        if len(bolt) != 4:
            malformed.append(index)
    if malformed:
        raise ValueError("malformed bolt records at positions: %s" % malformed)
    negatives = []
    for bolt in bolts:
        if bolt[1] < 0 or bolt[3] < 0:
            negatives.append(bolt[0])
    if negatives:
        raise ValueError("negative length or defect count for: %s" % negatives)
    return bolts


def measure(bolts):
    """Split a list of bolt records into eight parallel report lists."""
    validate(bolts)
    patterns = []
    for bolt in bolts:
        patterns.append(bolt[0])
    defects = []
    for bolt in bolts:
        defects.append(bolt[3])
    premium = []
    for bolt in bolts:
        if bolt[3] < 3:
            premium.append(bolt)
    premium_patterns = []
    for bolt in premium:
        premium_patterns.append(bolt[0])
    premium_lengths = []
    for bolt in premium:
        premium_lengths.append(bolt[1])
    premium_inches = []
    for length in premium_lengths:
        premium_inches.append(length * 36)
    premium_threads = []
    for bolt in premium:
        premium_threads.append(bolt[2])
    durability = []
    for count in premium_threads:
        durability.append(count * 1.5)
    catalog = []
    for pattern in premium_patterns:
        catalog.append("%s premium stock" % pattern)
    return (patterns, defects, premium_patterns, premium_lengths,
            premium_inches, premium_threads, durability, catalog)


def rejected(patterns, defects):
    """Names of the bolts that did not reach premium grade."""
    result = []
    for pattern, count in zip(patterns, defects):
        if count >= 3:
            result.append(pattern)
    return result


def catalog_report(catalog, inches, durability):
    """One formatted line per premium bolt."""
    result = []
    for row in zip(catalog, inches, durability):
        result.append("%-28s %6d in  durability %7.1f" % row)
    return result


def yardage_total(lengths):
    return sum(lengths)


def main():
    bolts = [
        ("houndstooth", 10, 200, 1),
        ("pinstripe", 14, 180, 4),
        ("tartan", 8, 220, 0),
        ("herringbone", 12, 260, 2),
        ("gingham", 6, 150, 5),
    ]
    (patterns, defects, premium_patterns, premium_lengths,
     premium_inches, premium_threads, durability, catalog) = measure(bolts)

    print("inspected %d bolts: %s" % (len(patterns), ", ".join(patterns)))
    print("defect counts: %s" % defects)
    print("premium grade: %s" % ", ".join(premium_patterns))
    print("premium yardage: %d yd" % yardage_total(premium_lengths))
    print("thread counts: %s" % premium_threads)
    for line in catalog_report(catalog, premium_inches, durability):
        print(line)

    downgraded = rejected(patterns, defects)
    print("held back: %s" % ", ".join(downgraded))
    strongest = []
    for pattern, score in zip(premium_patterns, durability):
        if score >= 300:
            strongest.append(pattern)
    print("reinforced stock: %s" % ", ".join(strongest))
    print("full catalog: %s" % catalog)


