def validate(tubes):
    """Return the tubes whose fields have usable types, raising on bad input."""
    bad = []
    for t in tubes:
        if len(t) != 4:
            bad.append(t)
    if bad:
        raise ValueError("each tube needs (name, volume, pressure, leakage): %r" % (bad,))
    negatives = []
    for t in tubes:
        if t[1] < 0 or t[2] < 0 or t[3] < 0:
            negatives.append(t[0])
    if negatives:
        raise ValueError("negative readings for: %s" % ", ".join(negatives))
    ret = []
    for name, vol, pres, leak in tubes:
        ret.append((str(name), float(vol), float(pres), float(leak)))
    return ret


def mix(tubes):
    """Split the tube data into the eight formulation sequences."""
    names = []
    for tube in tubes:
        names.append(tube[0])
    leakages = []
    for tube in tubes:
        leakages.append(tube[3])
    sealed = []
    for tube in tubes:
        if tube[3] == 0:
            sealed.append(tube)
    sealed_names = []
    for tube in sealed:
        sealed_names.append(tube[0])
    sealed_volumes = []
    for tube in sealed:
        sealed_volumes.append(tube[1])
    charges = []
    for volume in sealed_volumes:
        charges.append(volume * 12)
    sealed_pressures = []
    for tube in sealed:
        sealed_pressures.append(tube[2])
    normalized = []
    for pressure in sealed_pressures:
        normalized.append(pressure / 1.05)
    tags = []
    for name in sealed_names:
        tags.append(name + " ready")
    return (names, leakages, sealed_names, sealed_volumes,
            charges, sealed_pressures, normalized, tags)


def leaking_report(names, leakages):
    """Describe every tube that still loses gas, worst offender first."""
    faults = []
    for name, rate in zip(names, leakages):
        if rate > 0:
            faults.append((name, rate))
    faults.sort(key=lambda pair: pair[1], reverse=True)
    ret = []
    for name, rate in faults:
        ret.append("%s leaks %.2f ml/min" % (name, rate))
    return ret


def batch_sheet(tags, charges, normalized):
    """Build one printable line per sealed tube."""
    rows = zip(tags, charges, normalized)
    ret = []
    for row in rows:
        ret.append("%-16s charge=%8.1f C  pressure=%7.2f kPa" % row)
    return ret


def summarize(tubes):
    """Run the formulation and render a small text report."""
    clean = validate(tubes)
    (names, leakages, sealed_names, sealed_volumes,
     charges, sealed_pressures, normalized, tags) = mix(clean)
    lines = ["Tubes received: %d" % len(names),
             "Sealed tubes: %s" % (", ".join(sealed_names) or "none")]
    lines.extend(batch_sheet(tags, charges, normalized))
    lines.extend(leaking_report(names, leakages))
    total_volume = sum(sealed_volumes)
    lines.append("Sealed volume: %.1f ml over %d readings" % (total_volume, len(sealed_pressures)))
    return lines


def main():
    tubes = [
        ("argon", 50, 100, 0),
        ("neon", 30, 95.5, 0.4),
        ("krypton", 12.5, 80, 0),
        ("xenon", 5, 60.25, 1.75),
        ("radon", 2, 44, 0),
    ]
    for line in summarize(tubes):
        print(line)
    result = mix(validate(tubes))
    labels = ["names", "leakages", "sealed_names", "sealed_volumes",
              "charges", "sealed_pressures", "normalized_pressures", "tags"]
    for label, sequence in zip(labels, result):
        print("%s: %s" % (label, sequence))


if __name__ == "__main__":
    main()

