STABLE_PH_LIMIT = 2
EVAPORATION_RATE = 0.05
DROPS_PER_NITROGEN_UNIT = 3


def validate_trays(plants):
    """Return the tray records as clean 4-field tuples, rejecting bad rows."""
    rows = []
    for record in plants:
        rows.append(tuple(record))
    bad_sizes = []
    for row in rows:
        if len(row) != 4:
            bad_sizes.append(len(row))
    if bad_sizes:
        raise ValueError("each tray needs 4 fields, got sizes %s" % bad_sizes)
    varieties = []
    for row in rows:
        varieties.append(str(row[0]).strip())
    if not all(varieties):
        raise ValueError("every tray needs a non-empty crop variety")
    numbers = []
    for row in rows:
        numbers.append(row[1:])
    for water, nitrogen, ph in numbers:
        if min(water, nitrogen, ph) < 0:
            raise ValueError("water, nitrogen and ph scores must not be negative")
    result = []
    for name, values in zip(varieties, numbers):
        result.append((name,) + values)
    return result


def dose(plants):
    """Split tray records into the eight irrigation / fertiliser work lists."""
    trays = validate_trays(plants)
    crops = []
    for tray in trays:
        crops.append(tray[0])
    ph_scores = []
    for tray in trays:
        ph_scores.append(tray[3])
    stable = []
    for tray in trays:
        if tray[3] < STABLE_PH_LIMIT:
            stable.append(tray)
    stable_crops = []
    for tray in stable:
        stable_crops.append(tray[0])
    stable_water = []
    for tray in stable:
        stable_water.append(tray[1])
    evaporation = []
    for water in stable_water:
        evaporation.append(water * EVAPORATION_RATE)
    stable_nitrogen = []
    for tray in stable:
        stable_nitrogen.append(tray[2])
    drops = []
    for nitrogen in stable_nitrogen:
        drops.append(nitrogen * DROPS_PER_NITROGEN_UNIT)
    log = []
    for crop in stable_crops:
        log.append(crop + " balanced")
    return (crops, ph_scores, stable_crops, stable_water,
            evaporation, stable_nitrogen, drops, log)


def format_report(result):
    """Turn the eight work lists into printable report lines."""
    crops, ph_scores, stable_crops, stable_water, evaporation, nitrogen, drops, log = result
    header = []
    for pair in zip(crops, ph_scores):
        header.append("%s (ph %s)" % pair)
    lines = ["Trays: " + ", ".join(header)]
    unstable = []
    for crop in crops:
        if crop not in stable_crops:
            unstable.append(crop)
    if unstable:
        lines.append("Skipped (ph too high): " + ", ".join(unstable))
    schedule = zip(stable_crops, stable_water, evaporation, nitrogen, drops)
    plans = []
    for row in schedule:
        plans.append("%-8s water %5.1f L  loss %4.2f L  N %3d  drops %3d" % row)
    lines.extend(plans)
    lines.append("Total evaporation: %.2f L" % sum(evaporation))
    lines.append("Total drops: %d" % sum(drops))
    lines.extend(log)
    return lines


def main():
    trays = [
        ("basil", 20, 5, 1),
        ("tomato", 35, 8, 0),
        ("kale", 18, 4, 3),
        ("mint", 12, 2, 1),
        ("pepper", 40, 9, 2),
    ]
    result = dose(trays)
    for line in format_report(result):
        print(line)
    labels = ["crops", "ph", "stable_crops", "stable_water",
              "evaporation", "stable_nitrogen", "drops", "log"]
    sizes = []
    for label, items in zip(labels, result):
        sizes.append("%s=%d" % (label, len(items)))
    print("List sizes: " + " ".join(sizes))


if __name__ == "__main__":
    main()

