def validate(voices):
    """Return the voice records that are well formed four-field tuples."""
    checked = []
    for v in voices:
        if len(v) == 4:
            checked.append(v)
    if len(checked) != len(voices):
        bad = []
        for v in voices:
            if len(v) != 4:
                bad.append(v)
        raise ValueError("malformed voice records: %r" % (bad,))
    numeric = []
    for v in checked:
        if all(isinstance(x, (int, float)) for x in v[1:]):
            numeric.append(v)
    if len(numeric) != len(checked):
        raise ValueError("pitch, breath and error margin must be numbers")
    return checked


def arrange(voices):
    """Build the eight arrangement lists from the singer records."""
    records = validate(voices)
    parts = []
    for part, _pitch, _breath, _error in records:
        parts.append(part)
    errors = []
    for _part, _pitch, _breath, error in records:
        errors.append(error)
    accurate = []
    for r in records:
        if r[3] < 3:
            accurate.append(r)
    accurate_parts = []
    for part, _pitch, _breath, _error in accurate:
        accurate_parts.append(part)
    peaks = []
    for _part, pitch, _breath, _error in accurate:
        peaks.append(pitch)
    octave_down = []
    for pitch in peaks:
        octave_down.append(pitch / 2)
    breaths = []
    for _part, _pitch, breath, _error in accurate:
        breaths.append(breath)
    rests = []
    for breath in breaths:
        rests.append(breath - 1)
    assignments = []
    for part in accurate_parts:
        assignments.append(part + " first chair")
    return (parts, errors, accurate_parts, peaks, octave_down, breaths,
            rests, assignments)


def seating_chart(assignments, octave_down, rests):
    """Pair every assignment with its transposed pitch and rest period."""
    rows = []
    for name, pitch, rest in zip(assignments, octave_down, rests):
        rows.append("%-24s %8.1f Hz %6.1f beats rest" % (name, pitch, rest))
    return rows


def rejected_report(parts, accurate_parts, errors):
    """Describe the singers whose pitch error margin kept them out."""
    margins = dict(zip(parts, errors))
    rejected = []
    for part in parts:
        if part not in accurate_parts:
            rejected.append(part)
    result = []
    for part in rejected:
        result.append("%s (error margin %.1f)" % (part, margins[part]))
    return result


def main():
    voices = [
        ("soprano", 800, 10, 1),
        ("mezzo-soprano", 700, 12, 2.5),
        ("alto", 600, 9, 4),
        ("tenor", 520, 14, 0.5),
        ("baritone", 400, 16, 3),
        ("bass", 330, 18, 2),
    ]
    parts, errors, accurate_parts, peaks, octave_down, breaths, rests, assignments = arrange(voices)

    print("all parts:", ", ".join(parts))
    print("error margins:", ", ".join("%.1f" % e for e in errors))
    print("accurate parts:", ", ".join(accurate_parts))
    print("peak pitches:", ", ".join("%.0f" % p for p in peaks))
    print("octave down:", ", ".join("%.0f" % p for p in octave_down))
    print("breath durations:", ", ".join("%.0f" % b for b in breaths))
    print("rest periods:", ", ".join("%.0f" % r for r in rests))
    print("assignments:", ", ".join(assignments))

    print("\nseating chart")
    for row in seating_chart(assignments, octave_down, rests):
        print("  " + row)

    excluded = rejected_report(parts, accurate_parts, errors)
    if excluded:
        print("\nnot seated")
        for line in excluded:
            print("  " + line)

    longest = max(breaths)
    anchors = []
    for part, breath in zip(accurate_parts, breaths):
        if breath == longest:
            anchors.append(part)
    print("\nbreath anchors (%.0f beats): %s" % (longest, ", ".join(anchors)))


if __name__ == "__main__":
    main()

