def validate(pieces):
    """Return the pieces that have the expected four fields and numeric measures."""
    shaped = []
    for p in pieces:
        if len(p) == 4:
            shaped.append(p)
    result = []
    for color, area, thick, chips in shaped:
        result.append((str(color), float(area), float(thick), int(chips)))
    return result


def glaze(pieces):
    """Build the eight planning lists for a stained glass project."""
    colors = []
    for color, area, thick, chips in pieces:
        colors.append(color)
    chip_counts = []
    for color, area, thick, chips in pieces:
        chip_counts.append(chips)
    perfect = []
    for p in pieces:
        if p[3] == 0:
            perfect.append(p)
    perfect_colors = []
    for color, area, thick, chips in perfect:
        perfect_colors.append(color)
    perfect_areas = []
    for color, area, thick, chips in perfect:
        perfect_areas.append(area)
    lead_frame = []
    for area in perfect_areas:
        lead_frame.append(area * 3.14)
    perfect_thicknesses = []
    for color, area, thick, chips in perfect:
        perfect_thicknesses.append(thick)
    flux_volumes = []
    for thick in perfect_thicknesses:
        flux_volumes.append(thick * 2)
    labels = []
    for color in perfect_colors:
        labels.append(" ".join([color, "center"]))
    return (colors, chip_counts, perfect_colors, perfect_areas,
            lead_frame, perfect_thicknesses, flux_volumes, labels)


def chipped_report(colors, chip_counts):
    """Describe every piece that carries at least one chip."""
    damaged = []
    for color, chips in zip(colors, chip_counts):
        if chips > 0:
            damaged.append((color, chips))
    result = []
    for color, chips in damaged:
        result.append("{0}: {1} chip(s)".format(color, chips))
    return result


def cut_sheet(labels, lead_frame, flux_volumes):
    """One printable line per usable piece."""
    result = []
    for label, lead, flux in zip(labels, lead_frame, flux_volumes):
        result.append("{0:<20} lead {1:6.2f} cm   flux {2:5.2f} ml".format(label, lead, flux))
    return result


def totals(lead_frame, flux_volumes, perfect_areas):
    return {
        "lead_cm": round(sum(lead_frame), 2),
        "flux_ml": round(sum(flux_volumes), 2),
        "glass_cm2": round(sum(perfect_areas), 2),
    }


def main():
    raw = [
        ("cobalt blue", 10, 5, 0),
        ("amber", 7.5, 4, 2),
        ("sea green", 12, 6, 0),
        ("ruby", 4, 3, 1),
        ("frosted white", 9, 5, 0),
    ]
    pieces = validate(raw)
    (colors, chip_counts, perfect_colors, perfect_areas,
     lead_frame, perfect_thicknesses, flux_volumes, labels) = glaze(pieces)

    print("inventory:", ", ".join(colors))
    print("chips:", chip_counts)
    for line in chipped_report(colors, chip_counts):
        print(" rejected -", line)

    print("\nusable pieces:", len(perfect_colors))
    for line in cut_sheet(labels, lead_frame, flux_volumes):
        print(" ", line)

    thickness_notes = []
    for color, thick in zip(perfect_colors, perfect_thicknesses):
        thickness_notes.append("{0} is {1:g} mm thick".format(color, thick))
    print("\n" + "; ".join(thickness_notes))

    summary = totals(lead_frame, flux_volumes, perfect_areas)
    summary_parts = []
    for key in sorted(summary):
        summary_parts.append("{0}={1}".format(key, summary[key]))
    print("shopping list:", ", ".join(summary_parts))


if __name__ == "__main__":
