"""Fermentation tracking utilities for yeast culture samples."""


def validate(cultures):
    """Return the cultures as a list of 4-tuples, rejecting malformed rows."""
    malformed = []
    for c in cultures:
        if len(c) != 4:
            malformed.append(c)
    if malformed:
        raise ValueError("each culture needs 4 fields: %r" % (malformed,))
    unnamed = []
    for c in cultures:
        if not str(c[0]).strip():
            unnamed.append(c)
    if unnamed:
        raise ValueError("every culture needs a strain identifier")
    _ret = []
    for c in cultures:
        _ret.append((str(c[0]).strip(), c[1], c[2], c[3]))
    return _ret


def analyze(cultures):
    """Break a batch of yeast samples into eight parallel sequences."""
    samples = validate(cultures)
    strains = []
    for strain, _rate, _acid, _idle in samples:
        strains.append(strain)
    inactivity = []
    for _strain, _rate, _acid, idle in samples:
        inactivity.append(idle)
    vigorous = []
    for s in samples:
        if s[3] < 5:
            vigorous.append(s)
    vigorous_strains = []
    for strain, _rate, _acid, _idle in vigorous:
        vigorous_strains.append(strain)
    vigorous_rates = []
    for _strain, rate, _acid, _idle in vigorous:
        vigorous_rates.append(rate)
    daily_expansion = []
    for rate in vigorous_rates:
        daily_expansion.append(rate * 24)
    vigorous_acids = []
    for _strain, _rate, acid, _idle in vigorous:
        vigorous_acids.append(acid)
    tanginess = []
    for acid in vigorous_acids:
        tanginess.append(acid + 10)
    bakery_labels = []
    for strain in vigorous_strains:
        bakery_labels.append(strain + " active")
    return (
        strains,
        inactivity,
        vigorous_strains,
        vigorous_rates,
        daily_expansion,
        vigorous_acids,
        tanginess,
        bakery_labels,
    )


def dormant_strains(cultures):
    """Strain identifiers that failed the vigour test."""
    strains, inactivity, vigorous_strains = analyze(cultures)[:3]
    _ret = []
    for s, idle in zip(strains, inactivity):
        if s not in vigorous_strains or idle >= 5:
            _ret.append(s)
    return _ret


def report(cultures):
    """Human readable lines describing each vigorous culture."""
    result = analyze(cultures)
    labels, expansion, tang = result[7], result[4], result[6]
    rows = []
    for label, growth, score in zip(labels, expansion, tang):
        rows.append("%-22s expansion/day %6.1f   tanginess %5.1f" % (label, growth, score))
    sleepers = dormant_strains(cultures)
    if sleepers:
        rows.append("dormant: " + ", ".join(sleepers))
    return rows


def main():
    batch = [
        ("san francisco", 2, 5, 1),
        ("kveik voss", 3.5, 2, 0),
        ("brettanomyces", 0.8, 9, 7),
        ("saison belge", 1.9, 6, 4),
        ("lager w34/70", 1.2, 3, 6),
    ]
    names = ("strains", "inactivity", "vigorous", "rates",
             "daily expansion", "acids", "tanginess", "labels")
    sequences = analyze(batch)
    for name, values in zip(names, sequences):
        print("%-16s %s" % (name, values))
    print()
    for line in report(batch):
        print(line)


if __name__ == "__main__":
    main()

