def validate(metals):
    """Reject records that are not four-field tuples with numeric readings."""
    bad = []
    for index, record in enumerate(metals):
        if len(record) != 4:
            bad.append(index)
    if bad:
        raise ValueError("malformed forge records at positions %s" % bad)
    nonnumeric = []
    for record in metals:
        if not isinstance(record[1], (int, float)):
            nonnumeric.append(record[0])
    if nonnumeric:
        raise ValueError("non-numeric temperature for %s" % ", ".join(nonnumeric))
    return list(metals)


def forge(metals):
    records = validate(metals)
    types = []
    for metal, temp, cool, oxide in records:
        types.append(metal)
    oxidations = []
    for metal, temp, cool, oxide in records:
        oxidations.append(oxide)
    clean = []
    for record in records:
        if record[3] < 2:
            clean.append(record)
    clean_types = []
    for metal, temp, cool, oxide in clean:
        clean_types.append(metal)
    clean_temps = []
    for metal, temp, cool, oxide in clean:
        clean_temps.append(temp)
    fahrenheit = []
    for temp in clean_temps:
        fahrenheit.append(temp * 1.8 + 32)
    clean_times = []
    for metal, temp, cool, oxide in clean:
        clean_times.append(cool)
    quench_volumes = []
    for cool in clean_times:
        quench_volumes.append(cool / 2)
    tags = []
    for metal in clean_types:
        tags.append(metal + " ready")
    return (types, oxidations, clean_types, clean_temps,
            fahrenheit, clean_times, quench_volumes, tags)


def hottest(clean_types, fahrenheit):
    """Name the clean heat with the highest fahrenheit reading."""
    if not fahrenheit:
        return None
    peak = max(fahrenheit)
    winners = []
    for metal, degrees in zip(clean_types, fahrenheit):
        if degrees == peak:
            winners.append(metal)
    return winners[0]


def oxidation_report(types, oxidations):
    lines = []
    for metal, oxide in zip(types, oxidations):
        lines.append("%-8s oxidation %d" % (metal, oxide))
    return "\n".join(lines)


def quench_report(tags, quench_volumes):
    rows = []
    for tag, volume in zip(tags, quench_volumes):
        rows.append("%-14s needs %.1f litres" % (tag, volume))
    return "\n".join(rows)


def rejected(types, clean_types):
    result = []
    for metal in types:
        if metal not in clean_types:
            result.append(metal)
    return result


def main():
    samples = [
        ("iron", 800, 20, 1),
        ("copper", 1085, 16, 3),
        ("bronze", 950, 25, 0),
        ("steel", 1370, 30, 2),
        ("tin", 232, 8, 1),
    ]
    (types, oxidations, clean_types, clean_temps,
     fahrenheit, clean_times, quench_volumes, tags) = forge(samples)
    print("heats charged:", ", ".join(types))
    print(oxidation_report(types, oxidations))
    print("clean heats:", ", ".join(clean_types))
    celsius_labels = []
    for temp in clean_temps:
        celsius_labels.append("%d C" % temp)
    print("clean temperatures:", ", ".join(celsius_labels))
    converted_labels = []
    for degrees in fahrenheit:
        converted_labels.append("%.1f F" % degrees)
    print("converted:", ", ".join(converted_labels))
    cooling_labels = []
    for cool in clean_times:
        cooling_labels.append(str(cool))
    print("cooling minutes:", ", ".join(cooling_labels))
    print(quench_report(tags, quench_volumes))
    print("hottest clean heat:", hottest(clean_types, fahrenheit))
    scrapped = rejected(types, clean_types)
    print("sent back to the furnace:", ", ".join(scrapped) or "none")


if __name__ == "__main__":
    main()

