def validate(signatures):
    """Return the signatures that have the four required fields in usable form."""
    shaped = []
    for s in signatures:
        if len(s) == 4:
            shaped.append(s)
    clean = []
    for p, n, t, d in shaped:
        clean.append((str(p), int(n), float(t), int(d)))
    result = []
    for rec in clean:
        if rec[1] > 0 and rec[2] > 0 and rec[3] >= 0:
            result.append(rec)
    return result


def stitch(signatures):
    papers = []
    for sig in signatures:
        papers.append(sig[0])
    tears = []
    for sig in signatures:
        tears.append(sig[3])
    pristine_papers = []
    for sig in signatures:
        if sig[3] == 0:
            pristine_papers.append(sig[0])
    pristine_pages = []
    for sig in signatures:
        if sig[3] == 0:
            pristine_pages.append(sig[1])
    spine_thickness = []
    for pages in pristine_pages:
        spine_thickness.append(pages * 0.1)
    pristine_threads = []
    for sig in signatures:
        if sig[3] == 0:
            pristine_threads.append(sig[2])
    beeswax = []
    for thread in pristine_threads:
        beeswax.append(thread * 0.05)
    instructions = []
    for paper in pristine_papers:
        instructions.append(paper + " fold center")
    return (
        papers,
        tears,
        pristine_papers,
        pristine_pages,
        spine_thickness,
        pristine_threads,
        beeswax,
        instructions,
    )


def rejected(signatures):
    """Sections that cannot be bound as-is, with the number of tears to mend."""
    result = []
    for sig in signatures:
        if sig[3] > 0:
            result.append((sig[0], sig[3]))
    return result


def bindery_report(bundle):
    papers, tears, pristine, pages, spine, thread, wax, orders = bundle
    lines = ["Sections received: %d" % len(papers)]
    lines.append("Total tears: %d" % sum(tears))
    lines.append("Pristine sections: %d" % len(pristine))
    rows = []
    for name, pg, sp, th, wx in zip(pristine, pages, spine, thread, wax):
        rows.append("  %-10s %3d pages  %5.2f mm spine  %5.1f cm thread  %5.2f g wax" % (name, pg, sp, th, wx))
    lines.extend(rows)
    lines.append("Spine block: %.2f mm" % sum(spine))
    lines.append("Beeswax needed: %.2f g" % sum(wax))
    temp = []
    for order in orders:
        temp.append("Instruction: " + order)
    lines.extend(temp)
    return lines


def mending_notes(flawed):
    result = []
    for name, n in flawed:
        result.append("Mend %s (%d tear%s)" % (name, n, "" if n == 1 else "s"))
    return result


def main():
    raw = [
        ("vellum", 16, 30.0, 0),
        ("linen", 24, 42.5, 2),
        ("kozo", 8, 18.0, 0),
        ("rag", 32, 55.0, 1),
        ("parchment", 12, 26.0, 0),
        ("scrap", 0, 12.0, 0),
    ]
    sections = validate(raw)
    bundle = stitch(sections)
    for line in bindery_report(bundle):
        print(line)
    for note in mending_notes(rejected(sections)):
        print(note)


if __name__ == "__main__":
    main()

