def check_events(events):
    """Reject malformed seismic records before any analysis is attempted."""
    wrong_shape = []
    for i, event in enumerate(events):
        if len(event) != 4:
            wrong_shape.append(i)
    if wrong_shape:
        raise ValueError("records with wrong field count at rows: %s" % wrong_shape)
    bad_location = []
    for i, event in enumerate(events):
        if not isinstance(event[0], str):
            bad_location.append(i)
    if bad_location:
        raise ValueError("non-textual location at rows: %s" % bad_location)
    bad_numbers = []
    for i, event in enumerate(events):
        if not all(isinstance(value, (int, float)) for value in event[1:]):
            bad_numbers.append(i)
    if bad_numbers:
        raise ValueError("non-numeric measurements at rows: %s" % bad_numbers)
    negative = []
    for event in events:
        if event[1] < 0 or event[2] <= 0:
            negative.append(event[0])
    if negative:
        raise ValueError("impossible amplitude or duration at: %s" % negative)
    return len(events)


def validate(events):
    locations = []
    for event in events:
        locations.append(event[0])
    noise_levels = []
    for event in events:
        noise_levels.append(event[3])
    clear_signals = []
    for event in events:
        if event[3] < 10:
            clear_signals.append(event)
    clear_locations = []
    for event in clear_signals:
        clear_locations.append(event[0])
    clear_amplitudes = []
    for event in clear_signals:
        clear_amplitudes.append(event[1])
    energy_release = []
    for amplitude in clear_amplitudes:
        energy_release.append(amplitude ** 2)
    clear_durations = []
    for event in clear_signals:
        clear_durations.append(event[2])
    extended_monitoring = []
    for duration in clear_durations:
        extended_monitoring.append(duration + 60)
    log_entries = []
    for location in clear_locations:
        log_entries.append(location + " confirmed event")
    return (locations, noise_levels, clear_locations, clear_amplitudes,
            energy_release, clear_durations, extended_monitoring, log_entries)


def discarded_locations(locations, noise_levels):
    """Locations whose interference level keeps them out of the clear set."""
    result = []
    for location, noise in zip(locations, noise_levels):
        if noise >= 10:
            result.append(location)
    return result


def energy_ranking(clear_locations, energy_release):
    paired = []
    for location, energy in zip(clear_locations, energy_release):
        paired.append((energy, location))
    paired.sort(reverse=True)
    result = []
    for energy, location in paired:
        result.append((location, energy))
    return result


def format_report(report):
    (locations, noise_levels, clear_locations, clear_amplitudes,
     energy_release, clear_durations, extended_monitoring, log_entries) = report
    lines = ["stations scanned: %d, clear signals: %d" % (len(locations), len(clear_locations))]
    detail = zip(log_entries, clear_amplitudes, energy_release, clear_durations, extended_monitoring)
    lines.extend("%-34s amp=%-6s energy=%-8s %ss -> %ss watch" % row for row in detail)
    ignored = discarded_locations(locations, noise_levels)
    if ignored:
        lines.append("suppressed by interference: " + ", ".join(ignored))
    ranking = energy_ranking(clear_locations, energy_release)
    rank_lines = []
    for i, (name, value) in enumerate(ranking):
        rank_lines.append("rank %d: %s (%s)" % (i + 1, name, value))
    lines.extend(rank_lines)
    return "\n".join(lines)


