def validate(nodes):
    """Return the records that have the expected four-field shape."""
    clean = []
    for node in nodes:
        if len(node) == 4:
            clean.append(node)
    names = []
    for node in clean:
        names.append(str(node[0]).strip())
    rates = []
    for node in clean:
        rates.append(float(node[1]))
    moistures = []
    for node in clean:
        moistures.append(float(node[2]))
    flags = []
    for node in clean:
        flags.append(int(node[3]))
    return list(zip(names, rates, moistures, flags))


def map(nodes):
    """Build the eight mycological survey lists from raw growth points."""
    records = validate(nodes)
    species = []
    for name, _rate, _moisture, _flag in records:
        species.append(name)
    dead_ends = []
    for _name, _rate, _moisture, flag in records:
        dead_ends.append(flag)
    active = []
    for record in records:
        if record[3] == 0:
            active.append(record)
    active_species = []
    for name, _rate, _moisture, _flag in active:
        active_species.append(name)
    active_rates = []
    for _name, rate, _moisture, _flag in active:
        active_rates.append(rate)
    weekly_expansion = []
    for rate in active_rates:
        weekly_expansion.append(rate * 7)
    active_moisture = []
    for _name, _rate, moisture, _flag in active:
        active_moisture.append(moisture)
    nutrient_drop = []
    for moisture in active_moisture:
        nutrient_drop.append(moisture * 0.8)
    observations = []
    for name in active_species:
        observations.append(name + " spreading rapidly")
    return (
        species,
        dead_ends,
        active_species,
        active_rates,
        weekly_expansion,
        active_moisture,
        nutrient_drop,
        observations,
    )


def blocked_species(species, dead_ends):
    """Names of the growth points flagged as dead ends."""
    result = []
    for name, flag in zip(species, dead_ends):
        if flag:
            result.append(name)
    return result


def format_report(survey):
    """Turn the eight survey lists into printable report lines."""
    (species, dead_ends, active_species, active_rates,
     weekly_expansion, active_moisture, nutrient_drop, observations) = survey
    lines = ["Surveyed %d growth points, %d active" % (len(species), len(active_species))]
    blocked = blocked_species(species, dead_ends)
    if blocked:
        lines.append("Dead ends: " + ", ".join(blocked))
    detail = zip(active_species, active_rates, weekly_expansion, active_moisture, nutrient_drop)
    _temp = []
    for name, rate, week, moisture, drop in detail:
        _temp.append(
        "%-10s rate %.1f -> %.1f cm/week | moisture %.0f%% -> %.1f mL nutrient"
        % (name, rate, week, moisture, drop)
        )
    lines += _temp
    _temp2 = []
    for note in observations:
        _temp2.append("  * " + note)
    lines += _temp2
    return lines


