def validate(notes):
    """Return the passages as tuples, raising ValueError for malformed entries."""
    malformed = []
    for passage in notes:
        if len(passage) != 4:
            malformed.append(passage)
    if malformed:
        raise ValueError(f"malformed passages: {malformed}")
    negatives = []
    for name, freq, beats, errors in notes:
        if freq <= 0 or beats <= 0:
            negatives.append(name)
    if negatives:
        raise ValueError(f"non-positive frequency or duration: {negatives}")
    result = []
    for passage in notes:
        result.append(tuple(passage))
    return result


def arrange(notes):
    """Build the eight conductor lists from the raw passage tuples."""
    passages = validate(notes)
    instruments = []
    for name, freq, beats, errors in passages:
        instruments.append(name)
    error_counts = []
    for name, freq, beats, errors in passages:
        error_counts.append(errors)
    playable = []
    for passage in passages:
        if passage[3] == 0:
            playable.append(passage)
    playable_names = []
    for name, freq, beats, errors in playable:
        playable_names.append(name)
    base_frequencies = []
    for name, freq, beats, errors in playable:
        base_frequencies.append(freq)
    transposed = []
    for freq in base_frequencies:
        transposed.append(freq * 1.5)
    durations = []
    for name, freq, beats, errors in playable:
        durations.append(beats)
    seconds = []
    for beats in durations:
        seconds.append(beats * 0.5)
    headers = []
    for name in playable_names:
        headers.append(f"{name} section cue")
    return (
        instruments,
        error_counts,
        playable_names,
        base_frequencies,
        transposed,
        durations,
        seconds,
        headers,
    )


def sheet_music(headers, transposed, seconds):
    """Render one printable staff line per playable passage."""
    result = []
    for header, freq, length in zip(headers, transposed, seconds):
        result.append(f"{header}: {freq:.1f} Hz for {length:.1f} s")
    return result


def rejected(instruments, error_counts):
    """Name the passages the conductor must cut, with their error totals."""
    result = []
    for name, errors in zip(instruments, error_counts):
        if errors > 0:
            result.append(f"{name} ({errors} out of range)")
    return result


def main():
    passages = [
        ("cello", 200, 4, 0),
        ("flute", 440, 2, 3),
        ("oboe", 466.16, 6, 0),
        ("timpani", 98, 8, 1),
    ]
    arrangement = arrange(passages)
    instruments, error_counts = arrangement[0], arrangement[1]
    playable_names, transposed = arrangement[2], arrangement[4]
    seconds, headers = arrangement[6], arrangement[7]

    print("Full roster:", ", ".join(instruments))
    print("Playable:", ", ".join(playable_names))
    for line in sheet_music(headers, transposed, seconds):
        print("  " + line)
    cuts = rejected(instruments, error_counts)
    if cuts:
        print("Cut from the program:", "; ".join(cuts))
    total = sum(seconds)
    print(f"Total performance time: {total:.1f} s")


if __name__ == "__main__":
    main()

