def is_prime(n):
    """Return True if the positive integer n is prime."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n < 4:
        return n > 1
    if n % 2 == 0:
        return False
    divisors = [d for d in range(3, int(n ** 0.5) + 1, 2) if n % d == 0]
    return not divisors


def primes_up_to(limit):
    """Return every prime p with p <= limit, using a sieve of Eratosthenes."""
    if limit < 2:
        return []
    flags = [True] * (limit + 1)
    flags[0] = flags[1] = False
    for base in range(2, int(limit ** 0.5) + 1):
        if flags[base]:
            for multiple in range(base * base, limit + 1, base):
                flags[multiple] = False
    return [value for value, prime in enumerate(flags) if prime]


def prime_factors(n):
    """Return the prime factors of n in non-decreasing order."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    factors = []
    remaining = n
    divisor = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            factors.append(divisor)
            remaining //= divisor
        divisor += 1 if divisor == 2 else 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def twin_prime_pairs(limit):
    """Return pairs (p, p + 2) where both members are prime and p + 2 <= limit."""
    primes = set(primes_up_to(limit))
    return [(p, p + 2) for p in sorted(primes) if p + 2 in primes]


def factor_expression(n):
    """Render n as a product of primes, e.g. 360 -> '2^3 * 3^2 * 5'."""
    factors = prime_factors(n)
    bases = sorted(set(factors))
    powers = [(base, factors.count(base)) for base in bases]
    terms = [str(base) if count == 1 else "{}^{}".format(base, count)
             for base, count in powers]
    return " * ".join(terms) if terms else "1"


def main():
    samples = [1, 2, 7, 10, 97, 360, 1001]
    verdicts = ["prime" if is_prime(value) else "composite" for value in samples]
    for value, verdict in zip(samples, verdicts):
        print("{:>5} is {:<9} = {}".format(value, verdict, factor_expression(value)))

    limit = 60
    print("Primes up to {}: {}".format(limit, primes_up_to(limit)))

    pairs = twin_prime_pairs(limit)
    rendered = ["({}, {})".format(low, high) for low, high in pairs]
    print("Twin primes up to {}: {}".format(limit, ", ".join(rendered)))

    gaps = [high - low for low, high in zip(primes_up_to(limit), primes_up_to(limit)[1:])]
    print("Largest gap between consecutive primes below {}: {}".format(limit, max(gaps)))


if __name__ == "__main__":
    main()

