"""Set-style operations on plain Python lists, preserving first-appearance order."""


def dedupe(items):
    """Return the items without repeats, keeping the order of first appearance."""
    unique = []
    for item in items:
        if item not in unique:
            unique.append(item)
    return unique


def list_intersection(list1, list2):
    """Return the elements of list1 that also appear in list2, without repeats."""
    return dedupe([item for item in list1 if item in list2])


def list_difference(list1, list2):
    """Return the elements present in list1 but missing from list2."""
    return dedupe([item for item in list1 if item not in list2])


def list_union(list1, list2):
    """Return every element of both lists, keeping first-appearance order."""
    return dedupe(list1 + list2)


def symmetric_difference(list1, list2):
    """Return the elements that belong to exactly one of the two lists."""
    return list_difference(list1, list2) + list_difference(list2, list1)


def jaccard_index(list1, list2):
    """Return the intersection size divided by the union size."""
    union = list_union(list1, list2)
    if not union:
        return 1.0
    return len(list_intersection(list1, list2)) / len(union)


def format_list(items):
    """Render a list of values as a compact, readable string."""
    return "[" + ", ".join([repr(item) for item in items]) + "]"


def describe_pair(list1, list2):
    """Build the report lines comparing two lists."""
    operations = [
        ("intersection", list_intersection(list1, list2)),
        ("union", list_union(list1, list2)),
        ("only in first", list_difference(list1, list2)),
        ("only in second", list_difference(list2, list1)),
        ("symmetric difference", symmetric_difference(list1, list2)),
    ]
    lines = [" vs ".join([format_list(items) for items in (list1, list2)])]
    lines += ["  %-22s %s" % (name, format_list(values)) for name, values in operations]
    lines.append("  %-22s %.3f" % ("jaccard index", jaccard_index(list1, list2)))
    return lines


def common_to_all(lists):
    """Return the elements shared by every list in the given sequence of lists."""
    shared = lists[0]
    for other in lists[1:]:
        shared = list_intersection(shared, other)
    return shared


