import math


def validate_positive(numbers):
    """Return the values as floats, raising ValueError on non-positive input."""
    values = [float(n) for n in numbers]
    bad = [v for v in values if v <= 0]
    if bad:
        raise ValueError("all numbers must be positive, got: %r" % bad)
    if not values:
        raise ValueError("geometric mean is undefined for an empty list")
    return values


def geometric_mean(numbers):
    """Return the Nth root of the product of N positive numbers."""
    values = validate_positive(numbers)
    logs = [math.log(v) for v in values]
    return math.exp(sum(logs) / len(logs))


def arithmetic_mean(numbers):
    """Return the ordinary average of the values."""
    values = validate_positive(numbers)
    return sum(values) / len(values)


def harmonic_mean(numbers):
    """Return the reciprocal of the mean of the reciprocals."""
    values = validate_positive(numbers)
    reciprocals = [1.0 / v for v in values]
    return len(values) / sum(reciprocals)


def growth_rates(series):
    """Return the period-over-period growth factors of a value series."""
    if len(series) < 2:
        raise ValueError("need at least two observations to compute growth")
    pairs = list(zip(series, series[1:]))
    return [after / before for before, after in pairs]


def average_growth(series):
    """Return the average growth factor of a series as a percentage change."""
    factors = growth_rates(series)
    return (geometric_mean(factors) - 1.0) * 100.0


def summarize(label, numbers):
    """Return a one-line report comparing the three classical means."""
    means = [f(numbers) for f in (arithmetic_mean, geometric_mean, harmonic_mean)]
    formatted = ["%.4f" % m for m in means]
    return "%-14s A=%s  G=%s  H=%s" % (label, *formatted)


def main():
    datasets = [
        ("pair", [2, 8]),
        ("ones", [1, 1, 1]),
        ("powers", [1, 2, 4, 8, 16]),
        ("prices", [1.5, 2.25, 3.0]),
    ]
    report = [summarize(label, data) for label, data in datasets]
    print("\n".join(report))

    revenue = [100.0, 112.0, 120.4, 138.5]
    print("\nRevenue series: %s" % ", ".join("%.1f" % r for r in revenue))
    steps = ["%+.2f%%" % ((f - 1.0) * 100.0) for f in growth_rates(revenue)]
    print("Period growth: %s" % ", ".join(steps))
    print("Average growth: %+.2f%% per period" % average_growth(revenue))

    try:
        geometric_mean([4, -1, 9])
    except ValueError as exc:
        print("Rejected input: %s" % exc)


if __name__ == "__main__":
    main()

