MONTH_NAMES = ["January", "February", "March", "April", "May", "June",
                "July", "August", "September", "October", "November", "December"]


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    lengths = [31, 29 if is_leap_year(year) else 28, 31, 30, 31, 30,
               31, 31, 30, 31, 30, 31]
    return lengths[month - 1]


def format_date(year, month, day):
    if not all(isinstance(value, int) for value in (year, month, day)):
        raise TypeError("year, month and day must be integers")
    if not 1 <= month <= 12:
        raise ValueError(f"month out of range: {month}")
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError(f"day out of range for month {month}: {day}")
    return f"{year:04d}-{month:02d}-{day:02d}"


def format_many(dates):
    return [format_date(*date) for date in dates]


def month_calendar_dates(year, month):
    return [format_date(year, month, day)
            for day in range(1, days_in_month(year, month) + 1)]


def parse_date(text):
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError(f"malformed date string: {text!r}")
    numbers = [int(part) for part in parts]
    return format_date(*numbers)


def long_form(year, month, day):
    stamp = format_date(year, month, day)
    y, m, d = (int(piece) for piece in stamp.split("-"))
    return f"{MONTH_NAMES[m - 1]} {d}, {y}"


def year_first_days(year):
    return [format_date(year, month, 1) for month in range(1, 13)]


def report(dates):
    formatted = format_many(dates)
    widths = [len(entry) for entry in formatted]
    pad = max(widths)
    lines = [f"{entry:<{pad}}  {long_form(*date)}"
             for entry, date in zip(formatted, dates)]
    return "\n".join(lines)


def main():
    samples = [(2023, 7, 15), (2020, 1, 1), (1999, 12, 31), (2024, 2, 29)]
    print(report(samples))

    print("First days of 2021:", ", ".join(year_first_days(2021)))

    february = month_calendar_dates(2024, 2)
    print(f"February 2024 has {len(february)} days, last is {february[-1]}")

    raw = ["2023-7-15", "2020-01-01", "2000-2-29"]
    normalized = [parse_date(text) for text in raw]
    print("Normalized:", normalized)

    leap_years = [year for year in range(2000, 2031) if is_leap_year(year)]
    print("Leap years:", leap_years)


if __name__ == "__main__":
    main()

