import re

HASHTAG_RE = re.compile(r'#(\w+)')


def extract_hashtags(text):
    """Return the hashtags found in text, without the leading '#'."""
    return [match.group(1) for match in HASHTAG_RE.finditer(text)]


def normalize_hashtags(text):
    """Hashtags lowercased, so that #Python and #python count as one tag."""
    return [tag.lower() for tag in extract_hashtags(text)]


def unique_hashtags(text):
    """Normalized hashtags in order of first appearance, without repeats."""
    seen = set()
    tags = normalize_hashtags(text)
    return [tag for tag in tags if not (tag in seen or seen.add(tag))]


def count_hashtags(posts):
    """Map each normalized hashtag to the number of posts mentioning it."""
    counts = {}
    for post in posts:
        for tag in unique_hashtags(post):
            counts[tag] = counts.get(tag, 0) + 1
    return counts


def top_hashtags(posts, limit=3):
    """The most mentioned hashtags, ties broken alphabetically."""
    counts = count_hashtags(posts)
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:limit]


def posts_with_tag(posts, tag):
    """Indices of the posts that mention the given tag."""
    wanted = tag.lstrip('#').lower()
    return [index for index, post in enumerate(posts) if wanted in unique_hashtags(post)]


def strip_hashtags(text):
    """The text with hashtag markup removed, keeping the words themselves."""
    return HASHTAG_RE.sub(r'\1', text)


def format_report(posts):
    """Build a human readable summary of the hashtags used in the posts."""
    lines = ['%d post(s) analysed' % len(posts)]
    summaries = ['  post %d: %s' % (i, ', '.join(unique_hashtags(p)) or '(none)')
                 for i, p in enumerate(posts)]
    lines.extend(summaries)
    lines.append('top hashtags:')
    lines.extend('  #%s x%d' % (tag, n) for tag, n in top_hashtags(posts))
    return '\n'.join(lines)


def main():
    posts = [
        'This is a #test with #python.',
        'No hashtags here.',
        '#Python and #python are the same tag, #test is not.',
        'Learning #python with #regex and #test suites.',
    ]
    print(format_report(posts))
    print('posts mentioning #python:', posts_with_tag(posts, '#python'))
    cleaned = [strip_hashtags(post) for post in posts if extract_hashtags(post)]
    for text in cleaned:
        print('cleaned:', text)


if __name__ == '__main__':
    main()

