import random
import string

ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits
CATEGORIES = {
    "lowercase": string.ascii_lowercase,
    "uppercase": string.ascii_uppercase,
    "digits": string.digits,
}


def generate_password(length):
    """Return a random password of `length` letters and digits."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join([random.choice(ALPHABET) for _ in range(length)])


def generate_batch(count, length):
    """Return `count` independent passwords, each of the given length."""
    return [generate_password(length) for _ in range(count)]


def count_in(password, members):
    """Count how many characters of `password` belong to `members`."""
    return len([ch for ch in password if ch in members])


def category_counts(password):
    """Map each character category to how often it occurs in `password`."""
    pairs = [(name, count_in(password, members)) for name, members in CATEGORIES.items()]
    return dict(pairs)


def strength(password):
    """Score a password by length and by how many categories it uses."""
    counts = category_counts(password)
    used = [name for name, total in counts.items() if total > 0]
    return len(password) + 4 * len(used)


def strongest(passwords):
    """Return the password with the highest strength score."""
    return max(passwords, key=strength)


def describe(password):
    """Build a one-line summary of a password's composition."""
    counts = category_counts(password)
    parts = [f"{name}={counts[name]}" for name in sorted(counts)]
    return f"{password}  score={strength(password)}  " + " ".join(parts)


def report(passwords):
    """Render a numbered report plus a summary of the best candidate."""
    lines = [
        f"{index:>2}. {describe(password)}"
        for index, password in enumerate(passwords, start=1)
    ]
    best = strongest(passwords)
    lines.append(f"best: {best} (score {strength(best)})")
    return "\n".join(lines)


def main():
    lengths = [4, 8, 12, 16]
    samples = [generate_password(length) for length in lengths]
    print(report(samples))

    batch = generate_batch(5, 10)
    print()
    print(report(batch))

    widths = sorted({len(password) for password in samples + batch})
    print()
    print("observed lengths:", ", ".join([str(width) for width in widths]))


if __name__ == "__main__":
    main()

