MONTH_NAMES = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]


def is_leap_year(year):
    """Return True if `year` is a leap year in the Gregorian calendar."""
    if not isinstance(year, int) or isinstance(year, bool):
        raise TypeError("year must be an integer")
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def leap_years_in_range(start, end):
    """Return every leap year in the inclusive range [start, end]."""
    return [year for year in range(start, end + 1) if is_leap_year(year)]


def month_lengths(year):
    """Return the lengths of the twelve months of `year`."""
    extra = 1 if is_leap_year(year) else 0
    return [length + extra if index == 1 else length
            for index, length in enumerate(BASE_LENGTHS)]


def days_in_year(year):
    return sum(month_lengths(year))


def day_of_year(year, month, day):
    """Return the ordinal position of a date inside its own year."""
    lengths = month_lengths(year)
    if not 1 <= month <= 12:
        raise ValueError("month must be between 1 and 12")
    if not 1 <= day <= lengths[month - 1]:
        raise ValueError("day out of range for the given month")
    return sum(lengths[:month - 1]) + day


def month_table(year):
    """Return one "name length" line per month of `year`."""
    return ["{0:<10} {1}".format(name, length)
            for name, length in zip(MONTH_NAMES, month_lengths(year))]


def parse_years(tokens):
    """Turn command-line style tokens into integers, rejecting bad input."""
    bad = [token for token in tokens if not token.lstrip("-").isdigit()]
    if bad:
        raise ValueError("not a year: " + ", ".join(bad))
    return [int(token) for token in tokens]


def calendar_report(years):
    """Build one report line per year describing its length and February."""
    lines = []
    for year in years:
        lengths = month_lengths(year)
        label = "leap" if is_leap_year(year) else "common"
        lines.append(
            "{0:>5}  {1:<6}  {2} days  February has {3}".format(
                year, label, days_in_year(year), lengths[1]
