    """Count leap years per decade across the inclusive range."""
    decades = sorted({year - year % 10 for year in range(start, end + 1)})
    counts = [(decade, len(leap_years_in_range(max(decade, start),
                                               min(decade + 9, end))))
              for decade in decades]
    return ["{0}s: {1}".format(decade, count) for decade, count in counts]


