def sort_dict_by_value(d):
    """Return the items of ``d`` as a list of tuples sorted by value ascending."""
    if not isinstance(d, dict):
        raise TypeError("sort_dict_by_value expects a dictionary")
    invalid = [key for key, value in d.items() if not isinstance(value, (int, float))]
    if invalid:
        raise TypeError("non-numeric values for keys: " + ", ".join(map(str, invalid)))
    return sorted(d.items(), key=lambda item: item[1])


def top_n(d, n):
    """Return the ``n`` items with the largest values, biggest first."""
    return sort_dict_by_value(d)[::-1][:n]


def keys_with_value(d, value):
    """Return every key of ``d`` mapped to exactly ``value``."""
    return [key for key, item in d.items() if item == value]


def group_by_value(d):
    """Group the keys of ``d`` by their shared value, ordered by value."""
    distinct = sorted({value for _, value in sort_dict_by_value(d)})
    return [(value, keys_with_value(d, value)) for value in distinct]


def value_shares(d):
    """Return (key, fraction of the total) pairs in ascending value order."""
    pairs = sort_dict_by_value(d)
    total = sum(value for _, value in pairs)
    if total == 0:
        return [(key, 0.0) for key, _ in pairs]
    return [(key, value / total) for key, value in pairs]


def format_table(pairs):
    """Render (key, value) pairs as aligned text rows."""
    width = max([len(str(key)) for key, _ in pairs], default=0)
    return [f"{str(key):<{width}}  {value}" for key, value in pairs]


def format_groups(groups):
    """Render grouped keys as 'value: key, key' lines."""
    return [f"{value}: {', '.join(str(key) for key in keys)}" for value, keys in groups]


def report(label, data):
    """Print a small summary of one dictionary."""
    pairs = sort_dict_by_value(data)
    print(f"== {label} ==")
    print(f"  sorted: {pairs}")
    for line in format_table(pairs):
        print("  " + line)
    for line in format_groups(group_by_value(data)):
        print("  " + line)
    shares = [f"{key}={share:.1%}" for key, share in value_shares(data)]
    print("  shares: " + (", ".join(shares) if shares else "n/a"))
    print(f"  top two: {top_n(data, 2)}")


def main():
    datasets = [
        ("letters", {'a': 3, 'b': 1, 'c': 2}),
        ("empty", {}),
        ("scores", {'ada': 91, 'bob': 74, 'cy': 91, 'dee': 68}),
    ]
    for label, data in datasets:
        report(label, data)
    try:
        sort_dict_by_value({'x': 'not a number'})
    except TypeError as exc:
        print(f"rejected: {exc}")


if __name__ == "__main__":
    main()

