def dimensions(matrix):
    """Return (rows, cols) for a rectangular matrix, or raise ValueError."""
    if not matrix:
        return (0, 0)
    widths = {len(row) for row in matrix}
    if len(widths) != 1:
        lengths = [len(row) for row in matrix]
        raise ValueError("matrix rows have inconsistent lengths: %r" % (lengths,))
    return (len(matrix), widths.pop())


def validate(matrix1, matrix2):
    """Check that both operands are rectangular matrices of equal shape."""
    for name, candidate in (("matrix1", matrix1), ("matrix2", matrix2)):
        if not isinstance(candidate, list):
            raise TypeError("%s must be a list of lists" % name)
        bad = [row for row in candidate if not isinstance(row, list)]
        if bad:
            raise TypeError("%s must contain only lists, found %r" % (name, bad[0]))
    shape1 = dimensions(matrix1)
    shape2 = dimensions(matrix2)
    if shape1 != shape2:
        raise ValueError("shape mismatch: %r vs %r" % (shape1, shape2))
    return shape1


def add_rows(row1, row2):
    """Return the element-wise sum of two rows of equal length."""
    return [a + b for a, b in zip(row1, row2)]


def matrix_add(matrix1, matrix2):
    """Return the element-wise sum of two matrices of identical dimensions."""
    validate(matrix1, matrix2)
    return [add_rows(row1, row2) for row1, row2 in zip(matrix1, matrix2)]


def matrix_sum(matrices):
    """Add any number of same-shaped matrices together."""
    if not matrices:
        raise ValueError("matrix_sum needs at least one matrix")
    total = matrices[0]
    for other in matrices[1:]:
        total = matrix_add(total, other)
    return total


def render_row(row):
    """Convert one row of values into a list of strings."""
    return [str(value) for value in row]


def column_widths(cells):
    """Return the printing width of each column of a matrix of strings."""
    widths = []
    for column in zip(*cells):
        lengths = [len(text) for text in column]
        widths.append(max(lengths))
    return widths


def pad_row(texts, widths):
    """Right-align each cell of a row to its column width."""
    return [text.rjust(width) for text, width in zip(texts, widths)]


def format_matrix(matrix):
    """Render a matrix as right-aligned columns, one row per line."""
    cells = [render_row(row) for row in matrix]
    if not cells:
        return ""
    widths = column_widths(cells)
    lines = ["  ".join(pad_row(row, widths)) for row in cells]
    return "\n".join(lines)


def main():
    a = [[1, 2], [3, 4]]
    b = [[5, 6], [7, 8]]
    total = matrix_add(a, b)
    print(total)
    print(format_matrix(matrix_sum([a, b, total])))


if __name__ == "__main__":
