def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if not isinstance(decimal_int, int) or isinstance(decimal_int, bool):
        raise TypeError("decimal_to_binary expects an int, got %r" % (decimal_int,))
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative int")
    if decimal_int == 0:
        return "0"
    high = decimal_int.bit_length() - 1
    bits = [str((decimal_int >> shift) & 1) for shift in range(high, -1, -1)]
    return "".join(bits)


def binary_to_decimal(binary_str):
    """Convert a binary string such as '1011' back to an integer."""
    digits = [char for char in binary_str if char != "_"]
    if not digits or any(char not in "01" for char in digits):
        raise ValueError("not a binary string: %r" % (binary_str,))
    weights = [int(char) << shift for shift, char in enumerate(reversed(digits))]
    return sum(weights)


def group_bits(binary_str, size=4):
    """Pad on the left and split into fixed-size groups for readability."""
    padded = "0" * ((-len(binary_str)) % size) + binary_str
    groups = [padded[start:start + size] for start in range(0, len(padded), size)]
    return " ".join(groups)


def parse_inputs(tokens):
    """Turn tokens like '11' or '0b1011' into the integers to convert."""
    cleaned = [token.strip().lower() for token in tokens]
    numbers = []
    for token in cleaned:
        if token.startswith("0b"):
            numbers.append(binary_to_decimal(token[2:]))
        elif token.replace("_", "").isdigit():
            numbers.append(int(token.replace("_", "")))
        else:
            raise ValueError("expected a decimal or 0b-prefixed value: %r" % (token,))
    return numbers


def build_rows(numbers):
    """Build one report row per number."""
    binaries = [decimal_to_binary(number) for number in numbers]
    return [(str(number), binary, group_bits(binary), str(len(binary)))
            for number, binary in zip(numbers, binaries)]


def format_table(rows, headers=("decimal", "binary", "grouped", "bits")):
    """Render rows as a left-aligned text table."""
    table = [list(headers)] + [list(row) for row in rows]
    widths = [max(len(row[index]) for row in table) for index in range(len(headers))]
    lines = []
    for row in table:
        cells = [cell.ljust(width) for cell, width in zip(row, widths)]
        lines.append("  ".join(cells).rstrip())
    rule = ["-" * width for width in widths]
    lines.insert(1, "  ".join(rule))
