    if len(set(values)) != len(values):
        raise ValueError("entries must be unique")
    out_of_range = [v for v in values if v < 1 or v > len(values) + 1]
    if out_of_range:
        raise ValueError("entries must lie between 1 and N: %r" % (out_of_range,))
    return values


