def parse_numbers(text):
    """Turn a string like '5, 2, 8.5' into a list of numbers."""
    tokens = [piece.strip() for piece in text.split(",") if piece.strip()]
    values = []
    for token in tokens:
        try:
            values.append(int(token))
        except ValueError:
            values.append(float(token))
    return values


def validate(numbers):
    """Raise if the input is not a non-empty list of plain numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    if len(numbers) == 0:
        raise ValueError("numbers must not be empty")
    offenders = [repr(item) for item in numbers
                 if not isinstance(item, (int, float)) or isinstance(item, bool)]
    if offenders:
        raise TypeError("not numeric: " + ", ".join(offenders))


def find_smallest(numbers):
    """Return the minimum value of a list of int/float."""
    validate(numbers)
    smallest_number = numbers[0]
    for value in numbers[1:]:
        if value < smallest_number:
            smallest_number = value
    return smallest_number


def positions_of_smallest(numbers):
    """Every index at which the minimum value occurs."""
    smallest_number = find_smallest(numbers)
    return [index for index, value in enumerate(numbers) if value == smallest_number]


def smallest_of_each(datasets):
    """Apply find_smallest to several lists at once."""
    return [find_smallest(numbers) for numbers in datasets]


def format_number(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_report(datasets):
    """One human readable line per dataset."""
    minima = smallest_of_each(datasets)
    lines = []
    for numbers, smallest_number in zip(datasets, minima):
        shown = ", ".join([format_number(value) for value in numbers])
        spots = positions_of_smallest(numbers)
        lines.append("[{}] -> {} at index {}".format(
            shown, format_number(smallest_number),
            ", ".join([str(index) for index in spots])))
    return lines


def main():
    raw_inputs = ["5, 2, 8, 1", "-10, 0, 3", "4.5, -1.25, 4.5, -1.25", "7"]
    datasets = [parse_numbers(text) for text in raw_inputs]
    for line in format_report(datasets):
        print(line)
    overall = find_smallest([value for numbers in datasets for value in numbers])
    print("overall smallest:", format_number(overall))


