def validate(numbers):
    """Return the numbers as floats, raising ValueError on invalid input."""
    if not numbers:
        raise ValueError("harmonic mean requires at least one number")
    bad_types = [repr(x) for x in numbers if not isinstance(x, (int, float))]
    if bad_types:
        raise ValueError("non-numeric values: " + ", ".join(bad_types))
    values = [float(x) for x in numbers]
    non_positive = [v for v in values if v <= 0.0]
    if non_positive:
        raise ValueError("all numbers must be positive, got " + repr(non_positive[0]))
    return values


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate(numbers)
    reciprocals = [1.0 / v for v in values]
    return len(values) / sum(reciprocals)


def arithmetic_mean(numbers):
    values = validate(numbers)
    return sum(values) / len(values)


def geometric_mean(numbers):
    values = validate(numbers)
    product = 1.0
    for v in values:
        product *= v
    return product ** (1.0 / len(values))


def parse_series(text):
    """Turn a comma or space separated string into a list of floats."""
    return [float(tok) for tok in text.replace(",", " ").split()]


def weighted_harmonic_mean(numbers, weights):
    values = validate(numbers)
    if len(weights) != len(values):
        raise ValueError("weights and numbers must have the same length")
    clean_weights = validate(weights)
    terms = [w / v for w, v in zip(clean_weights, values)]
    return sum(clean_weights) / sum(terms)


def describe(numbers):
    """Build a one-line report comparing the three classical means."""
    means = [
        ("harmonic", harmonic_mean(numbers)),
        ("geometric", geometric_mean(numbers)),
        ("arithmetic", arithmetic_mean(numbers)),
    ]
    parts = ["{0}={1:.6f}".format(name, value) for name, value in means]
    shown = ", ".join(str(n) for n in numbers)
    return "[{0}] -> {1}".format(shown, " | ".join(parts))


def main():
    raw_series = ["1, 2, 4", "10 10 10", "2.5, 5, 7.5, 10"]
    series = [parse_series(text) for text in raw_series]
    for numbers in series:
        print(describe(numbers))

    speeds = [60.0, 40.0]
    hours = [2.0, 3.0]
    print("average speed: {0:.6f}".format(weighted_harmonic_mean(speeds, hours)))

    broken = ["1, 0, 4", "", "1, -3"]
    for text in broken:
        try:
            harmonic_mean(parse_series(text))
        except ValueError as err:
            print("rejected {0!r}: {1}".format(text, err))


if __name__ == "__main__":
    main()

