def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    w = _as_positive_float(width, "width")
    h = _as_positive_float(height, "height")
    return float(w * h)


def _as_positive_float(value, name):
    """Convert value to float, rejecting non-numeric or non-positive input."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError("{0} must be a number, got {1!r}".format(name, value))
    if number <= 0:
        raise ValueError("{0} must be positive, got {1!r}".format(name, number))
    return number


def parse_spec(text):
    """Parse a 'width x height' string into a (width, height) float pair."""
    parts = [piece.strip() for piece in text.replace("X", "x").split("x")]
    if len(parts) != 2:
        raise ValueError("expected 'width x height', got {0!r}".format(text))
    names = ("width", "height")
    values = [_as_positive_float(part, name) for part, name in zip(parts, names)]
    return values[0], values[1]


def parse_specs(lines):
    """Parse many specs, skipping blank lines and '#' comments."""
    useful = [line for line in lines if line.strip() and not line.lstrip().startswith("#")]
    return [parse_spec(line) for line in useful]


def areas(pairs):
    """Compute the area for each (width, height) pair."""
    return [rectangle_area(width, height) for width, height in pairs]


def perimeters(pairs):
    """Compute the perimeter for each (width, height) pair."""
    return [2.0 * (width + height) for width, height in pairs]


def total_area(pairs):
    """Sum of the areas of all rectangles described by pairs."""
    return float(sum(areas(pairs)))


def squares(pairs):
    """Keep only the pairs whose width and height are equal."""
    return [(width, height) for width, height in pairs if width == height]


