        for (w, h), a, p in zip(pairs, areas(pairs), perimeters(pairs))
    ]
    rows.append("total area: {0:.2f}".format(total_area(pairs)))
    rows.append("squares among them: {0:d}".format(len(squares(pairs))))
    return "\n".join(rows)


