import random

FACES = ('Heads', 'Tails')


def simulate_coin_flip():
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    result = random.choice(FACES)
    return result


def flip_many(count):
    """Flip the coin `count` times and return the list of outcomes."""
    if count < 0:
        raise ValueError("count must be non-negative")
    return [simulate_coin_flip() for _ in range(count)]


def tally(flips):
    """Return a face -> occurrences mapping covering both faces."""
    counts = [flips.count(face) for face in FACES]
    return dict(zip(FACES, counts))


def frequencies(flips):
    """Return a face -> relative frequency mapping."""
    total = len(flips)
    if total == 0:
        return dict(zip(FACES, [0.0] * len(FACES)))
    counted = tally(flips)
    shares = [counted[face] / total for face in FACES]
    return dict(zip(FACES, shares))


def longest_streak(flips):
    """Return (face, length) for the longest run of identical outcomes."""
    best_face, best_len = None, 0
    current_face, current_len = None, 0
    for flip in flips:
        current_len = current_len + 1 if flip == current_face else 1
        current_face = flip
        if current_len > best_len:
            best_face, best_len = current_face, current_len
    return best_face, best_len


def alternations(flips):
    """Count positions where an outcome differs from the previous one."""
    changes = [1 for prev, nxt in zip(flips, flips[1:]) if prev != nxt]
    return sum(changes)


def histogram(flips, width=40):
    """Render a simple text histogram of the outcome frequencies."""
    freqs = frequencies(flips)
    rows = [(face, freqs[face], "#" * round(freqs[face] * width)) for face in FACES]
    lines = [f"{face:<6} {share:6.2%} {bar}" for face, share, bar in rows]
    return "\n".join(lines)


def report(count):
    """Run a batch of flips and return a printable summary."""
    flips = flip_many(count)
    counted = tally(flips)
    face, streak = longest_streak(flips)
    parts = [f"{name}={counted[name]}" for name in FACES]
    lines = [f"{count} flips: " + ", ".join(parts)]
    lines.append(histogram(flips))
    lines.append(f"Longest streak: {streak} x {face}")
    lines.append(f"Alternations: {alternations(flips)}")
    lines.append("First ten: " + " ".join(flips[:10]))
    return "\n".join(lines)


def main():
    print("Single flip:", simulate_coin_flip())
    for batch in (10, 100, 1000):
        print()
        print(report(batch))


if __name__ == "__main__":
    main()

