from collections import Counter


def validate_input(nested_dict, separator):
    """Check that the input is a dict with only one level of nesting."""
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    if not isinstance(separator, str) or not separator:
        raise ValueError("separator must be a non-empty string")
    bad_keys = [key for key in nested_dict if not isinstance(key, str)]
    if bad_keys:
        raise TypeError("outer keys must be strings: %r" % (bad_keys,))
    deep = [key for key, value in nested_dict.items()
            if isinstance(value, dict) and any(isinstance(v, dict) for v in value.values())]
    if deep:
        raise ValueError("only one level of nesting is supported: %r" % (deep,))


def flatten_dict(nested_dict, separator):
    """Flatten a dictionary with at most one level of nesting."""
    validate_input(nested_dict, separator)
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            pairs = [(key + separator + str(inner), inner_value)
                     for inner, inner_value in value.items()]
            flattened_dict.update(pairs)
        else:
            flattened_dict[key] = value
    return flattened_dict


def unflatten_dict(flat_dict, separator):
    """Rebuild the nested form of a dictionary flattened with `separator`."""
    nested = {}
    for key, value in flat_dict.items():
        head, found, tail = key.partition(separator)
        if found:
            nested.setdefault(head, {})[tail] = value
        else:
            nested[key] = value
    return nested


def collisions(nested_dict, separator):
    """Return flat keys produced more than once by flattening."""
    flat_keys = [key + separator + str(inner)
                 if isinstance(value, dict) else key
                 for key, value in nested_dict.items()
                 for inner in (value if isinstance(value, dict) else [None])]
    counts = Counter(flat_keys)
    return sorted([key for key, total in counts.items() if total > 1])


def format_report(nested_dict, separator):
    """Render a flattening of `nested_dict` as aligned text lines."""
    flat = flatten_dict(nested_dict, separator)
    width = max([len(key) for key in flat] or [0])
    lines = ["%-*s -> %r" % (width, key, flat[key]) for key in sorted(flat)]
    clashes = collisions(nested_dict, separator)
    if clashes:
        lines.append("collisions: " + ", ".join(clashes))
    return "\n".join(lines)


def main():
    samples = [
        ({'a': 1, 'b': {'c': 2, 'd': 3}}, '_'),
        ({'x': {'y': 10}}, '.'),
        ({'a': {'b': 1}, 'a_b': 2}, '_'),
