def validate_integers(numbers):
    """Return the input as a list of ints, rejecting anything non-integral."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of integers")
    bad = [value for value in numbers if not isinstance(value, int) or isinstance(value, bool)]
    if bad:
        raise TypeError("non-integer values in input: %r" % (bad,))
    return list(numbers)


def distinct_descending(numbers):
    """Distinct values of the input, ordered from largest to smallest."""
    return sorted(set(numbers), reverse=True)


def find_third_largest(numbers):
    """Third largest distinct value, or the largest if fewer than three exist."""
    values = validate_integers(numbers)
    if not values:
        raise ValueError("numbers must contain at least one integer")
    ranked = distinct_descending(values)
    if len(ranked) < 3:
        return ranked[0]
    return ranked[2]


def parse_line(line):
    """Turn a whitespace/comma separated line of text into a list of ints."""
    return [int(token) for token in line.replace(",", " ").split()]


def rank_table(numbers, depth=3):
    """Pairs of (rank, value) for the top `depth` distinct values."""
    ranked = distinct_descending(numbers)
    return [(position + 1, value) for position, value in enumerate(ranked[:depth])]


def describe(numbers):
    """One-line human readable summary of the third-largest computation."""
    answer = find_third_largest(numbers)
    shown = [str(value) for value in numbers]
    parts = ["#%d=%d" % (rank, value) for rank, value in rank_table(numbers)]
    return "[%s] -> %d (top: %s)" % (", ".join(shown), answer, " ".join(parts))


def main():
    raw_lines = [
        "3, 2, 1, 5, 4",
        "1 1 2",
        "7",
        "10 10 9 9 8 8 7",
        "-1 -5 -3 -3 -2",
    ]
    datasets = [parse_line(line) for line in raw_lines]
    reports = [describe(dataset) for dataset in datasets]
    for report in reports:
        print(report)

    answers = [find_third_largest(dataset) for dataset in datasets]
    print("answers:", answers)

