PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = [PAIRS[closer] for closer in PAIRS]
ALLOWED = OPENERS + list(PAIRS)


def find_invalid_characters(s):
    """Return the characters of `s` that are not brackets, in order."""
    return [ch for ch in s if ch not in ALLOWED]


def is_brackets_balanced(s):
    """Return True if the bracket string `s` is balanced and correctly nested."""
    if find_invalid_characters(s):
        raise ValueError('input may only contain brackets')
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        else:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
    return not stack


def nesting_depths(s):
    """Running nesting depth after each character of a balanced string."""
    steps = [1 if ch in OPENERS else -1 for ch in s]
    depths = []
    level = 0
    for step in steps:
        level += step
        depths.append(level)
    return depths


def max_nesting_depth(s):
    """Deepest nesting level reached by a balanced bracket string."""
    return max(nesting_depths(s), default=0)


def first_mismatch_index(s):
    """Index of the first closer that does not match its opener, else None."""
    stack = []
    for index, ch in enumerate(s):
        if ch in OPENERS:
            stack.append(ch)
        elif not stack or stack.pop() != PAIRS[ch]:
            return index
    return None


