    """One-line human readable verdict for a single bracket string."""
    label = s if s else '<empty>'
    if not is_brackets_balanced(s):
        spot = first_mismatch_index(s)
        reason = 'unclosed openers' if spot is None else 'mismatch at index %d' % spot
        return '%-12s unbalanced (%s)' % (label, reason)
    return '%-12s balanced (max depth %d)' % (label, max_nesting_depth(s))


