def int_to_roman(num):
    """Convert an integer between 1 and 3999 into its Roman numeral string."""
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be an integer")
    if not 1 <= num <= 3999:
        raise ValueError("num must be between 1 and 3999")
    remaining = num
    parts = []
    for value, symbol in PAIRS:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(roman):
    """Convert a Roman numeral string back into an integer."""
    digits = [DIGIT_VALUES[char] for char in roman.upper()]
    total = 0
    for i, value in enumerate(digits):
        following = digits[i + 1:]
        if following and max(following) > value:
            total -= value
        else:
            total += value
    return total


