def validate(numbers):
    """Return the input as a list of numbers, raising TypeError on bad items."""
    bad = [repr(item) for item in numbers if not isinstance(item, (int, float))]
    if bad:
        raise TypeError("non-numeric values: " + ", ".join(bad))
    return list(numbers)


def adjacent_pairs(numbers):
    """Pair every element with its successor."""
    return [(numbers[i], numbers[i + 1]) for i in range(len(numbers) - 1)]


def is_sorted(numbers):
    """Return True if numbers is in ascending (non-decreasing) order."""
    values = validate(numbers)
    return all(left <= right for left, right in adjacent_pairs(values))


def inversion_positions(numbers):
    """Indices i where numbers[i] > numbers[i + 1]."""
    pairs = adjacent_pairs(validate(numbers))
    return [i for i, (left, right) in enumerate(pairs) if left > right]


def is_strictly_sorted(numbers):
    """Return True if every element is smaller than the one after it."""
    pairs = adjacent_pairs(validate(numbers))
    return all(left < right for left, right in pairs)


def duplicate_values(numbers):
    """Values that appear more than once, in order of first appearance."""
    values = validate(numbers)
    seen = []
    for value in values:
        if value not in seen:
            seen.append(value)
    return [value for value in seen if values.count(value) > 1]


def describe(numbers):
    """Build a one-line human readable verdict for a list of numbers."""
    shown = ", ".join([format(value, "g") for value in validate(numbers)])
    if not is_sorted(numbers):
        spots = inversion_positions(numbers)
        where = " and ".join(["index %d" % i for i in spots])
        return "[%s] is not ascending (drops at %s)" % (shown, where)
    dups = duplicate_values(numbers)
    if dups:
        listed = "/".join([format(value, "g") for value in dups])
        return "[%s] is ascending with repeats (%s)" % (shown, listed)
    return "[%s] is strictly ascending" % shown


