def count_frequencies(numbers):
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def validate_numbers(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    bad = []
    for value in numbers:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            bad.append(value)
    if bad:
        raise TypeError("non-numeric values found: %r" % (bad,))
    if not numbers:
        raise ValueError("numbers must not be empty")
    return list(numbers)


def calculate_mode(numbers):
    values = validate_numbers(numbers)
    counts = count_frequencies(values)
    best = max(counts.values())
    winners = []
    for value, freq in counts.items():
        if freq == best:
            winners.append(value)
    return winners[0]


def all_modes(numbers):
    values = validate_numbers(numbers)
    counts = count_frequencies(values)
    best = max(counts.values())
    tied = []
    for value in values:
        if counts[value] == best:
            tied.append(value)
    unique = []
    for value in tied:
        if value not in unique:
            unique.append(value)
    return unique


def frequency_table(numbers):
    counts = count_frequencies(validate_numbers(numbers))
    rows = []
    for value in sorted(counts):
        rows.append((value, counts[value]))
    return rows


def format_report(numbers):
    rows = frequency_table(numbers)
    width = max(len(str(value)) for value, _ in rows)
    lines = []
    for value, freq in rows:
        lines.append("%*s : %s" % (width, value, "#" * freq))
