def normalize_rectangle(x1, y1, x2, y2):
    """Return the rectangle as (left, bottom, right, top) regardless of input order."""
    left, right = sorted([x1, x2])
    bottom, top = sorted([y1, y2])
    return left, bottom, right, top


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """True if (px, py) lies inside or on the border of the rectangle."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    return left <= px <= right and bottom <= py <= top


def points_inside(points, rect):
    """Keep only the points of the sequence that fall in the rectangle."""
    return [(px, py) for px, py in points if is_point_in_rectangle(px, py, *rect)]


def points_outside(points, rect):
    """Keep only the points of the sequence that fall outside the rectangle."""
    return [(px, py) for px, py in points if not is_point_in_rectangle(px, py, *rect)]


def on_border(px, py, rect):
    left, bottom, right, top = normalize_rectangle(*rect)
    if not is_point_in_rectangle(px, py, *rect):
        return False
    return px in (left, right) or py in (bottom, top)


def corners(rect):
    left, bottom, right, top = normalize_rectangle(*rect)
    return [(x, y) for x in (left, right) for y in (bottom, top)]


def classify(points, rect):
    """Label every point as 'border', 'interior' or 'outside'."""
    labels = []
    for px, py in points:
        if not is_point_in_rectangle(px, py, *rect):
            labels.append("outside")
        elif on_border(px, py, rect):
            labels.append("border")
        else:
            labels.append("interior")
    return labels


def parse_points(text):
    """Read whitespace separated 'x,y' tokens into integer pairs."""
    pairs = [token.split(",") for token in text.split()]
    return [(int(a), int(b)) for a, b in pairs]


def format_report(points, rect):
    labels = classify(points, rect)
    lines = ["(%d, %d) -> %s" % (px, py, label)
             for (px, py), label in zip(points, labels)]
    counts = {name: labels.count(name) for name in ("interior", "border", "outside")}
    summary = ", ".join(["%s: %d" % (name, counts[name]) for name in sorted(counts)])
    return "\n".join(lines + [summary])


def main():
    rect = (0, 0, 5, 5)
