import math


def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    coords = [float(v) for v in (x1, y1, x2, y2)]
    deltas = [b - a for a, b in ((coords[0], coords[2]), (coords[1], coords[3]))]
    return math.sqrt(sum(d * d for d in deltas))


def parse_point(text: str) -> tuple:
    parts = [chunk.strip() for chunk in text.replace("(", "").replace(")", "").split(",")]
    if len(parts) != 2:
        raise ValueError(f"expected two coordinates, got {len(parts)}: {text!r}")
    numbers = [float(p) for p in parts]
    return numbers[0], numbers[1]


def parse_pairs(lines) -> list:
    pairs = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        halves = [half for half in stripped.split(";") if half.strip()]
        if len(halves) != 2:
            raise ValueError(f"expected two points separated by ';': {stripped!r}")
        pairs.append(tuple(parse_point(h) for h in halves))
    return pairs


def distances(pairs) -> list:
    return [euclidean_distance_2d(p[0], p[1], q[0], q[1]) for p, q in pairs]


def path_length(points) -> float:
    steps = [
        euclidean_distance_2d(a[0], a[1], b[0], b[1])
        for a, b in zip(points, points[1:])
    ]
    return sum(steps)


def nearest_neighbour(target, candidates) -> tuple:
    scored = [(euclidean_distance_2d(*target, *c), c) for c in candidates]
    return min(scored)[1]


def format_report(pairs) -> str:
    values = distances(pairs)
    width = max([len(f"{v:.4f}") for v in values])
    rows = [
        f"{p} -> {q}: {v:>{width}.4f}"
        for (p, q), v in zip(pairs, values)
    ]
    rows.append(f"total path length: {path_length([p for p, _ in pairs]):.4f}")
    return "\n".join(rows)


def main() -> None:
    raw = [
        "(0, 0); (3, 4)",
        "(1, 1); (1, 1)",
        "# a comment line",
        "(-2.5, 7); (0.5, 3)",
    ]
    pairs = parse_pairs(raw)
    print(format_report(pairs))

    origin = (0.0, 0.0)
    targets = [q for _, q in pairs]
    closest = nearest_neighbour(origin, targets)
    print(f"closest endpoint to {origin}: {closest}")

    labelled = [f"d{i}={d:.2f}" for i, d in enumerate(distances(pairs), start=1)]
    print(" | ".join(labelled))


if __name__ == "__main__":
    main()

