import string

PUNCTUATION = set(string.punctuation)


def strip_punctuation(token):
    """Remove leading/trailing punctuation from a token."""
    kept = [ch for ch in token if ch not in PUNCTUATION]
    return "".join(kept)


def tokenize(text):
    """Split text on whitespace and drop punctuation-only fragments."""
    raw = text.split()
    cleaned = [strip_punctuation(token) for token in raw]
    return [token for token in cleaned if token]


def count_words(text):
    """Count the words in text, ignoring punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return len(tokenize(text))


def word_lengths(text):
    """Return the length of every word in text."""
    return [len(word) for word in tokenize(text)]


def longest_words(text):
    """Return every word tying for the greatest length."""
    words = tokenize(text)
    if not words:
        return []
    longest = max(len(word) for word in words)
    return [word for word in words if len(word) == longest]


def frequencies(text):
    """Map lowercased words to how often they occur."""
    counts = {}
    for word in tokenize(text):
        key = word.lower()
        counts[key] = counts.get(key, 0) + 1
    return counts


def format_report(text):
    """Build a multi-line summary of the words found in text."""
    counts = frequencies(text)
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    lines = ["total words: {}".format(count_words(text))]
    lines.append("average length: {:.2f}".format(
        sum(word_lengths(text)) / len(counts) if counts else 0.0))
    lines.append("longest: {}".format(", ".join(longest_words(text)) or "-"))
    lines.extend("{:<12} {}".format(word, n) for word, n in ranked)
    return "\n".join(lines)


def main():
    samples = [
        "Hello world, how are you?",
        "  One   word  ",
        "The rain in Spain: the rain stays!",
        "...",
    ]
    widths = [len(sample) for sample in samples]
    for sample, width in zip(samples, widths):
        print("input ({} chars): {!r}".format(width, sample))
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

