"""Filter dictionary entries whose values exceed a threshold."""


def _numeric_type_errors(input_dict):
    """Return messages describing values that cannot be compared numerically."""
    return [
        "value for key {!r} is not numeric: {!r}".format(key, value)
        for key, value in input_dict.items()
        if not isinstance(value, (int, float)) or isinstance(value, bool)
    ]


def validate_input(input_dict, threshold):
    """Raise TypeError unless the arguments can be filtered numerically."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got {}".format(type(input_dict).__name__))
    if not isinstance(threshold, (int, float)) or isinstance(threshold, bool):
        raise TypeError("threshold must be an int or float, got {!r}".format(threshold))
    problems = _numeric_type_errors(input_dict)
    if problems:
        raise TypeError("; ".join(problems))


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is greater than threshold."""
    validate_input(input_dict, threshold)
    kept = [(key, value) for key, value in input_dict.items() if value > threshold]
    return dict(kept)


def rejected_keys(input_dict, threshold):
    """Return the keys dropped by filter_dict_by_value, in insertion order."""
    kept = filter_dict_by_value(input_dict, threshold)
    return [key for key in input_dict if key not in kept]


def summarize(input_dict, threshold):
    """Build a short multi-line report about one filtering operation."""
    kept = filter_dict_by_value(input_dict, threshold)
    dropped = rejected_keys(input_dict, threshold)
    lines = ["threshold = {}".format(threshold), "kept {} of {} entries".format(len(kept), len(input_dict))]
    lines.extend(["  keep {}: {}".format(key, value) for key, value in kept.items()])
    if dropped:
        lines.append("  dropped: " + ", ".join([str(key) for key in dropped]))
    return "\n".join(lines)


