import sys

FREEZING_C = 0.0
BOILING_C = 100.0


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9.0 / 5.0 + 32.0


def parse_temperatures(text):
    """Read whitespace/comma separated Celsius values out of a text blob."""
    tokens = text.replace(",", " ").split()
    bad = [tok for tok in tokens if not _is_number(tok)]
    if bad:
        raise ValueError("not a number: " + ", ".join(bad))
    return [float(tok) for tok in tokens]


def _is_number(token):
    try:
        float(token)
    except ValueError:
        return False
    return True


def convert_all(celsius_values):
    """Pair every Celsius value with its Fahrenheit equivalent."""
    return [(c, celsius_to_fahrenheit(c)) for c in celsius_values]


def describe(celsius):
    if celsius <= FREEZING_C:
        return "at or below freezing"
    if celsius >= BOILING_C:
        return "at or above boiling"
    return "liquid water range"


def format_table(pairs):
    """Render converted pairs as aligned text rows plus a header."""
    rows = [
        ("{:>10.2f}".format(c), "{:>10.2f}".format(f), describe(c))
        for c, f in pairs
    ]
    width = max([len(row[2]) for row in rows] + [len("note")])
    header = "{:>10} {:>10} {}".format("celsius", "fahrenheit", "note".ljust(width))
    lines = ["{} {} {}".format(c, f, note.ljust(width)) for c, f, note in rows]
    return "\n".join([header, "-" * len(header)] + lines)


def summarize(pairs):
    fahrenheits = [f for _, f in pairs]
    return "count={} min={:.2f}F max={:.2f}F mean={:.2f}F".format(
        len(fahrenheits),
        min(fahrenheits),
        max(fahrenheits),
        sum(fahrenheits) / len(fahrenheits),
    )


def main(argv):
    text = " ".join(argv[1:]) if len(argv) > 1 else "-40 0 21.5 37 100"
    try:
        celsius_values = parse_temperatures(text)
    except ValueError as exc:
        print("error: {}".format(exc), file=sys.stderr)
        return 2
    if not celsius_values:
        print("error: no temperatures given", file=sys.stderr)
        return 2
    pairs = convert_all(celsius_values)
    print(format_table(pairs))
    print(summarize(pairs))
