def is_prime(value):
    """Return True when value is a prime number, using trial division."""
    if value < 2:
        return False
    if value < 4:
        return True
    if value % 2 == 0:
        return False
    limit = int(value ** 0.5)
    divisors = [d for d in range(3, limit + 1, 2) if value % d == 0]
    return not divisors


def generate_primes(n):
    """Return every prime number up to and including n."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    return [candidate for candidate in range(2, n + 1) if is_prime(candidate)]


def twin_pairs(primes):
    """Return the pairs of primes that differ by exactly two."""
    return [(a, b) for a, b in zip(primes, primes[1:]) if b - a == 2]


def prime_gaps(primes):
    """Return the distance between each prime and the next one."""
    return [b - a for a, b in zip(primes, primes[1:])]


def digit_sum(value):
    return sum([int(ch) for ch in str(value)])


def additive_primes(primes):
    """Primes whose decimal digits themselves sum to a prime."""
    return [p for p in primes if is_prime(digit_sum(p))]


def format_columns(primes, per_row=10, width=5):
    """Lay the primes out in a fixed-width grid of text rows."""
    rows = [primes[start:start + per_row] for start in range(0, len(primes), per_row)]
    lines = []
    for row in rows:
        cells = [str(p).rjust(width) for p in row]
        lines.append("".join(cells))
    return lines


def summarize(n):
    """Build a human readable report about the primes below n."""
    primes = generate_primes(n)
    if not primes:
        return ["No primes up to {}.".format(n)]
    gaps = prime_gaps(primes)
    twins = twin_pairs(primes)
    report = ["Primes up to {}: {} found".format(n, len(primes))]
    report.append("Largest prime: {}".format(primes[-1]))
    report.append("Largest gap: {}".format(max(gaps) if gaps else 0))
    twin_text = ["{}/{}".format(a, b) for a, b in twins]
    report.append("Twin pairs: {}".format(", ".join(twin_text) or "none"))
    additive = additive_primes(primes)
    report.append("Additive primes: {}".format(len(additive)))
    report.extend(format_columns(primes))
    return report


