FEET_PER_METER = 3.28084
VALID_UNITS = ('m', 'ft')


def convert_length(value, from_unit, to_unit):
    """Convert a length between meters and feet."""
    units = [str(unit).strip().lower() for unit in (from_unit, to_unit)]
    bad = [unit for unit in units if unit not in VALID_UNITS]
    if bad:
        raise ValueError("unsupported unit(s): " + ", ".join(bad))
    source, target = units
    value = float(value)
    if source == target:
        return value
    if source == 'm':
        return value * FEET_PER_METER
    return value / FEET_PER_METER


def parse_request(line):
    """Parse a line like '10 m ft' into (value, from_unit, to_unit)."""
    parts = line.split()
    if len(parts) != 3:
        raise ValueError("expected 'value from_unit to_unit', got: " + line)
    return float(parts[0]), parts[1], parts[2]


def convert_all(requests):
    """Convert a sequence of (value, from_unit, to_unit) triples."""
    return [convert_length(*request) for request in requests]


def format_result(value, from_unit, to_unit, result):
    return "{0:g} {1} = {2:g} {3}".format(value, from_unit, result, to_unit)


def build_report(lines):
    """Turn raw request lines into formatted conversion strings."""
    requests = [parse_request(line) for line in lines if line.strip()]
    results = convert_all(requests)
    return [format_result(*req, result=res) for req, res in zip(requests, results)]


def round_trip_errors(values, unit):
    """Absolute error after converting out of and back into `unit`."""
    other = 'ft' if unit == 'm' else 'm'
    converted = [convert_length(value, unit, other) for value in values]
    back = [convert_length(value, other, unit) for value in converted]
    return [abs(original - restored) for original, restored in zip(values, back)]


def main():
    lines = [
        "10 m ft",
        "3.28084 ft m",
        "1 m m",
        "100 ft m",
    ]
    for text in build_report(lines):
