    samples = [0.5, 1.0, 42.0, 1234.5]
    errors = round_trip_errors(samples, 'm')
    worst = max(errors)
    print("worst round-trip error: {0:.3e} m".format(worst))

    try:
        convert_length(1, 'm', 'yd')
    except ValueError as exc:
        print("rejected:", exc)


if __name__ == '__main__':
