from datetime import date


def parse_date(text):
    """Turn a 'YYYY-MM-DD' string into a (year, month, day) tuple of ints."""
    parts = [chunk.strip() for chunk in text.split("-")]
    if len(parts) != 3:
        raise ValueError("expected a date in YYYY-MM-DD form: %r" % text)
    non_numeric = [part for part in parts if not part.isdigit()]
    if non_numeric:
        raise ValueError("non-numeric date components: %s" % ", ".join(non_numeric))
    return tuple(int(part) for part in parts)


def days_since(year, month, day):
    """Return the number of full days between the given past date and today."""
    for name, value in (("year", year), ("month", month), ("day", day)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s must be an int, got %r" % (name, value))
    then = date(year, month, day)
    today = date.today()
    if then > today:
        raise ValueError("%s is in the future" % then.isoformat())
    return (today - then).days


def days_since_all(texts):
    """Map a sequence of date strings to their age in days."""
    triples = [parse_date(text) for text in texts]
    return [days_since(*triple) for triple in triples]


def describe(text):
    """Human-readable age of a single date string."""
    count = days_since(*parse_date(text))
    if count == 0:
        return "%s was today" % text
    if count == 1:
        return "%s was 1 day ago" % text
    return "%s was %d days ago" % (text, count)


def oldest(texts):
    """Return the date string with the largest age in days."""
    return max(zip(days_since_all(texts), texts))[1]


def format_report(texts):
    """Build a padded report of each date's age plus a summary footer."""
    width = max(len(text) for text in texts)
    ages = days_since_all(texts)
    lines = [
        "%s : %5d days" % (text.ljust(width), age)
        for text, age in zip(texts, ages)
    ]
    lines.append("-" * (width + 14))
    lines.append("%s : oldest" % oldest(texts).ljust(width))
    lines.append("%s : %5d days total" % ("sum".ljust(width), sum(ages)))
    return "\n".join(lines)


def main():
    samples = ["2023-01-01", "2022-12-31", "2000-02-29", "1969-07-20"]
    print(format_report(samples))
    print()
    for text in samples:
        print(describe(text))
    print()
    print("moon landing:", days_since(1969, 7, 20), "days")


if __name__ == "__main__":
    main()

