def parse_csv_line(line):
    """Split a single CSV row into fields, preserving empty ones."""
    stripped = line.rstrip("\r\n")
    if stripped == "":
        return [""]
    return [field.strip() for field in stripped.split(",")]


def parse_csv(text):
    """Parse a whole CSV document into a list of field lists."""
    lines = [line for line in text.splitlines() if line.strip() != ""]
    return [parse_csv_line(line) for line in lines]


def normalize_rows(rows):
    """Pad every row with empty fields so all rows have the same length."""
    width = max([len(row) for row in rows], default=0)
    return [row + [""] * (width - len(row)) for row in rows]


def column_widths(rows):
    """Display width needed by each column."""
    columns = list(zip(*rows))
    return [max(len(field) for field in column) for column in columns]


def format_row(row, widths):
    cells = [field.ljust(width) for field, width in zip(row, widths)]
    return " | ".join(cells).rstrip()


def format_table(rows):
    """Render rows as an aligned text table with a header separator."""
    padded = normalize_rows(rows)
    widths = column_widths(padded)
    lines = [format_row(row, widths) for row in padded]
    if len(lines) > 1:
        separator = "-+-".join(["-" * width for width in widths])
        lines.insert(1, separator)
    return "\n".join(lines)


def empty_field_report(rows):
    """Map each row index to the column indices that hold an empty field."""
    report = {}
    for index, row in enumerate(normalize_rows(rows)):
        missing = [column for column, field in enumerate(row) if field == ""]
        if missing:
            report[index] = missing
    return report


def column_totals(rows, columns):
    """Sum the numeric values found in the given columns."""
    padded = normalize_rows(rows)
    totals = []
    for column in columns:
        values = [row[column] for row in padded[1:] if row[column].isdigit()]
        totals.append(sum(int(value) for value in values))
    return totals


def main():
