def update_inventory(inventory, item_name, quantity_change):
    """Apply a quantity change to one item, clamping the result at zero."""
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item_name must be a non-empty string")
    current = inventory.get(item_name, 0)
    inventory[item_name] = max(0, current + quantity_change)
    return inventory


def parse_transaction(line):
    """Turn 'apple,-3' into ('apple', -3)."""
    fields = [part.strip() for part in line.split(",")]
    if len(fields) != 2:
        raise ValueError("expected 'item,change' but got %r" % line)
    name, change = fields
    return name, int(change)


def parse_transactions(lines):
    """Parse every non-blank line into a transaction tuple."""
    useful = [line for line in lines if line.strip()]
    return [parse_transaction(line) for line in useful]


def apply_transactions(inventory, transactions):
    """Apply transactions in order, returning the same dictionary."""
    for name, change in transactions:
        update_inventory(inventory, name, change)
    return inventory


def out_of_stock(inventory):
    return sorted([name for name, qty in inventory.items() if qty == 0])


def low_stock(inventory, threshold):
    candidates = [(name, qty) for name, qty in inventory.items() if 0 < qty <= threshold]
    return sorted(candidates, key=lambda pair: (pair[1], pair[0]))


def format_report(inventory, threshold):
    width = max([len(name) for name in inventory] + [4])
    rows = ["%-*s %5d" % (width, name, inventory[name]) for name in sorted(inventory)]
    lines = ["STOCK REPORT", "-" * (width + 6)]
