        lines.append("out of stock: " + ", ".join(empty))
    warnings = ["%s (%d left)" % (name, qty) for name, qty in low_stock(inventory, threshold)]
    if warnings:
        lines.append("reorder soon: " + "; ".join(warnings))
    return "\n".join(lines)


