def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions turning s1 into s2."""
    if s1 == s2:
        return 0
    if not s1 or not s2:
        return len(s1) or len(s2)
    previous = list(range(len(s2) + 1))
    for i, a in enumerate(s1, start=1):
        current = [i]
        for j, b in enumerate(s2, start=1):
            cost = 0 if a == b else 1
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost))
        previous = current
    return previous[-1]


def distance_row(word, words):
    """Distances from one word to each of the given words."""
    return [levenshtein_distance(word, other) for other in words]


def distance_matrix(words):
    """Full table of pairwise distances between the given words."""
    return [distance_row(word, words) for word in words]


def similarity(s1, s2):
    """Normalised similarity in [0.0, 1.0] derived from the edit distance."""
    longest = max(len(s1), len(s2))
    if longest == 0:
        return 1.0
    return 1.0 - levenshtein_distance(s1, s2) / longest


def closest_words(target, candidates, max_distance=2):
    """Candidates within max_distance edits of target, nearest first."""
    scored = [(levenshtein_distance(target, word), word) for word in candidates]
    near = [pair for pair in scored if pair[0] <= max_distance]
    return sorted(near)


def normalise(words):
    """Strip surrounding blanks and drop empty entries before comparing."""
    stripped = [word.strip() for word in words]
    return [word for word in stripped if word]


def format_row(label, values, width):
    """Render one labelled table row as aligned text."""
    cells = [f"{value:>{width + 2}}" for value in values]
    return f"{label:<{width}}" + "".join(cells)


def format_matrix(words):
    """Render the pairwise distance table as aligned text lines."""
    lengths = [len(word) for word in words]
    width = max(lengths)
    headings = [f"{word:>{width + 2}}" for word in words]
    header = " " * width + "".join(headings)
    matrix = distance_matrix(words)
    rows = [format_row(word, row, width) for word, row in zip(words, matrix)]
    return [header] + rows


def main():
    pairs = [("kitten", "sitting"), ("flaw", "lawn"), ("", "abc"), ("same", "same")]
    for s1, s2 in pairs:
        distance = levenshtein_distance(s1, s2)
        print(f"{s1!r} -> {s2!r}: distance {distance}, similarity {similarity(s1, s2):.2f}")

    vocabulary = normalise([" kitten ", "sitting", "mitten", "", "kitchen", "bitten", "flaw"])
    print()
    for line in format_matrix(vocabulary):
        print(line)

    print()
    suggestions = closest_words("kitten", vocabulary, max_distance=2)
    labels = [f"{word} ({distance})" for distance, word in suggestions]
    print("closest to 'kitten': " + ", ".join(labels))


