import math


def validate_vector(vec):
    """Return vec as a tuple of two floats/ints, raising on bad input."""
    if not isinstance(vec, (tuple, list)) or len(vec) != 2:
        raise ValueError("a 2D vector must have exactly two components")
    bad = [c for c in vec if not isinstance(c, (int, float)) or isinstance(c, bool)]
    if bad:
        raise TypeError("vector components must be numbers, got %r" % (bad[0],))
    return tuple(vec)


def calculate_dot_product(vec1, vec2):
    """Dot product of two 2D vectors given as tuples (x, y)."""
    a = validate_vector(vec1)
    b = validate_vector(vec2)
    return sum([x * y for x, y in zip(a, b)])


def parse_vector(text):
    """Parse '1, 2' or '(1 2)' into a 2D tuple of numbers."""
    cleaned = text.strip().strip("()[]")
    fields = [f.strip() for f in cleaned.replace(",", " ").split()]
    numbers = [float(f) for f in fields]
    whole = [int(n) for n in numbers if n.is_integer()]
    if len(whole) == len(numbers):
        return validate_vector(tuple(whole))
    return validate_vector(tuple(numbers))


