def enqueue(queue, item):
    queue.append(item)


def dequeue(queue):
    if not queue:
        return None
    return queue.pop(0)


def coerce(token):
    try:
        return int(token)
    except ValueError:
        return token


def parse_command(line):
    parts = line.split()
    op = parts[0].lower()
    args = [coerce(token) for token in parts[1:]]
    if op == "enqueue":
        if not args:
            raise ValueError("enqueue needs at least one argument: " + line)
        return op, args
    if op in ("dequeue", "drain", "show"):
        if args:
            raise ValueError(op + " takes no arguments: " + line)
        return op, args
    raise ValueError("unknown command: " + op)


def parse_script(text):
    stripped = [line.strip() for line in text.splitlines()]
    return [parse_command(line) for line in stripped if line and not line.startswith("#")]


def enqueue_all(queue, items):
    for item in items:
        enqueue(queue, item)


def drain(queue):
    emptied = []
    while True:
        item = dequeue(queue)
        if item is None:
            return emptied
        emptied.append(item)


def render(queue):
    cells = ["[%s]" % item for item in queue]
    return "".join(cells) if cells else "(empty)"


def run_script(queue, commands):
    log = []
    for op, args in commands:
        if op == "enqueue":
            enqueue_all(queue, args)
            log.append("enqueued " + ", ".join([str(a) for a in args]))
        elif op == "dequeue":
            log.append("dequeued %r" % dequeue(queue))
        elif op == "drain":
            log.append("drained %r" % drain(queue))
        else:
            log.append("queue " + render(queue))
    return log


def main():
    script = """
    # simple queue session
    enqueue 1 2
    show
    dequeue
    enqueue red green
    drain
    dequeue
    """
    queue = []
    entries = run_script(queue, parse_script(script))
    numbered = ["%2d. %s" % (index, entry) for index, entry in enumerate(entries, 1)]
    for line in numbered:
        print(line)
    print("final state:", render(queue))


if __name__ == "__main__":
    main()

