    sides = [round(float(s), 9) for s in (side1, side2, side3)]
    distinct = len(set(sides))
    if distinct == 1:
        return "equilateral"
    if distinct == 2:
        return "isosceles"
    return "scalene"


def triangle_area(side1, side2, side3):
    perimeter = calculate_triangle_perimeter(side1, side2, side3)
    half = perimeter / 2.0
    factors = [half - s for s in (side1, side2, side3)]
    product = half
    for factor in factors:
