def count_lines_in_text(text):
    """Count the lines in a multi-line string, where lines are separated by '\\n'."""
    if not text:
        return 0
    breaks = [index for index, char in enumerate(text) if char == '\n']
    trailing = 1 if not text.endswith('\n') else 0
    return len(breaks) + trailing


def split_lines(text):
    """Return the individual lines of the text, without their newline characters."""
    if not text:
        return []
    pieces = text.split('\n')
    if pieces and pieces[-1] == '':
        pieces.pop()
    return [piece.rstrip('\r') for piece in pieces]


def non_blank_lines(text):
    """Return the lines that contain at least one non-whitespace character."""
    return [line for line in split_lines(text) if line.strip()]


def line_lengths(text):
    """Return the character length of every line."""
    return [len(line) for line in split_lines(text)]


def word_count(text):
    """Total number of whitespace-separated words across all lines."""
    per_line = [len(line.split()) for line in split_lines(text)]
    return sum(per_line)


def numbered_lines(text, width=None):
    """Return the lines prefixed with right-aligned line numbers."""
